// Document structure analysis shared by all rules.
use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HeadingStyle {
    Atx,
    AtxClosed,
    Setext,
}

#[derive(Debug, Clone)]
pub struct Heading {
    pub line: usize, // 0-based line index of the heading text line
    pub level: usize,
    pub style: HeadingStyle,
    pub text: String,       // trimmed heading text (without markers)
    pub indent: usize,      // leading spaces before marker
    pub text_col: usize,    // 0-based byte column where text starts
    pub underline_line: Option<usize>,
    pub underline_char: char,
    pub closing_hashes: usize, // for atx closed
    pub prefix_len: usize,  // blockquote prefix length (bytes) if any
}

#[derive(Debug, Clone)]
pub struct CodeBlock {
    pub start: usize, // 0-based line of opening fence (or first code line for indented)
    pub end: usize,   // 0-based line of closing fence (or last code line); may equal len-1 if unclosed
    pub fenced: bool,
    pub closed: bool,
    pub fence_char: char,
    pub fence_len: usize,
    pub indent: usize,
    pub info: String, // info string (trimmed)
}

#[derive(Debug, Clone)]
pub struct ListItem {
    pub line: usize,
    pub indent: usize,        // visual column of marker start (after blockquote prefix)
    pub marker: String,       // e.g. "-", "*", "+", "1.", "2)"
    pub ordered: bool,
    pub number: Option<u64>,
    pub spaces_after: usize,  // spaces between marker and content
    pub content_col: usize,   // visual column where content begins
    pub prefix_len: usize,    // byte length of blockquote prefix
    pub marker_byte: usize,   // byte offset in line of marker start
    pub has_content: bool,
}

#[derive(Debug, Clone)]
pub struct RefDef {
    pub line: usize,
    pub label: String, // original label
    pub url: String,
    pub title: Option<String>,
}

#[derive(Debug, Clone)]
pub struct Table {
    pub start: usize,
    pub end: usize, // inclusive
    pub delimiter: usize,
}

#[derive(Debug, Clone, Default)]
pub struct Line {
    pub start: usize,  // byte offset of line start
    pub len: usize,    // byte length of line (without newline)
    pub blank: bool,
    pub indent: usize, // visual indent of raw line
    pub in_code: bool,       // content line inside code block
    pub is_fence: bool,      // opening/closing fence line
    pub in_front_matter: bool, // including delimiters
    pub in_html_block: bool,
    pub in_comment: bool,    // inside html comment (multi-line)
    pub in_math: bool,
    pub bq_depth: usize,
    pub bq_prefix_len: usize, // byte length of blockquote prefix ("> > ")
    pub heading: Option<usize>,
    pub list_item: Option<usize>,
    pub in_table: bool,
    pub is_hr: bool,
    pub in_list: bool, // inside a list (item line or continuation)
}

pub struct Ctx<'a> {
    pub content: &'a str,
    pub lines: Vec<Line>,
    pub raw: Vec<&'a str>, // line text without newline
    pub headings: Vec<Heading>,
    pub code_blocks: Vec<CodeBlock>,
    pub list_items: Vec<ListItem>,
    pub ref_defs: Vec<RefDef>,
    pub tables: Vec<Table>,
    pub front_matter: Option<(usize, usize)>, // inclusive line range
    pub has_crlf: bool,
}

pub fn is_blank(s: &str) -> bool {
    s.trim().is_empty()
}

pub fn visual_indent(s: &str) -> usize {
    let mut col = 0;
    for ch in s.chars() {
        match ch {
            ' ' => col += 1,
            '\t' => col = (col / 4 + 1) * 4,
            _ => break,
        }
    }
    col
}

pub fn leading_ws_bytes(s: &str) -> usize {
    s.len() - s.trim_start_matches([' ', '\t']).len()
}

/// Strip blockquote markers ("> " repeated). Returns (depth, prefix_byte_len, rest)
pub fn strip_blockquote(s: &str) -> (usize, usize, &str) {
    let mut depth = 0;
    let mut pos = 0;
    let bytes = s.as_bytes();
    loop {
        // up to 3 spaces then '>'
        let mut p = pos;
        let mut spaces = 0;
        while p < bytes.len() && bytes[p] == b' ' && spaces < 3 {
            p += 1;
            spaces += 1;
        }
        if p < bytes.len() && bytes[p] == b'>' {
            p += 1;
            if p < bytes.len() && bytes[p] == b' ' {
                p += 1;
            }
            depth += 1;
            pos = p;
        } else {
            break;
        }
    }
    (depth, pos, &s[pos..])
}

/// Parse a list marker at the start of `s` (after indentation). Returns (marker, ordered, number, marker_len)
pub fn parse_list_marker(s: &str) -> Option<(String, bool, Option<u64>, usize)> {
    let bytes = s.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let c = bytes[0];
    if c == b'-' || c == b'*' || c == b'+' {
        if bytes.len() == 1 || bytes[1] == b' ' || bytes[1] == b'\t' {
            return Some(((c as char).to_string(), false, None, 1));
        }
        return None;
    }
    if c.is_ascii_digit() {
        let mut i = 0;
        while i < bytes.len() && bytes[i].is_ascii_digit() && i < 9 {
            i += 1;
        }
        if i < bytes.len() && (bytes[i] == b'.' || bytes[i] == b')') {
            if i + 1 == bytes.len() || bytes[i + 1] == b' ' || bytes[i + 1] == b'\t' {
                let num = s[..i].parse::<u64>().ok();
                return Some((s[..=i].to_string(), true, num, i + 1));
            }
        }
    }
    None
}

pub fn is_hr_line(s: &str) -> bool {
    let t = s.trim();
    if t.len() < 3 {
        return false;
    }
    let first = t.chars().next().unwrap();
    if first != '-' && first != '*' && first != '_' {
        return false;
    }
    let mut count = 0;
    for ch in t.chars() {
        if ch == first {
            count += 1;
        } else if ch != ' ' && ch != '\t' {
            return false;
        }
    }
    count >= 3
}

fn is_fence_open(s: &str) -> Option<(char, usize, String)> {
    let t = s.trim_start_matches(' ');
    let ind = s.len() - t.len();
    if ind > 3 {
        return None;
    }
    let c = t.chars().next()?;
    if c != '`' && c != '~' {
        return None;
    }
    let n = t.chars().take_while(|&x| x == c).count();
    if n < 3 {
        return None;
    }
    let info = t[n..].trim().to_string();
    if c == '`' && info.contains('`') {
        return None;
    }
    Some((c, n, info))
}

fn is_fence_close(s: &str, c: char, n: usize) -> bool {
    let t = s.trim_start_matches(' ');
    let ind = s.len() - t.len();
    if ind > 3 {
        return false;
    }
    let cnt = t.chars().take_while(|&x| x == c).count();
    cnt >= n && t[cnt..].trim().is_empty()
}

fn html_block_start(t: &str) -> Option<usize> {
    // returns kind: 1 = ends with </script|pre|style|textarea>, 2 = comment, 6 = block tags (ends at blank), 7 = other tag alone
    let l = t.to_ascii_lowercase();
    if !l.starts_with('<') {
        return None;
    }
    for tag in ["<script", "<pre", "<style", "<textarea"] {
        if l.starts_with(tag) {
            let rest = &l[tag.len()..];
            if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('>') || rest.starts_with('\t') {
                return Some(1);
            }
        }
    }
    if l.starts_with("<!--") {
        return Some(2);
    }
    if l.starts_with("<?") {
        return Some(3);
    }
    if l.starts_with("<![cdata[") {
        return Some(5);
    }
    if l.starts_with("<!") && l.len() > 2 && l.as_bytes()[2].is_ascii_alphabetic() {
        return Some(4);
    }
    const BLOCK_TAGS: &[&str] = &[
        "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center", "col",
        "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure",
        "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6", "head", "header", "hr",
        "html", "iframe", "legend", "li", "link", "main", "menu", "menuitem", "nav", "noframes", "ol",
        "optgroup", "option", "p", "param", "search", "section", "summary", "table", "tbody", "td", "tfoot",
        "th", "thead", "title", "tr", "track", "ul",
    ];
    let mut rest = &l[1..];
    if rest.starts_with('/') {
        rest = &rest[1..];
    }
    let name: String = rest.chars().take_while(|c| c.is_ascii_alphanumeric()).collect();
    let after = &rest[name.len()..];
    if BLOCK_TAGS.contains(&name.as_str())
        && (after.is_empty() || after.starts_with(' ') || after.starts_with('>') || after.starts_with("/>") || after.starts_with('\t'))
    {
        return Some(6);
    }
    // kind 7: complete open or closing tag alone on the line
    if !name.is_empty() && name.chars().next().unwrap().is_ascii_alphabetic() {
        let re7 = regex::Regex::new(r"^</?[A-Za-z][A-Za-z0-9-]*(\s+[A-Za-z_:][A-Za-z0-9_.:-]*(\s*=\s*([^\s\x22'=<>`]+|'[^']*'|\x22[^\x22]*\x22))?)*\s*/?>\s*$").unwrap();
        if re7.is_match(t) {
            return Some(7);
        }
    }
    None
}

impl<'a> Ctx<'a> {
    pub fn new(content: &'a str) -> Ctx<'a> {
        let has_crlf = content.contains("\r\n");
        let mut raw: Vec<&str> = Vec::new();
        let mut lines: Vec<Line> = Vec::new();
        let mut pos = 0;
        for seg in content.split_inclusive('\n') {
            let mut text = seg;
            if text.ends_with('\n') {
                text = &text[..text.len() - 1];
            }
            if text.ends_with('\r') {
                text = &text[..text.len() - 1];
            }
            lines.push(Line { start: pos, len: text.len(), blank: is_blank(text), indent: visual_indent(text), ..Default::default() });
            raw.push(text);
            pos += seg.len();
        }
        if content.is_empty() || content.ends_with('\n') {
            // trailing empty line representing position after final newline? keep as not a line.
        }
        let mut ctx = Ctx {
            content,
            lines,
            raw,
            headings: Vec::new(),
            code_blocks: Vec::new(),
            list_items: Vec::new(),
            ref_defs: Vec::new(),
            tables: Vec::new(),
            front_matter: None,
            has_crlf,
        };
        ctx.analyze();
        ctx
    }

    pub fn line_count(&self) -> usize {
        self.lines.len()
    }

    pub fn line(&self, i: usize) -> &'a str {
        self.raw[i]
    }

    fn analyze(&mut self) {
        let n = self.lines.len();
        // Front matter
        if n > 0 {
            let first = self.raw[0].trim_end();
            let delim = if first == "---" { Some("---") } else if first == "+++" { Some("+++") } else { None };
            if let Some(d) = delim {
                let mut end = None;
                for i in 1..n {
                    let t = self.raw[i].trim_end();
                    if t == d || (d == "---" && t == "...") {
                        end = Some(i);
                        break;
                    }
                }
                if let Some(e) = end {
                    self.front_matter = Some((0, e));
                    for i in 0..=e {
                        self.lines[i].in_front_matter = true;
                    }
                }
            }
        }

        // Blockquote prefixes
        for i in 0..n {
            let (d, plen, _) = strip_blockquote(self.raw[i]);
            self.lines[i].bq_depth = d;
            self.lines[i].bq_prefix_len = plen;
        }

        // Code blocks (fenced + indented), HTML blocks, comments
        let mut i = 0;
        let mut in_html = false;
        let mut html_kind = 0;
        let mut in_comment = false;
        let mut list_content_indent: Option<usize> = None; // content indent of the innermost active list item
        let mut prev_blank = true;
        let mut in_math = false;
        while i < n {
            if self.lines[i].in_front_matter {
                i += 1;
                continue;
            }
            let rawl = self.raw[i];
            let (_, plen, rest) = strip_blockquote(rawl);
            let _ = plen;
            if in_comment {
                self.lines[i].in_comment = true;
                if rawl.contains("-->") {
                    in_comment = false;
                }
                i += 1;
                prev_blank = false;
                continue;
            }
            if in_html {
                self.lines[i].in_html_block = true;
                let l = rawl.to_ascii_lowercase();
                let ends = match html_kind {
                    1 => l.contains("</script>") || l.contains("</pre>") || l.contains("</style>") || l.contains("</textarea>"),
                    2 => l.contains("-->"),
                    3 => l.contains("?>"),
                    4 => l.contains('>'),
                    5 => l.contains("]]>"),
                    _ => false,
                };
                if ends {
                    in_html = false;
                } else if (html_kind == 6 || html_kind == 7) && self.lines[i].blank {
                    in_html = false;
                    self.lines[i].in_html_block = false;
                }
                i += 1;
                prev_blank = self.lines[i - 1].blank;
                continue;
            }
            if in_math {
                self.lines[i].in_math = true;
                if rest.trim().starts_with("$$") {
                    in_math = false;
                }
                i += 1;
                prev_blank = false;
                continue;
            }
            // Fenced code block
            if let Some((c, len, info)) = is_fence_open(rest) {
                let indent = visual_indent(rest);
                let start = i;
                self.lines[i].is_fence = true;
                let mut j = i + 1;
                let mut closed = false;
                while j < n {
                    let (_, _, r) = strip_blockquote(self.raw[j]);
                    if is_fence_close(r, c, len) {
                        closed = true;
                        break;
                    }
                    self.lines[j].in_code = true;
                    j += 1;
                }
                let end = if closed { self.lines[j].is_fence = true; j } else { n - 1 };
                self.code_blocks.push(CodeBlock { start, end, fenced: true, closed, fence_char: c, fence_len: len, indent, info });
                i = end + 1;
                prev_blank = false;
                list_content_indent = None;
                continue;
            }
            // Math block
            if rest.trim_start().starts_with("$$") && rest.trim() == "$$" {
                in_math = true;
                self.lines[i].in_math = true;
                i += 1;
                prev_blank = false;
                continue;
            }
            // Blank line
            if self.lines[i].blank {
                prev_blank = true;
                i += 1;
                continue;
            }
            let ind = visual_indent(rest);
            // list item?
            let trimmed = rest.trim_start_matches([' ', '\t']);
            if let Some((_m, _o, _num, mlen)) = parse_list_marker(trimmed) {
                if ind < list_content_indent.map(|c| c + 4).unwrap_or(4) {
                    // list item line
                    let after = &trimmed[mlen..];
                    let sp = after.len() - after.trim_start_matches([' ', '\t']).len();
                    let content_col = if after.trim().is_empty() { ind + mlen + 1 } else if sp > 4 { ind + mlen + 1 } else { ind + mlen + sp };
                    list_content_indent = Some(content_col);
                    prev_blank = false;
                    i += 1;
                    continue;
                }
            }
            // Indented code block
            let code_threshold = match list_content_indent {
                Some(c) if ind >= c => c + 4,
                Some(_) => 4,
                None => 4,
            };
            if ind >= code_threshold && prev_blank {
                let start = i;
                let mut j = i;
                let mut last = i;
                while j < n {
                    let (_, _, r) = strip_blockquote(self.raw[j]);
                    if self.lines[j].blank {
                        j += 1;
                        continue;
                    }
                    if visual_indent(r) >= code_threshold {
                        last = j;
                        j += 1;
                    } else {
                        break;
                    }
                }
                for k in start..=last {
                    self.lines[k].in_code = true;
                }
                self.code_blocks.push(CodeBlock { start, end: last, fenced: false, closed: true, fence_char: ' ', fence_len: 0, indent: code_threshold, info: String::new() });
                i = last + 1;
                prev_blank = false;
                continue;
            }
            // HTML block
            if ind < 4 {
                if let Some(kind) = html_block_start(trimmed) {
                    if kind == 2 {
                        // comment
                        self.lines[i].in_comment = true;
                        if !rawl[rawl.find("<!--").unwrap() + 4..].contains("-->") {
                            in_comment = true;
                        }
                        i += 1;
                        prev_blank = false;
                        continue;
                    }
                    self.lines[i].in_html_block = true;
                    let l = rawl.to_ascii_lowercase();
                    let ends_now = match kind {
                        1 => l.contains("</script>") || l.contains("</pre>") || l.contains("</style>") || l.contains("</textarea>"),
                        3 => l.contains("?>"),
                        4 => l[2..].contains('>'),
                        5 => l.contains("]]>"),
                        _ => false,
                    };
                    if !ends_now {
                        in_html = true;
                        html_kind = kind;
                    }
                    i += 1;
                    prev_blank = false;
                    continue;
                }
            }
            if list_content_indent.is_some() && prev_blank && ind == 0 {
                list_content_indent = None;
            }
            prev_blank = false;
            i += 1;
        }

        self.analyze_headings();
        self.analyze_lists();
        self.analyze_tables();
        self.analyze_refdefs();
        for i in 0..n {
            if is_hr_line(self.raw[i]) && !self.skip_line(i) && self.lines[i].heading.is_none() && self.lines[i].list_item.is_none() && visual_indent(self.raw[i]) < 4 {
                // ensure it is not a setext underline
                let is_underline = i > 0 && self.lines[i - 1].heading.map(|h| self.headings[h].underline_line == Some(i)).unwrap_or(false);
                if !is_underline {
                    self.lines[i].is_hr = true;
                }
            }
        }
    }

    /// true if the line should be skipped by most rules (code, front matter, html block, comment)
    pub fn skip_line(&self, i: usize) -> bool {
        let l = &self.lines[i];
        l.in_code || l.is_fence || l.in_front_matter || l.in_math
    }

    pub fn in_code_or_fence(&self, i: usize) -> bool {
        self.lines[i].in_code || self.lines[i].is_fence
    }

    fn analyze_headings(&mut self) {
        let n = self.lines.len();
        let mut i = 0;
        while i < n {
            if self.skip_line(i) || self.lines[i].in_html_block || self.lines[i].in_comment || self.lines[i].blank {
                i += 1;
                continue;
            }
            let rawl = self.raw[i];
            let (_, plen, rest) = strip_blockquote(rawl);
            let ind = rest.len() - rest.trim_start_matches(' ').len();
            let t = &rest[ind..];
            if t.starts_with('#') && visual_indent(rest) < 4 {
                let hashes = t.chars().take_while(|&c| c == '#').count();
                if hashes <= 6 {
                    let after = &t[hashes..];
                    // valid atx requires space or end; rumdl also treats "#Heading" as heading (MD018)
                    let valid = after.is_empty() || after.starts_with(' ') || after.starts_with('\t');
                    let looks_like_heading = valid || (!after.starts_with('#') && after.chars().next().map(|c| !c.is_whitespace()).unwrap_or(false) && !is_hr_line(t));
                    if looks_like_heading {
                        let (text, style, closing, text_col) = parse_atx(t, hashes, ind + plen);
                        let idx = self.headings.len();
                        self.headings.push(Heading {
                            line: i,
                            level: hashes,
                            style,
                            text,
                            indent: ind,
                            text_col,
                            underline_line: None,
                            underline_char: ' ',
                            closing_hashes: closing,
                            prefix_len: plen,
                        });
                        self.lines[i].heading = Some(idx);
                        i += 1;
                        continue;
                    }
                }
            }
            // setext: this line is a paragraph line and next line is === or ---
            if i + 1 < n && !self.lines[i + 1].blank && !self.skip_line(i + 1) {
                let (_, _plen2, rest2) = strip_blockquote(self.raw[i + 1]);
                let t2 = rest2.trim();
                let ind2 = visual_indent(rest2);
                if ind2 < 4 && !t2.is_empty() && (t2.chars().all(|c| c == '=') || t2.chars().all(|c| c == '-')) {
                    // previous line must be paragraph text (not list item, not heading, not blank)
                    let is_para = !t.is_empty() && visual_indent(rest) < 4 && parse_list_marker(t).is_none() && !is_hr_line(t) && !t.starts_with('>') && {
                        // previous line must be blank or paragraph (not list item etc.)
                        let prev_ok = i == 0 || self.lines[i - 1].blank || (self.lines[i - 1].heading.is_none() && !self.skip_line(i - 1));
                        prev_ok
                    } && !(i > 0 && !self.lines[i - 1].blank && self.lines[i - 1].list_item.is_some());
                    // Ensure it's not within a list item continuation
                    if is_para {
                        let c = t2.chars().next().unwrap();
                        let level = if c == '=' { 1 } else { 2 };
                        let idx = self.headings.len();
                        self.headings.push(Heading {
                            line: i,
                            level,
                            style: HeadingStyle::Setext,
                            text: t.trim().to_string(),
                            indent: ind,
                            text_col: ind + plen,
                            underline_line: Some(i + 1),
                            underline_char: c,
                            closing_hashes: 0,
                            prefix_len: plen,
                        });
                        self.lines[i].heading = Some(idx);
                        i += 2;
                        continue;
                    }
                }
            }
            i += 1;
        }
    }

    fn analyze_lists(&mut self) {
        let n = self.lines.len();
        let mut in_list = false;
        let mut last_content_col = 0usize;
        for i in 0..n {
            if self.skip_line(i) || self.lines[i].in_html_block || self.lines[i].heading.is_some() || self.lines[i].in_comment {
                if !self.lines[i].in_code {
                    in_list = false;
                }
                continue;
            }
            if self.lines[i].blank {
                continue;
            }
            let rawl = self.raw[i];
            let (_, plen, rest) = strip_blockquote(rawl);
            let ind = visual_indent(rest);
            let ws = leading_ws_bytes(rest);
            let t = &rest[ws..];
            if is_hr_line(t) && !(t.starts_with('-') || t.starts_with('*')) {
                in_list = false;
                continue;
            }
            if let Some((marker, ordered, number, mlen)) = parse_list_marker(t) {
                if is_hr_line(t) {
                    in_list = false;
                    continue;
                }
                let code_threshold = if in_list { last_content_col + 4 } else { 4 };
                if ind >= code_threshold && (i == 0 || self.lines[i - 1].blank) {
                    continue; // indented code handled elsewhere
                }
                let after = &t[mlen..];
                let sp = after.len() - after.trim_start_matches([' ', '\t']).len();
                let has_content = !after.trim().is_empty();
                let content_col = if !has_content || sp > 4 { ind + mlen + 1 } else { ind + mlen + sp };
                let idx = self.list_items.len();
                self.list_items.push(ListItem {
                    line: i,
                    indent: ind,
                    marker,
                    ordered,
                    number,
                    spaces_after: sp,
                    content_col,
                    prefix_len: plen,
                    marker_byte: plen + ws,
                    has_content,
                });
                self.lines[i].list_item = Some(idx);
                self.lines[i].in_list = true;
                in_list = true;
                last_content_col = content_col;
                continue;
            }
            if in_list {
                // continuation if indented at least to content col, or lazy continuation (previous line non-blank)
                if ind >= 1 && ind >= last_content_col.min(ind) && (ind >= 2 || (i > 0 && !self.lines[i - 1].blank)) {
                    self.lines[i].in_list = true;
                } else if i > 0 && !self.lines[i - 1].blank {
                    self.lines[i].in_list = true; // lazy continuation
                } else {
                    in_list = false;
                }
            }
        }
    }

    fn analyze_tables(&mut self) {
        let n = self.lines.len();
        let mut i = 0;
        while i + 1 < n {
            if self.skip_line(i) || self.lines[i].blank || self.lines[i].heading.is_some() || self.lines[i].in_html_block {
                i += 1;
                continue;
            }
            let (_, _, r0) = strip_blockquote(self.raw[i]);
            let (_, _, r1) = strip_blockquote(self.raw[i + 1]);
            if r0.contains('|') && is_delimiter_row(r1) && !self.skip_line(i + 1) {
                let header_cells = split_cells(r0).len();
                let delim_cells = split_cells(r1).len();
                if header_cells == delim_cells || (header_cells > 0 && delim_cells > 0) {
                    // table starts at i
                    let start = i;
                    let mut end = i + 1;
                    let mut j = i + 2;
                    while j < n {
                        let (_, _, rj) = strip_blockquote(self.raw[j]);
                        if self.lines[j].blank || self.skip_line(j) || !rj.contains('|') {
                            break;
                        }
                        if rj.trim_start().starts_with('#') {
                            break;
                        }
                        end = j;
                        j += 1;
                    }
                    for k in start..=end {
                        self.lines[k].in_table = true;
                    }
                    self.tables.push(Table { start, end, delimiter: i + 1 });
                    i = end + 1;
                    continue;
                }
            }
            i += 1;
        }
    }

    fn analyze_refdefs(&mut self) {
        let re = regex::Regex::new(r#"^ {0,3}\[([^\]]+)\]:\s*(<[^>]*>|\S+)(?:\s+("[^"]*"|'[^']*'|\([^)]*\)))?\s*$"#).unwrap();
        for i in 0..self.lines.len() {
            if self.skip_line(i) || self.lines[i].in_html_block {
                continue;
            }
            let (_, _, rest) = strip_blockquote(self.raw[i]);
            if let Some(c) = re.captures(rest) {
                let label = c.get(1).unwrap().as_str().to_string();
                if label.starts_with('^') {
                    continue; // footnote
                }
                let mut url = c.get(2).unwrap().as_str().to_string();
                if url.starts_with('<') && url.ends_with('>') {
                    url = url[1..url.len() - 1].to_string();
                }
                let title = c.get(3).map(|m| {
                    let s = m.as_str();
                    s[1..s.len() - 1].to_string()
                });
                self.ref_defs.push(RefDef { line: i, label, url, title });
            }
        }
    }

    pub fn is_refdef_line(&self, i: usize) -> bool {
        self.ref_defs.iter().any(|r| r.line == i)
    }

    pub fn code_block_at(&self, line: usize) -> Option<&CodeBlock> {
        self.code_blocks.iter().find(|cb| cb.start <= line && line <= cb.end)
    }

    pub fn heading_at(&self, line: usize) -> Option<&Heading> {
        self.lines[line].heading.map(|h| &self.headings[h])
    }

    pub fn list_item_at(&self, line: usize) -> Option<&ListItem> {
        self.lines[line].list_item.map(|h| &self.list_items[h])
    }

    /// Byte offset for (0-based line, 0-based byte column)
    pub fn offset(&self, line: usize, col: usize) -> usize {
        if line >= self.lines.len() {
            return self.content.len();
        }
        self.lines[line].start + col
    }

    /// byte offset of the end of line (before newline)
    pub fn line_end(&self, line: usize) -> usize {
        self.lines[line].start + self.lines[line].len
    }

    /// Offset of start of the next line (after newline), or content len
    pub fn next_line_start(&self, line: usize) -> usize {
        if line + 1 < self.lines.len() {
            self.lines[line + 1].start
        } else {
            self.content.len()
        }
    }

    pub fn ref_def_map(&self) -> HashMap<String, &RefDef> {
        let mut m = HashMap::new();
        for r in &self.ref_defs {
            m.entry(normalize_label(&r.label)).or_insert(r);
        }
        m
    }
}

pub fn normalize_label(s: &str) -> String {
    s.trim().to_lowercase().split_whitespace().collect::<Vec<_>>().join(" ")
}

fn parse_atx(t: &str, hashes: usize, base_col: usize) -> (String, HeadingStyle, usize, usize) {
    // t starts with hashes
    let after = &t[hashes..];
    let sp = after.len() - after.trim_start_matches([' ', '\t']).len();
    let content = &after[sp..];
    let text_col = base_col + hashes + sp;
    // closed?
    let trimmed_end = content.trim_end();
    let mut text = trimmed_end.to_string();
    let mut style = HeadingStyle::Atx;
    let mut closing = 0;
    if !trimmed_end.is_empty() {
        let closing_run = trimmed_end.chars().rev().take_while(|&c| c == '#').count();
        if closing_run > 0 {
            let before = &trimmed_end[..trimmed_end.len() - closing_run];
            if before.is_empty() {
                // "## ##" -> closed heading with empty text? treat as closed
                style = HeadingStyle::AtxClosed;
                closing = closing_run;
                text = String::new();
            } else if before.ends_with(' ') || before.ends_with('\t') {
                style = HeadingStyle::AtxClosed;
                closing = closing_run;
                text = before.trim_end().to_string();
            } else if before.chars().last().map(|c| c != '\\').unwrap_or(false) {
                // "Heading##" -> rumdl treats as closed heading missing space (MD020)
                style = HeadingStyle::AtxClosed;
                closing = closing_run;
                text = before.to_string();
            }
        }
    }
    (text, style, closing, text_col)
}

pub fn is_delimiter_row(s: &str) -> bool {
    let t = s.trim();
    if !t.contains('-') {
        return false;
    }
    let cells = split_cells(t);
    if cells.is_empty() {
        return false;
    }
    let re = regex::Regex::new(r"^:?-+:?$").unwrap();
    if !t.contains('|') {
        return false;
    }
    cells.iter().all(|c| {
        let c = c.trim();
        !c.is_empty() && re.is_match(c)
    })
}

/// Split a table row into cells (ignoring leading/trailing pipes). Handles escaped pipes and code spans.
pub fn split_cells(s: &str) -> Vec<String> {
    let mut t = s.trim();
    if t.starts_with('|') {
        t = &t[1..];
    }
    if t.ends_with('|') && !t.ends_with("\\|") {
        t = &t[..t.len() - 1];
    }
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut chars = t.chars().peekable();
    let mut in_code = 0usize;
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&nx) = chars.peek() {
                cur.push(c);
                cur.push(nx);
                chars.next();
                continue;
            }
        }
        if c == '`' {
            let mut run = 1;
            while chars.peek() == Some(&'`') {
                chars.next();
                run += 1;
            }
            if in_code == 0 {
                in_code = run;
            } else if in_code == run {
                in_code = 0;
            }
            for _ in 0..run {
                cur.push('`');
            }
            continue;
        }
        if c == '|' && in_code == 0 {
            cells.push(cur.clone());
            cur.clear();
        } else {
            cur.push(c);
        }
    }
    cells.push(cur);
    cells
}
