// Document structure analysis shared by all rules.
use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HeadingStyle {
    Atx,
    AtxClosed,
    Setext,
}

#[derive(Debug, Clone)]
pub struct Heading {
    pub line: usize, // 0-based line index of the heading text line
    pub level: usize,
    pub style: HeadingStyle,
    pub text: String,       // trimmed heading text (without markers)
    pub indent: usize,      // leading spaces before marker
    pub text_col: usize,    // 0-based byte column where text starts
    pub underline_line: Option<usize>,
    pub underline_char: char,
    pub closing_hashes: usize, // for atx closed
    pub prefix_len: usize,  // blockquote prefix length (bytes) if any
}

#[derive(Debug, Clone)]
pub struct CodeBlock {
    pub start: usize, // 0-based line of opening fence (or first code line for indented)
    pub end: usize,   // 0-based line of closing fence (or last code line); may equal len-1 if unclosed
    pub fenced: bool,
    pub closed: bool,
    pub fence_char: char,
    pub fence_len: usize,
    pub indent: usize,
    pub info: String, // info string (trimmed)
}

#[derive(Debug, Clone)]
pub struct ListItem {
    pub line: usize,
    pub indent: usize,        // visual column of marker start (after blockquote prefix)
    pub marker: String,       // e.g. "-", "*", "+", "1.", "2)"
    pub ordered: bool,
    pub number: Option<u64>,
    pub spaces_after: usize,  // spaces between marker and content
    pub content_col: usize,   // visual column where content begins
    pub prefix_len: usize,    // byte length of blockquote prefix
    pub marker_byte: usize,   // byte offset in line of marker start
    pub has_content: bool,
}

#[derive(Debug, Clone)]
pub struct RefDef {
    pub line: usize,
    pub label: String, // original label
    pub url: String,
    pub title: Option<String>,
}

#[derive(Debug, Clone)]
pub struct Table {
    pub start: usize,
    pub end: usize, // inclusive
    pub delimiter: usize,
}

#[derive(Debug, Clone, Default)]
pub struct Line {
    pub start: usize,  // byte offset of line start
    pub len: usize,    // byte length of line (without newline)
    pub blank: bool,
    pub indent: usize, // visual indent of raw line
    pub in_code: bool,       // content line inside code block
    pub is_fence: bool,      // opening/closing fence line
    pub in_front_matter: bool, // including delimiters
    pub in_html_block: bool,
    pub in_comment: bool,    // inside html comment (multi-line)
    pub in_math: bool,
    pub bq_depth: usize,
    pub bq_prefix_len: usize, // byte length of blockquote prefix ("> > ")
    pub heading: Option<usize>,
    pub list_item: Option<usize>,
    pub in_table: bool,
    pub is_hr: bool,
    pub in_list: bool, // inside a list (item line or continuation)
}

pub struct Ctx<'a> {
    pub content: &'a str,
    pub lines: Vec<Line>,
    pub raw: Vec<&'a str>, // line text without newline
    pub headings: Vec<Heading>,
    pub code_blocks: Vec<CodeBlock>,
    pub list_items: Vec<ListItem>,
    pub ref_defs: Vec<RefDef>,
    pub tables: Vec<Table>,
    pub front_matter: Option<(usize, usize)>, // inclusive line range
    pub has_crlf: bool,
}

pub fn is_blank(s: &str) -> bool {
    s.trim().is_empty()
}

pub fn visual_indent(s: &str) -> usize {
    let mut col = 0;
    for ch in s.chars() {
        match ch {
            ' ' => col += 1,
            '\t' => col = (col / 4 + 1) * 4,
            _ => break,
        }
    }
    col
}

pub fn leading_ws_bytes(s: &str) -> usize {
    s.len() - s.trim_start_matches([' ', '\t']).len()
}

/// Strip blockquote markers ("> " repeated). Returns (depth, prefix_byte_len, rest)
pub fn strip_blockquote(s: &str) -> (usize, usize, &str) {
    let mut depth = 0;
    let mut pos = 0;
    let bytes = s.as_bytes();
    loop {
        // up to 3 spaces then '>'
        let mut p = pos;
        let mut spaces = 0;
        while p < bytes.len() && bytes[p] == b' ' && spaces < 3 {
            p += 1;
            spaces += 1;
        }
        if p < bytes.len() && bytes[p] == b'>' {
            p += 1;
            if p < bytes.len() && bytes[p] == b' ' {
                p += 1;
            }
            depth += 1;
            pos = p;
        } else {
            break;
        }
    }
    (depth, pos, &s[pos..])
}

/// Parse a list marker at the start of `s` (after indentation). Returns (marker, ordered, number, marker_len)
pub fn parse_list_marker(s: &str) -> Option<(String, bool, Option<u64>, usize)> {
    let bytes = s.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let c = bytes[0];
    if c == b'-' || c == b'*' || c == b'+' {
        if bytes.len() == 1 || bytes[1] == b' ' || bytes[1] == b'\t' {
            return Some(((c as char).to_string(), false, None, 1));
        }
        return None;
    }
    if c.is_ascii_digit() {
        let mut i = 0;
        while i < bytes.len() && bytes[i].is_ascii_digit() && i < 9 {
            i += 1;
        }
        if i < bytes.len() && (bytes[i] == b'.' || bytes[i] == b')') {
            if i + 1 == bytes.len() || bytes[i + 1] == b' ' || bytes[i + 1] == b'\t' {
                let num = s[..i].parse::<u64>().ok();
                return Some((s[..=i].to_string(), true, num, i + 1));
            }
        }
    }
    None
}

pub fn is_hr_line(s: &str) -> bool {
    let t = s.trim();
    if t.len() < 3 {
        return false;
    }
    let first = t.chars().next().unwrap();
    if first != '-' && first != '*' && first != '_' {
        return false;
    }
    let mut count = 0;
    for ch in t.chars() {
        if ch == first {
            count += 1;
        } else if ch != ' ' && ch != '\t' {
            return false;
        }
    }
    count >= 3
}

fn is_fence_open(s: &str) -> Option<(char, usize, String)> {
    let t = s.trim_start_matches(' ');
    let ind = s.len() - t.len();
    if ind > 3 {
        return None;
    }
    let c = t.chars().next()?;
    if c != '`' && c != '~' {
        return None;
    }
    let n = t.chars().take_while(|&x| x == c).count();
    if n < 3 {
        return None;
    }
    let info = t[n..].trim().to_string();
    if c == '`' && info.contains('`') {
        return None;
    }
    Some((c, n, info))
}

fn is_fence_close(s: &str, c: char, n: usize) -> bool {
    let t = s.trim_start_matches(' ');
    let ind = s.len() - t.len();
    if ind > 3 {
        return false;
    }
    let cnt = t.chars().take_while(|&x| x == c).count();
    cnt >= n && t[cnt..].trim().is_empty()
}

fn html_block_start(t: &str) -> Option<usize> {
    // returns kind: 1 = ends with </script|pre|style|textarea>, 2 = comment, 6 = block tags (ends at blank), 7 = other tag alone
    let l = t.to_ascii_lowercase();
    if !l.starts_with('<') {
        return None;
    }
    for tag in ["<script", "<pre", "<style", "<textarea"] {
        if l.starts_with(tag) {
            let rest = &l[tag.len()..];
            if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('>') || rest.starts_with('\t') {
                return Some(1);
            }
        }
    }
    if l.starts_with("<!--") {
        return Some(2);
    }
    if l.starts_with("<?") {
        return Some(3);
    }
    if l.starts_with("<![cdata[") {
        return Some(5);
    }
    if l.starts_with("<!") && l.len() > 2 && l.as_bytes()[2].is_ascii_alphabetic() {
        return Some(4);
    }
    const BLOCK_TAGS: &[&str] = &[
        "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center", "col",
        "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure",
        "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6", "head", "header", "hr",
        "html", "iframe", "legend", "li", "link", "main", "menu", "menuitem", "nav", "noframes", "ol",
        "optgroup", "option", "p", "param", "search", "section", "summary", "table", "tbody", "td", "tfoot",
        "th", "thead", "title", "tr", "track", "ul",
    ];
    let mut rest = &l[1..];
    if rest.starts_with('/') {
        rest = &rest[1..];
    }
    let name: String = rest.chars().take_while(|c| c.is_ascii_alphanumeric()).collect();
    let after = &rest[name.len()..];
    if BLOCK_TAGS.contains(&name.as_str())
        && (after.is_empty() || after.starts_with(' ') || after.starts_with('>') || after.starts_with("/>") || after.starts_with('\t'))
    {
        return Some(6);
    }
    // kind 7: complete open or closing tag alone on the line
    if !name.is_empty() && name.chars().next().unwrap().is_ascii_alphabetic() {
        let re7 = regex::Regex::new(r"^</?[A-Za-z][A-Za-z0-9-]*(\s+[A-Za-z_:][A-Za-z0-9_.:-]*(\s*=\s*([^\s\x22'=<>`]+|'[^']*'|\x22[^\x22]*\x22))?)*\s*/?>\s*$").unwrap();
        if re7.is_match(t) {
            return Some(7);
        }
    }
    None
}

impl<'a> Ctx<'a> {
    pub fn new(content: &'a str) -> Ctx<'a> {
        let has_crlf = content.contains("\r\n");
        let mut raw: Vec<&str> = Vec::new();
        let mut lines: Vec<Line> = Vec::new();
        let mut pos = 0;
        for seg in content.split_inclusive('\n') {
            let mut text = seg;
            if text.ends_with('\n') {
                text = &text[..text.len() - 1];
            }
            if text.ends_with('\r') {
                text = &text[..text.len() - 1];
            }
            lines.push(Line { start: pos, len: text.len(), blank: is_blank(text), indent: visual_indent(text), ..Default::default() });
            raw.push(text);
            pos += seg.len();
        }
        if content.is_empty() || content.ends_with('\n') {
            // trailing empty line representing position after final newline? keep as not a line.
        }
        let mut ctx = Ctx {
            content,
            lines,
            raw,
            headings: Vec::new(),
            code_blocks: Vec::new(),
            list_items: Vec::new(),
            ref_defs: Vec::new(),
            tables: Vec::new(),
            front_matter: None,
            has_crlf,
        };
        ctx.analyze();
        ctx
    }

    pub fn line_count(&self) -> usize {
        self.lines.len()
    }

    pub fn line(&self, i: usize) -> &'a str {
        self.raw[i]
    }

    fn analyze(&mut self) {
        let n = self.lines.len();
        // Front matter
        if n > 0 {
            let first = self.raw[0].trim_end();
            let delim = if first == "---" { Some("---") } else if first == "+++" { Some("+++") } else { None };
            if let Some(d) = delim {
                let mut end = None;
                for i in 1..n {
                    let t = self.raw[i].trim_end();
                    if t == d || (d == "---" && t == "...") {
                        end = Some(i);
                        break;
                    }
                }
                if let Some(e) = end {
                    self.front_matter = Some((0, e));
                    for i in 0..=e {
                        self.lines[i].in_front_matter = true;
                    }
                }
            }
        }

        // Blockquote prefixes
        for i in 0..n {
            let (d, plen, _) = strip_blockquote(self.raw[i]);
            self.lines[i].bq_depth = d;
            self.lines[i].bq_prefix_len = plen;
        }

        // Code blocks (fenced + indented), HTML blocks, comments
        let mut i = 0;
        let mut in_html = false;
        let mut html_kind = 0;
        let mut in_comment = false;
        let mut list_content_indent: Option<usize> = None; // content indent of the innermost active list item
        let mut prev_blank = true;
        let mut in_math = false;
        while i < n {
            if self.lines[i].in_front_matter {
                i += 1;
                continue;
            }
            let rawl = self.raw[i];
            let (_, plen, rest) = strip_blockquote(rawl);
            let _ = plen;
            if in_comment {
                self.lines[i].in_comment = true;
                if rawl.contains("-->") {
                    in_comment = false;
                }
                i += 1;
                prev_blank = false;
                continue;
            }
            if in_html {
                self.lines[i].in_html_block = true;
                let l = rawl.to_ascii_lowercase();
                let ends = match html_kind {
                    1 => l.contains("</script>") || l.contains("</pre>") || l.contains("</style>") || l.contains("</textarea>"),
                    2 => l.contains("-->"),
                    3 => l.contains("?>"),
                    4 => l.contains('>'),
                    5 => l.contains("]]>"),
                    _ => false,
                };
                if ends {
                    in_html = false;
                } else if (html_kind == 6 || html_kind == 7) && self.lines[i].blank {
                    in_html = false;
                    self.lines[i].in_html_block = false;
                }
                i += 1;
                prev_blank = self.lines[i - 1].blank;
                continue;
            }
            if in_math {
                self.lines[i].in_math = true;
                if rest.trim().starts_with("$$") {
                    in_math = false;
                }
                i += 1;
                prev_blank = false;
                continue;
            }
            // Fenced code block
            if let Some((c, len, info)) = is_fence_open(rest) {
                let indent = visual_indent(rest);
                let start = i;
                self.lines[i].is_fence = true;
                let mut j = i + 1;
                let mut closed = false;
                while j < n {
                    let (_, _, r) = strip_blockquote(self.raw[j]);
                    if is_fence_close(r, c, len) {
                        closed = true;
                        break;
                    }
                    self.lines[j].in_code = true;
                    j += 1;
                }
                let end = if closed { self.lines[j].is_fence = true; j } else { n - 1 };
                self.code_blocks.push(CodeBlock { start, end, fenced: true, closed, fence_char: c, fence_len: len, indent, info });
                i = end + 1;
                prev_blank = false;
                list_content_indent = None;
                continue;
            }
            // Math block
            if rest.trim_start().starts_with("$$") && rest.trim() == "$$" {
                in_math = true;
                self.lines[i].in_math = true;
                i += 1;
                prev_blank = false;
                continue;
            }
            // Blank line
            if self.lines[i].blank {
                prev_blank = true;
                i += 1;
