                }
            }
            if let Some(j) = found {
                res.push(Span { start: i, end: j + n });
                i = j + n;
            } else {
                i += n;
            }
            continue;
        }
        i += 1;
    }
    res
}

pub fn in_spans(spans: &[Span], pos: usize) -> bool {
    spans.iter().any(|sp| pos >= sp.start && pos < sp.end)
}

#[derive(Debug, Clone, PartialEq)]
pub enum LinkKind {
    Inline,    // [text](url)
    Full,      // [text][ref]
    Collapsed, // [text][]
    Shortcut,  // [text]
    Autolink,  // <http://...>
}

#[derive(Debug, Clone)]
pub struct Link {
    pub start: usize,
    pub end: usize,
    pub text: String,
    pub text_start: usize,
    pub text_end: usize,
    pub url: String,
    pub url_start: usize,
    pub url_end: usize,
    pub title: Option<String>,
    pub reference: Option<String>,
    pub image: bool,
    pub kind: LinkKind,
}

fn find_matching_bracket(b: &[u8], open: usize) -> Option<usize> {
    // b[open] == '['; find matching ']' with nesting, skipping escapes and code spans
    let mut depth = 0;
    let mut i = open;
    while i < b.len() {
        match b[i] {
            b'\\' => {
                i += 2;
                continue;
            }
            b'`' => {
                let mut n = 0;
                while i + n < b.len() && b[i + n] == b'`' {
                    n += 1;
                }
                // find closing
                let mut j = i + n;
                let mut closed = None;
                while j < b.len() {
                    if b[j] == b'`' {
                        let mut m = 0;
                        while j + m < b.len() && b[j + m] == b'`' {
                            m += 1;
                        }
                        if m == n {
                            closed = Some(j + m);
                            break;
                        }
                        j += m;
                    } else {
                        j += 1;
                    }
                }
                if let Some(c) = closed {
                    i = c;
                } else {
                    i += n;
                }
                continue;
            }
            b'[' => depth += 1,
            b']' => {
                depth -= 1;
                if depth == 0 {
                    return Some(i);
                }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

/// Parse inline destination starting at b[pos] == '('. Returns (url, url_start, url_end, title, end_of_paren)
fn parse_inline_dest(s: &str, pos: usize) -> Option<(String, usize, usize, Option<String>, usize)> {
    let b = s.as_bytes();
    if pos >= b.len() || b[pos] != b'(' {
        return None;
    }
    let mut i = pos + 1;
    let mut ws_before = 0;
    while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
        i += 1;
        ws_before += 1;
    }
    let _ = ws_before;
    let url_start = i;
    let url_end;
    if i < b.len() && b[i] == b'<' {
        let mut j = i + 1;
        while j < b.len() && b[j] != b'>' && b[j] != b'\n' {
            if b[j] == b'\\' {
                j += 1;
            }
            j += 1;
        }
        if j >= b.len() {
            return None;
        }
        url_end = j + 1;
        i = j + 1;
    } else {
        let mut depth = 0;
        let mut j = i;
        while j < b.len() {
            let c = b[j];
            if c == b'\\' {
                j += 2;
                continue;
            }
            if c == b'(' {
                depth += 1;
            } else if c == b')' {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            } else if c == b' ' || c == b'\t' {
                break;
            } else if c < 0x20 {
                return None;
            }
            j += 1;
        }
        if j > b.len() {
            return None;
        }
        url_end = j;
        i = j;
    }
    // whitespace
    let mut ws_after_start = i;
    while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
        i += 1;
    }
    let had_ws = i > ws_after_start;
    let mut title = None;
    if i < b.len() && (b[i] == b'"' || b[i] == b'\'' || b[i] == b'(') {
        if !had_ws && url_end != url_start {
            return None;
        }
        let close = match b[i] {
            b'"' => b'"',
            b'\'' => b'\'',
            _ => b')',
        };
        let mut j = i + 1;
        while j < b.len() && b[j] != close {
            if b[j] == b'\\' {
                j += 1;
            }
            j += 1;
        }
        if j >= b.len() {
            return None;
        }
        title = Some(s[i + 1..j].to_string());
        i = j + 1;
        ws_after_start = i;
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
            i += 1;
        }
    }
    let _ = ws_after_start;
    if i < b.len() && b[i] == b')' {
        let url = s[url_start..url_end].to_string();
        Some((url, url_start, url_end, title, i + 1))
    } else {
        None
    }
}

/// Find links and images in a line. `code` = code spans to skip.
pub fn links(s: &str) -> Vec<Link> {
    let code = code_spans(s);
    let b = s.as_bytes();
    let mut res = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if in_spans(&code, i) {
            i += 1;
            continue;
        }
        if b[i] == b'\\' {
            i += 2;
            continue;
        }
        if b[i] == b'<' {
            // autolink
            if let Some(end) = autolink_end(s, i) {
                let inner = &s[i + 1..end - 1];
                res.push(Link {
                    start: i,
                    end,
                    text: inner.to_string(),
                    text_start: i + 1,
                    text_end: end - 1,
                    url: inner.to_string(),
                    url_start: i + 1,
                    url_end: end - 1,
                    title: None,
                    reference: None,
                    image: false,
                    kind: LinkKind::Autolink,
                });
                i = end;
                continue;
            }
            i += 1;
            continue;
        }
        let image = b[i] == b'!' && i + 1 < b.len() && b[i + 1] == b'[';
        if b[i] == b'[' || image {
            let open = if image { i + 1 } else { i };
            if let Some(close) = find_matching_bracket(b, open) {
                let text = &s[open + 1..close];
                // inline
                if close + 1 < b.len() && b[close + 1] == b'(' {
                    if let Some((url, us, ue, title, end)) = parse_inline_dest(s, close + 1) {
                        if !image && text.starts_with('^') {
                            // footnote-ish; skip
                        }
                        res.push(Link {
                            start: i,
                            end,
                            text: text.to_string(),
                            text_start: open + 1,
                            text_end: close,
                            url,
                            url_start: us,
                            url_end: ue,
                            title,
                            reference: None,
                            image,
                            kind: LinkKind::Inline,
                        });
                        i = end;
                        continue;
                    }
                }
                // reference: [text][ref] or [text][]
                if close + 1 < b.len() && b[close + 1] == b'[' {
                    if let Some(rclose) = find_matching_bracket(b, close + 1) {
                        let r = &s[close + 2..rclose];
                        if !r.contains('[') {
                            let kind = if r.is_empty() { LinkKind::Collapsed } else { LinkKind::Full };
                            let reference = if r.is_empty() { text.to_string() } else { r.to_string() };
                            res.push(Link {
                                start: i,
                                end: rclose + 1,
                                text: text.to_string(),
                                text_start: open + 1,
                                text_end: close,
                                url: String::new(),
                                url_start: close + 2,
                                url_end: rclose,
                                title: None,
                                reference: Some(reference),
                                image,
                                kind,
                            });
                            i = rclose + 1;
                            continue;
                        }
                    }
                }
                // shortcut [text] (not followed by ':' which would be a definition)
                if !text.is_empty() && !text.starts_with('^') && !(close + 1 < b.len() && b[close + 1] == b':') {
                    // only treat as shortcut if text has no nested brackets
                    res.push(Link {
                        start: i,
                        end: close + 1,
                        text: text.to_string(),
                        text_start: open + 1,
                        text_end: close,
                        url: String::new(),
                        url_start: close + 1,
                        url_end: close + 1,
                        title: None,
                        reference: Some(text.to_string()),
                        image,
                        kind: LinkKind::Shortcut,
                    });
                    i = close + 1;
                    continue;
                }
                i = open + 1;
                continue;
            }
        }
        i += 1;
    }
    res
}

pub fn autolink_end(s: &str, start: usize) -> Option<usize> {
    // <scheme:...> or <email>
    let b = s.as_bytes();
    let mut j = start + 1;
    while j < b.len() && b[j] != b'>' {
        if b[j] == b' ' || b[j] == b'<' {
            return None;
        }
        j += 1;
    }
    if j >= b.len() {
        return None;
    }
    let inner = &s[start + 1..j];
    let re_scheme = regex::Regex::new(r"^[A-Za-z][A-Za-z0-9+.-]{1,31}:[^\s<>]*$").unwrap();
    let re_email = regex::Regex::new(r"^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*$").unwrap();
    if re_scheme.is_match(inner) || re_email.is_match(inner) {
        Some(j + 1)
    } else {
        None
    }
}

#[derive(Debug, Clone)]
pub struct HtmlTag {
    pub start: usize,
    pub end: usize,
    pub name: String,
    pub closing: bool,
    pub raw: String,
}

/// Find inline HTML tags in a line (excluding code spans and autolinks)
pub fn html_tags(s: &str) -> Vec<HtmlTag> {
    let code = code_spans(s);
    let re = regex::Regex::new(r#"<(/?)([A-Za-z][A-Za-z0-9-]*)(?:\s+[^<>]*?)?\s*/?>"#).unwrap();
    let mut res = Vec::new();
    for m in re.find_iter(s) {
        if in_spans(&code, m.start()) {
            continue;
        }
        if autolink_end(s, m.start()).is_some() {
            continue;
        }
        let c = re.captures(m.as_str()).unwrap();
        res.push(HtmlTag {
            start: m.start(),
            end: m.end(),
            name: c.get(2).unwrap().as_str().to_string(),
            closing: !c.get(1).unwrap().as_str().is_empty(),
            raw: m.as_str().to_string(),
        });
    }
    res
}

/// Mask code spans, links urls, html, etc. replacing chars with spaces (keeps byte offsets). Used by many rules.
pub fn mask_ranges(s: &str, ranges: &[(usize, usize)]) -> String {
    let mut out: Vec<u8> = s.as_bytes().to_vec();
    for &(a, b) in ranges {
        for k in a..b.min(out.len()) {
            if out[k] != b'\n' {
                out[k] = b' ';
            }
        }
    }
    // this may break utf8 if ranges cut multibyte chars; ranges are at char boundaries normally
    String::from_utf8(out).unwrap_or_else(|_| s.to_string())
}

/// Mask code spans only.
pub fn mask_code_spans(s: &str) -> String {
    let spans = code_spans(s);
    let ranges: Vec<(usize, usize)> = spans.iter().map(|sp| (sp.start, sp.end)).collect();
    mask_ranges(s, &ranges)
}

/// Mask code spans, link destinations (urls), autolinks, and html tags
pub fn mask_code_and_links(s: &str) -> String {
    let spans = code_spans(s);
    let mut ranges: Vec<(usize, usize)> = spans.iter().map(|sp| (sp.start, sp.end)).collect();
    for l in links(s) {
        match l.kind {
            LinkKind::Inline => ranges.push((l.text_end, l.end)),
            LinkKind::Autolink => ranges.push((l.start, l.end)),
            LinkKind::Full => ranges.push((l.text_end, l.end)),
            _ => {}
        }
    }
    for t in html_tags(s) {
        ranges.push((t.start, t.end));
    }
    mask_ranges(s, &ranges)
}
