        }
        j += 1;
    }
    if j >= b.len() {
        return None;
    }
    let inner = &s[start + 1..j];
    let re_scheme = regex::Regex::new(r"^[A-Za-z][A-Za-z0-9+.-]{1,31}:[^\s<>]*$").unwrap();
    let re_email = regex::Regex::new(r"^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*$").unwrap();
    if re_scheme.is_match(inner) || re_email.is_match(inner) {
        Some(j + 1)
    } else {
        None
    }
}

#[derive(Debug, Clone)]
pub struct HtmlTag {
    pub start: usize,
    pub end: usize,
    pub name: String,
    pub closing: bool,
    pub raw: String,
}

/// Find inline HTML tags in a line (excluding code spans and autolinks)
pub fn html_tags(s: &str) -> Vec<HtmlTag> {
    let code = code_spans(s);
    let re = regex::Regex::new(r#"<(/?)([A-Za-z][A-Za-z0-9-]*)(?:\s+[^<>]*?)?\s*/?>"#).unwrap();
    let mut res = Vec::new();
    for m in re.find_iter(s) {
        if in_spans(&code, m.start()) {
            continue;
        }
        if autolink_end(s, m.start()).is_some() {
            continue;
        }
        let c = re.captures(m.as_str()).unwrap();
        res.push(HtmlTag {
            start: m.start(),
            end: m.end(),
            name: c.get(2).unwrap().as_str().to_string(),
            closing: !c.get(1).unwrap().as_str().is_empty(),
            raw: m.as_str().to_string(),
        });
    }
    res
}

/// Mask code spans, links urls, html, etc. replacing chars with spaces (keeps byte offsets). Used by many rules.
pub fn mask_ranges(s: &str, ranges: &[(usize, usize)]) -> String {
    let mut out: Vec<u8> = s.as_bytes().to_vec();
    for &(a, b) in ranges {
        for k in a..b.min(out.len()) {
            if out[k] != b'\n' {
                out[k] = b' ';
            }
        }
    }
    // this may break utf8 if ranges cut multibyte chars; ranges are at char boundaries normally
    String::from_utf8(out).unwrap_or_else(|_| s.to_string())
}

/// Mask code spans only.
pub fn mask_code_spans(s: &str) -> String {
    let spans = code_spans(s);
    let ranges: Vec<(usize, usize)> = spans.iter().map(|sp| (sp.start, sp.end)).collect();
    mask_ranges(s, &ranges)
}

/// Mask code spans, link destinations (urls), autolinks, and html tags
pub fn mask_code_and_links(s: &str) -> String {
    let spans = code_spans(s);
    let mut ranges: Vec<(usize, usize)> = spans.iter().map(|sp| (sp.start, sp.end)).collect();
    for l in links(s) {
        match l.kind {
            LinkKind::Inline => ranges.push((l.text_end, l.end)),
            LinkKind::Autolink => ranges.push((l.start, l.end)),
            LinkKind::Full => ranges.push((l.text_end, l.end)),
            _ => {}
        }
    }
    for t in html_tags(s) {
        ranges.push((t.start, t.end));
    }
    mask_ranges(s, &ranges)
}
