// Minimal YAML subset parser (for markdownlint configs and front matter): maps, scalars, simple lists.
use serde_json::{Map, Value};

pub fn parse_yaml(s: &str) -> Option<Value> {
    let lines: Vec<&str> = s.lines().filter(|l| !l.trim().is_empty() && !l.trim_start().starts_with('#')).collect();
    let mut idx = 0;
    let v = parse_block(&lines, &mut idx, 0)?;
    Some(v)
}

fn indent_of(l: &str) -> usize {
    l.len() - l.trim_start().len()
}

fn parse_scalar(s: &str) -> Value {
    let t = s.trim();
    if t == "true" {
        return Value::Bool(true);
    }
    if t == "false" {
        return Value::Bool(false);
    }
    if t == "null" || t == "~" || t.is_empty() {
        return Value::Null;
    }
    if let Ok(i) = t.parse::<i64>() {
        return Value::Number(i.into());
    }
    if let Ok(f) = t.parse::<f64>() {
        if let Some(n) = serde_json::Number::from_f64(f) {
            return Value::Number(n);
        }
    }
    if (t.starts_with('"') && t.ends_with('"') && t.len() >= 2) || (t.starts_with('\'') && t.ends_with('\'') && t.len() >= 2) {
        return Value::String(t[1..t.len() - 1].to_string());
    }
    if t.starts_with('[') && t.ends_with(']') {
        let inner = &t[1..t.len() - 1];
        let items: Vec<Value> = inner.split(',').map(|x| x.trim()).filter(|x| !x.is_empty()).map(parse_scalar).collect();
        return Value::Array(items);
    }
    if t.starts_with('{') && t.ends_with('}') {
        let inner = &t[1..t.len() - 1];
        let mut m = Map::new();
        for part in inner.split(',') {
            if let Some((k, v)) = part.split_once(':') {
                m.insert(strip_quotes(k.trim()), parse_scalar(v));
            }
        }
        return Value::Object(m);
    }
    Value::String(t.to_string())
}

fn strip_quotes(s: &str) -> String {
    if (s.starts_with('"') && s.ends_with('"') && s.len() >= 2) || (s.starts_with('\'') && s.ends_with('\'') && s.len() >= 2) {
        s[1..s.len() - 1].to_string()
    } else {
        s.to_string()
    }
}

fn parse_block(lines: &[&str], idx: &mut usize, indent: usize) -> Option<Value> {
    if *idx >= lines.len() {
        return Some(Value::Null);
    }
    let first = lines[*idx];
    if first.trim_start().starts_with("- ") || first.trim() == "-" {
        // list
        let mut arr = Vec::new();
        while *idx < lines.len() {
            let l = lines[*idx];
            if indent_of(l) != indent || !(l.trim_start().starts_with("- ") || l.trim() == "-") {
                break;
            }
            let item = l.trim_start()[1..].trim();
            *idx += 1;
            if item.is_empty() {
                let v = parse_block(lines, idx, next_indent(lines, *idx, indent))?;
                arr.push(v);
            } else if item.contains(": ") || item.ends_with(':') {
                // inline map item
                let mut m = Map::new();
                let (k, v) = split_kv(item);
                if v.is_empty() {
                    let sub = parse_block(lines, idx, next_indent(lines, *idx, indent))?;
                    m.insert(k, sub);
                } else {
                    m.insert(k, parse_scalar(&v));
                }
                // more keys at deeper indent
                while *idx < lines.len() && indent_of(lines[*idx]) > indent && !lines[*idx].trim_start().starts_with("- ") {
                    let l2 = lines[*idx];
                    let (k2, v2) = split_kv(l2.trim());
                    *idx += 1;
                    if v2.is_empty() {
                        let sub = parse_block(lines, idx, next_indent(lines, *idx, indent_of(l2)))?;
                        m.insert(k2, sub);
                    } else {
                        m.insert(k2, parse_scalar(&v2));
                    }
                }
                arr.push(Value::Object(m));
            } else {
                arr.push(parse_scalar(item));
            }
        }
        return Some(Value::Array(arr));
    }
    let mut m = Map::new();
    while *idx < lines.len() {
        let l = lines[*idx];
        let ind = indent_of(l);
        if ind < indent {
            break;
        }
        if ind > indent {
            *idx += 1;
            continue;
        }
        let t = l.trim();
        if t.starts_with("- ") {
            break;
        }
        let (k, v) = split_kv(t);
        *idx += 1;
        if v.is_empty() {
            if *idx < lines.len() && indent_of(lines[*idx]) > indent {
                let sub = parse_block(lines, idx, indent_of(lines[*idx]))?;
                m.insert(k, sub);
            } else if *idx < lines.len() && indent_of(lines[*idx]) == indent && lines[*idx].trim_start().starts_with("- ") {
                let sub = parse_block(lines, idx, indent)?;
                m.insert(k, sub);
            } else {
                m.insert(k, Value::Null);
            }
        } else {
            m.insert(k, parse_scalar(&v));
        }
    }
    Some(Value::Object(m))
}

fn next_indent(lines: &[&str], idx: usize, cur: usize) -> usize {
    if idx < lines.len() {
        indent_of(lines[idx]).max(cur + 1)
    } else {
        cur + 1
    }
}

fn split_kv(t: &str) -> (String, String) {
    // find first ': ' or trailing ':'
    if let Some(p) = t.find(": ") {
        (strip_quotes(t[..p].trim()), t[p + 2..].trim().to_string())
    } else if t.ends_with(':') {
        (strip_quotes(t[..t.len() - 1].trim()), String::new())
    } else {
        (strip_quotes(t), String::new())
    }
}
