use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use toml::Value;

#[derive(Debug, Clone, Default)]
pub struct RuleConfig {
    pub values: BTreeMap<String, Value>, // kebab-case keys
    pub sources: BTreeMap<String, String>,
}

impl RuleConfig {
    pub fn get(&self, key: &str) -> Option<&Value> {
        self.values.get(&norm_key(key))
    }
    pub fn get_str(&self, key: &str) -> Option<String> {
        self.get(key).and_then(|v| v.as_str().map(|s| s.to_string()))
    }
    pub fn get_usize(&self, key: &str) -> Option<usize> {
        self.get(key).and_then(|v| v.as_integer()).map(|i| if i < 0 { 0 } else { i as usize })
    }
    pub fn get_i64(&self, key: &str) -> Option<i64> {
        self.get(key).and_then(|v| v.as_integer())
    }
    pub fn get_bool(&self, key: &str) -> Option<bool> {
        self.get(key).and_then(|v| v.as_bool())
    }
    pub fn get_str_vec(&self, key: &str) -> Option<Vec<String>> {
        self.get(key).and_then(|v| v.as_array()).map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
    }
}

#[derive(Debug, Clone)]
pub struct GlobalConfig {
    pub enable: Vec<String>,
    pub disable: Vec<String>,
    pub exclude: Vec<String>,
    pub include: Vec<String>,
    pub respect_gitignore: bool,
    pub line_length: usize,
    pub flavor: String,
    pub output_format: Option<String>,
    pub cache: bool,
    pub cache_dir: Option<String>,
    pub force_exclude: bool,
    pub fixable: Vec<String>,
    pub unfixable: Vec<String>,
    pub sources: BTreeMap<String, String>,
}

impl Default for GlobalConfig {
    fn default() -> Self {
        GlobalConfig {
            enable: vec![],
            disable: vec![],
            exclude: vec![],
            include: vec![],
            respect_gitignore: true,
            line_length: 80,
            flavor: "standard".to_string(),
            output_format: None,
            cache: true,
            cache_dir: None,
            force_exclude: false,
            fixable: vec![],
            unfixable: vec![],
            sources: BTreeMap::new(),
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Config {
    pub global: GlobalConfig,
    pub rules: BTreeMap<String, RuleConfig>, // "MD013" -> config
    pub per_file_ignores: Vec<(String, Vec<String>)>,
    pub per_file_flavor: Vec<(String, String)>,
    pub loaded_from: Option<PathBuf>,
    pub warnings: Vec<String>,
}

pub fn norm_key(k: &str) -> String {
    k.replace('_', "-").to_lowercase()
}

pub fn norm_rule_name(k: &str) -> String {
    k.trim().to_uppercase()
}

impl Config {
    pub fn rule(&self, name: &str) -> RuleConfig {
        self.rules.get(name).cloned().unwrap_or_default()
    }

    fn apply_global_value(&mut self, key: &str, v: &Value, source: &str, file: &str) {
        let k = norm_key(key);
        let g = &mut self.global;
        let strs = |v: &Value| -> Vec<String> {
            match v {
                Value::Array(a) => a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect(),
                Value::String(s) => s.split(',').map(|x| x.trim().to_string()).filter(|x| !x.is_empty()).collect(),
                _ => vec![],
            }
        };
        match k.as_str() {
            "enable" => g.enable = strs(v).iter().map(|s| norm_rule_name(s)).collect(),
            "disable" => g.disable = strs(v).iter().map(|s| norm_rule_name(s)).collect(),
            "exclude" => g.exclude = strs(v),
            "include" => g.include = strs(v),
            "respect-gitignore" => {
                if let Some(b) = v.as_bool() {
                    g.respect_gitignore = b
                }
            }
            "line-length" => {
                if let Some(i) = v.as_integer() {
                    g.line_length = i.max(0) as usize
                }
            }
            "flavor" => {
                if let Some(s) = v.as_str() {
                    g.flavor = s.to_string()
                }
            }
            "output-format" => g.output_format = v.as_str().map(|s| s.to_string()),
            "cache" => {
                if let Some(b) = v.as_bool() {
                    g.cache = b
                }
            }
            "cache-dir" => g.cache_dir = v.as_str().map(|s| s.to_string()),
            "force-exclude" => {
                if let Some(b) = v.as_bool() {
                    g.force_exclude = b
                }
            }
            "fixable" => g.fixable = strs(v),
            "unfixable" => g.unfixable = strs(v),
            _ => {
                self.warnings.push(format!("Unknown global option in {}: {}", file, key));
                return;
            }
        }
        self.global.sources.insert(k, source.to_string());
    }

    fn apply_rule_table(&mut self, rule: &str, table: &toml::map::Map<String, Value>, source: &str) {
        let rc = self.rules.entry(rule.to_string()).or_default();
        for (k, v) in table {
            rc.values.insert(norm_key(k), v.clone());
            rc.sources.insert(norm_key(k), source.to_string());
        }
    }

    fn apply_toml_table(&mut self, table: &toml::map::Map<String, Value>, source: &str, file: &str, pyproject: bool) {
        let rule_re = regex::Regex::new(r"^(?i)md\d{3}$").unwrap();
        for (k, v) in table {
            let kn = norm_key(k);
            if kn == "global" {
                if let Some(t) = v.as_table() {
                    for (gk, gv) in t {
                        self.apply_global_value(gk, gv, source, file);
                    }
                }
            } else if kn == "per-file-ignores" {
                if let Some(t) = v.as_table() {
                    for (pat, rules) in t {
                        let rs: Vec<String> = rules.as_array().map(|a| a.iter().filter_map(|x| x.as_str().map(norm_rule_name)).collect()).unwrap_or_default();
                        self.per_file_ignores.push((pat.clone(), rs));
                    }
                }
            } else if kn == "per-file-flavor" {
                if let Some(t) = v.as_table() {
                    for (pat, fl) in t {
                        if let Some(s) = fl.as_str() {
                            self.per_file_flavor.push((pat.clone(), s.to_string()));
                        }
                    }
                }
            } else if kn == "code-block-tools" {
                // ignored
            } else if rule_re.is_match(k) {
                if let Some(t) = v.as_table() {
                    self.apply_rule_table(&k.to_uppercase(), t, source);
                } else {
                    self.warnings.push(format!("Unknown rule in {}: {}", file, k));
                }
            } else if let Some(alias_rule) = crate::rules::rule_id_from_alias(k) {
                if let Some(t) = v.as_table() {
                    self.apply_rule_table(alias_rule, t, source);
                }
            } else if pyproject || v.as_table().is_none() {
                // top-level global keys (pyproject style)
                self.apply_global_value(k, v, source, file);
            } else {
                let hint = crate::rules::closest_rule_name(k);
                if let Some(h) = hint {
                    self.warnings.push(format!("Unknown rule in {}: {} (did you mean: {})", file, k, h));
                } else {
                    self.warnings.push(format!("Unknown rule in {}: {}", file, k));
                }
            }
        }
    }

    pub fn load_toml_file(&mut self, path: &Path, source: &str) -> Result<(), String> {
        let content = std::fs::read_to_string(path).map_err(|e| format!("Failed to read config file at {}: {}", path.display(), e))?;
        let value: Value = toml::from_str(&content).map_err(|e| format!("Failed to parse config: {}: Failed to parse TOML: {}", path.display(), e))?;
        let file = path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
        let table = value.as_table().cloned().unwrap_or_default();
        if file == "pyproject.toml" {
            if let Some(tool) = table.get("tool").and_then(|t| t.as_table()) {
                if let Some(r) = tool.get("rumdl").and_then(|t| t.as_table()) {
                    self.apply_toml_table(r, source, &file, true);
                }
            }
        } else {
            self.apply_toml_table(&table, source, &file, false);
        }
        self.loaded_from = Some(path.to_path_buf());
        Ok(())
    }

    pub fn load_markdownlint_file(&mut self, path: &Path, source: &str) -> Result<(), String> {
        let content = std::fs::read_to_string(path).map_err(|e| format!("Failed to read config file at {}: {}", path.display(), e))?;
        let fname = path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
        let json: serde_json::Value = if fname.ends_with(".yaml") || fname.ends_with(".yml") {
            crate::yaml::parse_yaml(&content).ok_or_else(|| format!("Failed to parse config: {}", path.display()))?
        } else {
            let stripped = strip_json_comments(&content);
            serde_json::from_str(&stripped).map_err(|e| format!("Failed to parse config: {}: {}", path.display(), e))?
        };
        if let Some(obj) = json.as_object() {
            for (k, v) in obj {
                let ku = k.to_uppercase();
                let rule_id: Option<String> = if regex::Regex::new(r"^MD\d{3}$").unwrap().is_match(&ku) {
                    Some(ku.clone())
                } else {
                    crate::rules::rule_id_from_alias(k).map(|s| s.to_string())
                };
                if let Some(rid) = rule_id {
                    match v {
                        serde_json::Value::Bool(false) => {
                            self.global.disable.push(rid);
                            self.global.sources.insert("disable".into(), source.into());
                        }
                        serde_json::Value::Bool(true) => {}
                        serde_json::Value::Object(o) => {
                            let rc = self.rules.entry(rid).or_default();
                            for (rk, rv) in o {
                                if let Some(tv) = json_to_toml(rv) {
                                    rc.values.insert(norm_key(rk), tv);
                                    rc.sources.insert(norm_key(rk), source.to_string());
                                }
                            }
                        }
                        _ => {}
                    }
                } else if k == "default" {
                    // ignore
                } else if k == "line-length" || k == "line_length" {
                    if let Some(i) = v.as_i64() {
                        self.global.line_length = i.max(0) as usize;
                    }
                }
            }
        }
        self.loaded_from = Some(path.to_path_buf());
        Ok(())
    }

    pub fn discover(start: &Path) -> Option<(PathBuf, &'static str)> {
        let mut dir = Some(start.to_path_buf());
        while let Some(d) = dir {
            for (name, kind) in [
                (".rumdl.toml", "rumdl"),
                ("rumdl.toml", "rumdl"),
                ("pyproject.toml", "pyproject"),
                (".markdownlint.json", "markdownlint"),
                (".markdownlint.jsonc", "markdownlint"),
                (".markdownlint.yaml", "markdownlint"),
                (".markdownlint.yml", "markdownlint"),
            ] {
                let p = d.join(name);
                if p.is_file() {
                    if kind == "pyproject" {
                        if let Ok(c) = std::fs::read_to_string(&p) {
                            if !c.contains("[tool.rumdl") {
                                continue;
                            }
                        } else {
                            continue;
                        }
                    }
                    return Some((p, kind));
                }
            }
            dir = d.parent().map(|p| p.to_path_buf());
        }
        None
    }

    pub fn load(explicit: Option<&str>, no_config: bool) -> Result<Config, String> {
        let mut cfg = Config::default();
        if no_config {
            return Ok(cfg);
        }
        if let Some(p) = explicit {
            let path = Path::new(p);
            let fname = path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
            if fname.ends_with(".json") || fname.ends_with(".jsonc") || fname.ends_with(".yaml") || fname.ends_with(".yml") {
                cfg.load_markdownlint_file(path, "project config")?;
            } else {
                cfg.load_toml_file(path, "project config")?;
            }
            return Ok(cfg);
        }
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        if let Some((p, kind)) = Config::discover(&cwd) {
            if kind == "markdownlint" {
                cfg.load_markdownlint_file(&p, "project config")?;
            } else {
                cfg.load_toml_file(&p, "project config")?;
            }
        }
        Ok(cfg)
    }
}

fn strip_json_comments(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    let mut in_str = false;
    while let Some(c) = chars.next() {
        if in_str {
            out.push(c);
            if c == '\\' {
                if let Some(n) = chars.next() {
                    out.push(n);
                }
            } else if c == '"' {
                in_str = false;
            }
            continue;
        }
        if c == '"' {
            in_str = true;
            out.push(c);
        } else if c == '/' && chars.peek() == Some(&'/') {
            while let Some(&n) = chars.peek() {
                if n == '\n' {
                    break;
                }
                chars.next();
            }
        } else if c == '/' && chars.peek() == Some(&'*') {
            chars.next();
            loop {
                match chars.next() {
                    Some('*') if chars.peek() == Some(&'/') => {
                        chars.next();
                        break;
                    }
                    Some(_) => {}
                    None => break,
                }
            }
        } else {
            out.push(c);
        }
    }
    // remove trailing commas
    let re = regex::Regex::new(r",(\s*[}\]])").unwrap();
    re.replace_all(&out, "$1").to_string()
}

pub fn json_to_toml(v: &serde_json::Value) -> Option<Value> {
    Some(match v {
        serde_json::Value::Null => return None,
        serde_json::Value::Bool(b) => Value::Boolean(*b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Value::Integer(i)
            } else {
                Value::Float(n.as_f64().unwrap_or(0.0))
            }
        }
        serde_json::Value::String(s) => Value::String(s.clone()),
        serde_json::Value::Array(a) => Value::Array(a.iter().filter_map(json_to_toml).collect()),
        serde_json::Value::Object(o) => {
            let mut m = toml::map::Map::new();
            for (k, v) in o {
                if let Some(t) = json_to_toml(v) {
                    m.insert(k.clone(), t);
                }
            }
            Value::Table(m)
        }
    })
}
