pub trait Rule {
    fn name(&self) -> &'static str;
    fn check(&self, ctx: &Ctx) -> Vec<Warning>;
    /// Return fixed content (whole document). Default: apply warning fixes.
    fn fix(&self, ctx: &Ctx) -> Option<String> {
