/// Apply individual warning fixes (non-overlapping ranges), sorted by range start.
pub fn apply_warning_fixes(content: &str, warnings: &[Warning]) -> Option<String> {
    let mut fixes: Vec<&crate::warning::Fix> = warnings.iter().filter_map(|w| w.fix.as_ref()).collect();
    if fixes.is_empty() {
        return None;
    }
    fixes.sort_by_key(|f| (f.range.start, f.range.end));
    let mut out = String::with_capacity(content.len());
    let mut pos = 0;
    for f in fixes {
        if f.range.start < pos {
            continue; // overlapping; skip
        }
        if f.range.end > content.len() || f.range.start > content.len() {
            continue;
        }
        out.push_str(&content[pos..f.range.start]);
        out.push_str(&f.replacement);
        pos = f.range.end;
    }
    out.push_str(&content[pos..]);
    Some(out)
}

