pub fn meta(id: &str) -> Option<&'static RuleMeta> {
    RULES.iter().find(|r| r.id == id)
}

/// Resolve a rule id or alias (case-insensitive) to the canonical id.
pub fn resolve_rule(s: &str) -> Option<&'static str> {
    let l = s.trim().to_lowercase();
    for r in RULES {
        if r.id.to_lowercase() == l || r.name == l || r.aliases.iter().any(|a| *a == l) {
            return Some(r.id);
        }
    }
    None
}

pub fn rule_id_from_alias(s: &str) -> Option<&'static str> {
    let l = s.trim().to_lowercase();
    for r in RULES {
        if r.name == l || r.aliases.iter().any(|a| *a == l) {
            return Some(r.id);
        }
    }
    None
}

pub fn closest_rule_name(s: &str) -> Option<&'static str> {
    // simple edit-distance based suggestion among ids
    let su = s.to_uppercase();
    let mut best: Option<(usize, &'static str)> = None;
    for r in RULES {
        let d = edit_distance(&su, r.id);
        if d <= 2 && best.map(|b| d < b.0).unwrap_or(true) {
            best = Some((d, r.id));
        }
    }
    best.map(|b| b.1)
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    for i in 1..=a.len() {
        let mut cur = vec![i; b.len() + 1];
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        prev = cur;
    }
    prev[b.len()]
}

