/// Determine the list of enabled rule ids given config and CLI overrides.
pub fn enabled_rules(cfg: &Config, cli_enable: Option<&str>, cli_disable: Option<&str>, extend_enable: Option<&str>, extend_disable: Option<&str>) -> Vec<&'static str> {
    let parse = |s: &str| -> Vec<String> { s.split(',').map(|x| x.trim()).filter(|x| !x.is_empty()).filter_map(|x| resolve_rule(x).map(|r| r.to_string()).or_else(|| Some(x.to_uppercase()))).collect() };
    let mut enable: Vec<String> = cfg.global.enable.iter().filter_map(|x| resolve_rule(x).map(|r| r.to_string()).or_else(|| Some(x.to_uppercase()))).collect();
    let mut disable: Vec<String> = cfg.global.disable.iter().filter_map(|x| resolve_rule(x).map(|r| r.to_string()).or_else(|| Some(x.to_uppercase()))).collect();
    let mut cli_enable_set = false;
    if let Some(e) = cli_enable {
        enable = parse(e);
        cli_enable_set = true;
    }
    if let Some(d) = cli_disable {
        disable = parse(d);
    }
    if let Some(e) = extend_enable {
        enable.extend(parse(e));
    }
    if let Some(d) = extend_disable {
        disable.extend(parse(d));
    }
    let mut result = Vec::new();
    for r in RULES {
        let explicitly_enabled = enable.iter().any(|e| e == r.id) || (cfg.rule(r.id).get_bool("enabled") == Some(true));
        let explicitly_disabled_cfg = cfg.rule(r.id).get_bool("enabled") == Some(false);
        let on = if cli_enable_set || !enable.is_empty() {
            // enable list is exclusive
            if cli_enable_set {
                enable.iter().any(|e| e == r.id)
            } else {
                enable.iter().any(|e| e == r.id) || (cfg.rule(r.id).get_bool("enabled") == Some(true) && !r.opt_in) || (r.opt_in && cfg.rule(r.id).get_bool("enabled") == Some(true))
            }
        } else if r.opt_in {
            explicitly_enabled
        } else {
            !explicitly_disabled_cfg
        };
        if !on {
            continue;
        }
        if disable.iter().any(|d| d == r.id) && !(cli_enable_set && enable.iter().any(|e| e == r.id)) {
            continue;
        }
        result.push(r.id);
    }
    result
}
