fn is_valid_heading(ctx: &Ctx, h: &Heading) -> bool {
    // a structural heading: atx with space after hashes (or empty), or setext
    match h.style {
        HeadingStyle::Setext => true,
        _ => {
            let line = ctx.line(h.line);
            let rest = &line[h.prefix_len + h.indent..];
            let after = &rest[h.level..];
            after.is_empty() || after.starts_with(' ') || after.starts_with('\t') || after.chars().next().map(|c| c.is_alphabetic() && c.is_uppercase()).unwrap_or(false)
        }
    }
}

fn front_matter_has_title(ctx: &Ctx) -> bool {
    if let Some((s, e)) = ctx.front_matter {
        for i in s + 1..e {
            let l = ctx.line(i);
            if l.starts_with("title:") || l.starts_with("title =") || l.starts_with("title=") || l.starts_with("\"title\"") {
                return true;
            }
        }
    }
    false
}

/// Render a heading line in the given style. Returns (replacement text for the heading's text line).
fn render_atx(h: &Heading, level: usize, closed: bool, prefix: &str) -> String {
    let hashes = "#".repeat(level);
    if h.text.is_empty() {
        if closed {
            format!("{}{} {}", prefix, hashes, hashes)
        } else {
            format!("{}{}", prefix, hashes)
        }
    } else if closed {
        format!("{}{} {} {}", prefix, hashes, h.text, hashes)
    } else {
        format!("{}{} {}", prefix, hashes, h.text)
    }
}

