impl MD001 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD001 { front_matter_title: rc.get_bool("front-matter-title").unwrap_or(true) }
    }
}
impl Rule for MD001 {
    fn name(&self) -> &'static str {
        "MD001"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let mut prev: Option<usize> = None;
        if self.front_matter_title && front_matter_has_title(ctx) {
            prev = Some(1);
        }
        for h in &ctx.headings {
            if !is_valid_heading(ctx, h) {
                continue;
            }
            if let Some(p) = prev {
                if h.level > p + 1 {
                    let expected = p + 1;
                    let line = ctx.line(h.line);
                    let mut w = Warning::new("MD001", h.line + 1, 1, format!("Expected heading level {}, but found heading level {}", expected, h.level))
                        .with_severity(Severity::Error)
                        .with_end(h.line + 1, line.len() + 1);
                    // fix: replace line
                    let rep = fix_level_line(ctx, h, expected);
                    let start = ctx.lines[h.line].start;
                    let end = match h.underline_line {
                        Some(u) => ctx.line_end(u),
                        None => ctx.line_end(h.line),
                    };
                    w = w.with_fix(start, end, rep);
                    out.push(w);
                }
            }
            prev = Some(h.level);
        }
        out
    }
    fn fix(&self, ctx: &Ctx) -> Option<String> {
        let warnings = self.check(ctx);
        if warnings.iter().all(|w| w.fix.is_none()) {
            return None;
        }
        // Recompute levels progressively
        let mut lines: Vec<String> = ctx.raw.iter().map(|s| s.to_string()).collect();
        let mut prev: Option<usize> = None;
        if self.front_matter_title && front_matter_has_title(ctx) {
            prev = Some(1);
        }
        for h in &ctx.headings {
            if !is_valid_heading(ctx, h) {
                continue;
            }
            let mut level = h.level;
            if let Some(p) = prev {
                if level > p + 1 {
                    level = p + 1;
                    let rep = fix_level_line(ctx, h, level);
                    match h.underline_line {
                        Some(u) => {
                            let parts: Vec<&str> = rep.splitn(2, '\n').collect();
                            lines[h.line] = parts[0].to_string();
                            if parts.len() > 1 {
                                lines[u] = parts[1].to_string();
                            }
                        }
                        None => lines[h.line] = rep,
                    }
                }
            }
            prev = Some(level);
        }
        Some(join_lines(ctx, &lines))
    }
}

pub fn join_lines(ctx: &Ctx, lines: &[String]) -> String {
    let mut s = lines.join("\n");
    if ctx.content.ends_with('\n') {
        s.push('\n');
    }
    s
}

fn fix_level_line(ctx: &Ctx, h: &Heading, level: usize) -> String {
    let line = ctx.line(h.line);
    let prefix = &line[..h.prefix_len + h.indent];
    match h.style {
        HeadingStyle::Setext => {
            if level <= 2 {
                let c = if level == 1 { '=' } else { '-' };
                let ul = ctx.line(h.underline_line.unwrap());
                let ul_len = ul.trim().len().max(1);
                format!("{}{}\n{}{}", prefix, h.text, prefix, c.to_string().repeat(ul_len))
            } else {
                format!("{}{} {}\n", prefix, "#".repeat(level), h.text)
            }
        }
        HeadingStyle::AtxClosed => render_atx(h, level, true, prefix),
        HeadingStyle::Atx => render_atx(h, level, false, prefix),
    }
}

// ---------------- MD003 ----------------
#[derive(Clone, Copy, PartialEq, Debug)]
enum Style {
    Consistent,
    Atx,
    AtxClosed,
    Setext,
    SetextWithAtx,
    SetextWithAtxClosed,
}
pub struct MD003 {
    style: Style,
}
impl MD003 {
    pub fn new(rc: &RuleConfig) -> Self {
        let style = match rc.get_str("style").unwrap_or_default().to_lowercase().as_str() {
            "atx" => Style::Atx,
            "atx_closed" | "atx-closed" => Style::AtxClosed,
            "setext" => Style::Setext,
            "setext_with_atx" | "setext-with-atx" => Style::SetextWithAtx,
            "setext_with_atx_closed" | "setext-with-atx-closed" => Style::SetextWithAtxClosed,
            _ => Style::Consistent,
        };
        MD003 { style }
    }
    fn target(&self, ctx: &Ctx, headings: &[&Heading]) -> Style {
        if self.style != Style::Consistent {
            return self.style;
        }
        let _ = ctx;
        let mut atx = 0;
        let mut closed = 0;
        let mut s1 = 0;
        let mut s2 = 0;
        for h in headings {
            match h.style {
                HeadingStyle::Atx => atx += 1,
                HeadingStyle::AtxClosed => closed += 1,
                HeadingStyle::Setext => {
                    if h.level == 1 {
                        s1 += 1
                    } else {
                        s2 += 1
                    }
                }
            }
        }
        let max = atx.max(closed).max(s1).max(s2);
        if max == 0 {
            return Style::Atx;
        }
        if atx == max {
            Style::Atx
        } else if s1 == max || s2 == max {
            Style::Setext
        } else {
            Style::AtxClosed
        }
    }
}
fn style_desc(style: Style, level: usize) -> String {
    match style {
        Style::Atx => "# Heading".to_string(),
        Style::AtxClosed => "# Heading #".to_string(),
        Style::Setext | Style::SetextWithAtx | Style::SetextWithAtxClosed => {
            if level == 1 {
                "Heading\n=======".to_string()
            } else {
                "Heading\n-------".to_string()
            }
        }
        Style::Consistent => "# Heading".to_string(),
    }
}
fn found_desc(h: &Heading) -> String {
    match h.style {
        HeadingStyle::Atx => "# Heading".to_string(),
        HeadingStyle::AtxClosed => "# Heading #".to_string(),
        HeadingStyle::Setext => format!("Heading (underlined with {})", h.underline_char),
    }
}
impl Rule for MD003 {
    fn name(&self) -> &'static str {
        "MD003"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let headings: Vec<&Heading> = ctx.headings.iter().filter(|h| is_valid_heading(ctx, h)).collect();
        if headings.is_empty() {
            return out;
        }
        let target = self.target(ctx, &headings);
        for h in &headings {
            // expected style for this heading
            let expected = match target {
                Style::Atx => Style::Atx,
                Style::AtxClosed => Style::AtxClosed,
                Style::Setext => {
                    if h.level <= 2 {
                        Style::Setext
                    } else {
                        Style::Atx
                    }
                }
                Style::SetextWithAtx => {
                    if h.level <= 2 {
                        Style::Setext
                    } else {
                        Style::Atx
                    }
                }
                Style::SetextWithAtxClosed => {
                    if h.level <= 2 {
                        Style::Setext
                    } else {
                        Style::AtxClosed
                    }
                }
                Style::Consistent => Style::Atx,
            };
            let actual = match h.style {
                HeadingStyle::Atx => Style::Atx,
                HeadingStyle::AtxClosed => Style::AtxClosed,
                HeadingStyle::Setext => Style::Setext,
            };
            if actual != expected {
                let line = ctx.line(h.line);
                let prefix = &line[..h.prefix_len + h.indent];
                let rep = match expected {
                    Style::Atx => render_atx(h, h.level, false, prefix),
                    Style::AtxClosed => render_atx(h, h.level, true, prefix),
                    _ => {
                        let c = if h.level == 1 { '=' } else { '-' };
                        format!("{}{}\n{}{}", prefix, h.text, prefix, c.to_string().repeat(h.text.chars().count().max(1)))
                    }
                };
                let msg = format!("Heading style should be {}, found {}", style_desc(expected, h.level), found_desc(h));
                let w = Warning::new("MD003", h.line + 1, 1, msg)
                    .with_end(h.line + 1, line.len() + 1)
                    .with_fix(ctx.lines[h.line].start, ctx.line_end(h.line), rep);
                out.push(w);
            }
        }
        out
    }
}

// ---------------- MD018 ----------------
pub struct MD018 {}
impl MD018 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD018 {}
    }
}
impl Rule for MD018 {
    fn name(&self) -> &'static str {
        "MD018"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for i in 0..ctx.line_count() {
            if ctx.skip_line(i) || ctx.lines[i].in_html_block || ctx.lines[i].in_comment || ctx.lines[i].in_table {
                continue;
            }
            let line = ctx.line(i);
            if !line.starts_with('#') {
                continue;
            }
            let hashes = line.chars().take_while(|&c| c == '#').count();
            let level = hashes.min(6);
            let after = &line[level..];
            if after.is_empty() || after.starts_with(' ') || after.starts_with('\t') {
                continue;
            }
            if hashes > 6 && !after.starts_with('#') {
                // handled below as 6 hashes + content starting with '#'
            }
            // not a heading if it's e.g. a shebang? original flags these too
            let msg = format!("No space after {} in heading", "#".repeat(level));
            let w = Warning::new("MD018", i + 1, level + 1, msg)
                .with_end(i + 1, line.len() + 1)
                .with_fix(ctx.lines[i].start + level, ctx.lines[i].start + level, " ");
            out.push(w);
        }
        out
    }
}

// ---------------- MD019 ----------------
pub struct MD019 {}
impl MD019 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD019 {}
    }
}
impl Rule for MD019 {
    fn name(&self) -> &'static str {
        "MD019"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for h in &ctx.headings {
            if h.style == HeadingStyle::Setext || !is_valid_heading(ctx, h) {
                continue;
            }
            let line = ctx.line(h.line);
            let rest = &line[h.prefix_len + h.indent..];
            let after = &rest[h.level..];
            let sp = after.len() - after.trim_start_matches([' ', '\t']).len();
            if sp > 1 && !after.trim().is_empty() && h.style == HeadingStyle::Atx {
                let col = h.prefix_len + h.indent + h.level + 1;
                let msg = format!("Multiple spaces ({}) after {} in heading", sp, "#".repeat(h.level));
                let s = ctx.lines[h.line].start + h.prefix_len + h.indent + h.level;
                let w = Warning::new("MD019", h.line + 1, col, msg).with_end(h.line + 1, col + sp).with_fix(s, s + sp, " ");
                out.push(w);
            } else if sp > 1 && after.trim().is_empty() {
                let col = h.prefix_len + h.indent + h.level + 1;
                let msg = format!("Multiple spaces ({}) after {} in heading", sp, "#".repeat(h.level));
                let s = ctx.lines[h.line].start + h.prefix_len + h.indent + h.level;
                let w = Warning::new("MD019", h.line + 1, col, msg).with_end(h.line + 1, col + sp).with_fix(s, s + sp, "");
                out.push(w);
            } else if sp > 1 && h.style == HeadingStyle::AtxClosed {
                let col = h.prefix_len + h.indent + h.level + 1;
                let msg = format!("Multiple spaces ({}) after {} in heading", sp, "#".repeat(h.level));
                let s = ctx.lines[h.line].start + h.prefix_len + h.indent + h.level;
                let w = Warning::new("MD019", h.line + 1, col, msg).with_end(h.line + 1, col + sp).with_fix(s, s + sp, " ");
                out.push(w);
            }
        }
        out
    }
}

// ---------------- MD020 ----------------
pub struct MD020 {}
impl MD020 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD020 {}
    }
}
impl Rule for MD020 {
    fn name(&self) -> &'static str {
        "MD020"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for h in &ctx.headings {
            if h.style != HeadingStyle::AtxClosed {
                continue;
            }
            let line = ctx.line(h.line);
            let rest = &line[h.prefix_len + h.indent..];
            let after = &rest[h.level..];
            let missing_start = !(after.starts_with(' ') || after.starts_with('\t')) && !after.is_empty();
            let trimmed = rest.trim_end();
            let closing = trimmed.chars().rev().take_while(|&c| c == '#').count();
            let before_close = &trimmed[..trimmed.len() - closing];
            let missing_end = !before_close.is_empty() && !(before_close.ends_with(' ') || before_close.ends_with('\t'));
            if !missing_start && !missing_end {
                continue;
            }
            let hashes = "#".repeat(h.level);
            let base = h.prefix_len + h.indent;
            // fix: rebuild
            let rep = format!("{}{} {} {}", &line[..base], hashes, h.text.trim(), "#".repeat(closing));
            let (col, msg) = if missing_start && missing_end {
                (base + h.level + 1, format!("Missing space inside hashes on closed heading (with {} at start and end)", hashes))
            } else if missing_start {
                (base + h.level + 1, format!("Missing space after {} at start of closed heading", hashes))
            } else {
                (base + before_close.len(), format!("Missing space before {} at end of closed heading", "#".repeat(closing)))
            };
            let w = Warning::new("MD020", h.line + 1, col, msg).with_end(h.line + 1, line.len() + 1).with_fix(ctx.lines[h.line].start, ctx.line_end(h.line), rep);
            out.push(w);
        }
        out
    }
}

