            } else if sp_start > 1 {
                format!("Multiple spaces ({}) after {} at start of closed heading", sp_start, hashes)
            } else {
                format!("Multiple spaces ({}) before {} at end of closed heading", sp_end, "#".repeat(closing))
            };
            let w = Warning::new("MD021", h.line + 1, 1, msg).with_end(h.line + 1, line.len() + 1).with_fix(ctx.lines[h.line].start, ctx.line_end(h.line), rep);
            out.push(w);
        }
        out
    }
}

// ---------------- MD022 ----------------
pub struct MD022 {
    lines_above: i64,
    lines_below: i64,
    allowed_at_start: bool,
}
impl MD022 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD022 {
            lines_above: rc.get_i64("lines-above").unwrap_or(1),
            lines_below: rc.get_i64("lines-below").unwrap_or(1),
            allowed_at_start: rc.get_bool("allowed-at-start").unwrap_or(true),
        }
    }
}
fn is_comment_line(ctx: &Ctx, i: usize) -> bool {
    let t = ctx.line(i).trim();
    ctx.lines[i].in_comment || t.starts_with("<!--")
}
impl Rule for MD022 {
    fn name(&self) -> &'static str {
        "MD022"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let n = ctx.line_count();
        for h in &ctx.headings {
            if !is_valid_heading(ctx, h) {
                continue;
            }
            if ctx.lines[h.line].bq_depth > 0 {
                continue;
            }
            let i = h.line;
            let line = ctx.line(i);
            // above
            let mut blanks_above = 0;
            let mut j = i;
            while j > 0 && ctx.lines[j - 1].blank {
                blanks_above += 1;
                j -= 1;
            }
            let at_start = j == 0 || ctx.front_matter.map(|(_, e)| j == e + 1).unwrap_or(false);
            let above_required = self.lines_above.max(0) as usize;
            if !(at_start && (self.allowed_at_start || blanks_above > 0 || j == 0)) && blanks_above < above_required && self.lines_above >= 0 {
                let prev = j - 1;
                if !is_comment_line(ctx, prev) {
                    let needed = above_required - blanks_above;
                    let msg = format!("Expected {} blank line{} above heading", above_required, if above_required == 1 { "" } else { "s" });
                    let pos = ctx.lines[i].start;
                    let w = Warning::new("MD022", i + 1, 1, msg).with_end(i + 1, line.len() + 1).with_fix(pos, pos, "\n".repeat(needed));
                    out.push(w);
                }
            }
            // below
            let last = h.underline_line.unwrap_or(i);
            let mut blanks_below = 0;
            let mut k = last + 1;
            while k < n && ctx.lines[k].blank {
                blanks_below += 1;
                k += 1;
            }
            let below_required = self.lines_below.max(0) as usize;
            if k < n && blanks_below < below_required && self.lines_below >= 0 {
                let next_is_list = ctx.lines[k].list_item.is_some();
                let next_is_fence = ctx.lines[k].is_fence;
                let next_is_comment = is_comment_line(ctx, k);
                if !next_is_list && !next_is_fence && !next_is_comment {
                    let needed = below_required - blanks_below;
                    let msg = format!("Expected {} blank line{} below heading", below_required, if below_required == 1 { "" } else { "s" });
                    let pos = ctx.next_line_start(last);
                    let w = Warning::new("MD022", i + 1, 1, msg).with_end(i + 1, line.len() + 1).with_fix(pos, pos, "\n".repeat(needed));
                    out.push(w);
                }
            }
        }
        out
    }
    fn fix(&self, ctx: &Ctx) -> Option<String> {
        let warnings = self.check(ctx);
        if warnings.is_empty() {
            return None;
        }
        // Rebuild document ensuring blank lines around headings
        let n = ctx.line_count();
        let mut out: Vec<String> = Vec::new();
        let mut i = 0;
        let above = self.lines_above.max(0) as usize;
        let below = self.lines_below.max(0) as usize;
        while i < n {
            let line = ctx.line(i).to_string();
            if let Some(h) = ctx.heading_at(i) {
                if is_valid_heading(ctx, h) && ctx.lines[i].bq_depth == 0 {
                    // ensure blank lines above
                    let at_start = out.is_empty();
                    if !at_start {
                        let mut blanks = 0;
                        for l in out.iter().rev() {
                            if l.trim().is_empty() {
                                blanks += 1;
                            } else {
                                break;
                            }
                        }
                        let prev_idx = out.len() - blanks;
                        let prev_is_comment = prev_idx > 0 && out[prev_idx - 1].trim().starts_with("<!--");
                        if !prev_is_comment {
                            while blanks < above {
                                out.push(String::new());
                                blanks += 1;
                            }
                        }
                    }
                    out.push(line);
                    let mut last = i;
                    if let Some(u) = h.underline_line {
                        out.push(ctx.line(u).to_string());
                        last = u;
                    }
                    // ensure blank lines below
                    let mut k = last + 1;
                    let mut blanks = 0;
                    while k < n && ctx.lines[k].blank {
                        blanks += 1;
                        k += 1;
                    }
                    if k < n {
                        let next_is_list = ctx.lines[k].list_item.is_some();
                        let next_is_fence = ctx.lines[k].is_fence;
                        let next_is_comment = is_comment_line(ctx, k);
                        if !next_is_list && !next_is_fence && !next_is_comment {
                            for _ in blanks..below {
                                out.push(String::new());
                            }
                        }
                    }
                    i = last + 1;
                    continue;
                }
            }
            out.push(line);
            i += 1;
        }
        Some(join_lines(ctx, &out))
    }
}

// ---------------- MD023 ----------------
pub struct MD023 {}
impl MD023 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD023 {}
    }
}
impl Rule for MD023 {
    fn name(&self) -> &'static str {
        "MD023"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for h in &ctx.headings {
            if !is_valid_heading(ctx, h) {
                continue;
            }
            if h.indent > 0 && ctx.lines[h.line].list_item.is_none() {
                // must not be inside a list continuation
                if ctx.lines[h.line].in_list {
                    continue;
                }
                let line = ctx.line(h.line);
                let msg = format!("Heading should not be indented by {} space{}", h.indent, if h.indent == 1 { "" } else { "s" });
                let s = ctx.lines[h.line].start + h.prefix_len;
                let mut w = Warning::new("MD023", h.line + 1, 1, msg).with_end(h.line + 1, line.len() + 1).with_fix(s, s + h.indent, "");
                if let Some(u) = h.underline_line {
                    let ul = ctx.line(u);
                    let uind = ul.len() - ul.trim_start().len();
                    let rep = format!("{}\n{}", &line[h.prefix_len + h.indent..], &ul[uind..]);
                    w = w.with_fix(ctx.lines[h.line].start + h.prefix_len, ctx.line_end(u), rep);
                }
                out.push(w);
            }
        }
        out
    }
}

// ---------------- MD024 ----------------
pub struct MD024 {
    siblings_only: bool,
    allow_different_nesting: bool,
}
impl MD024 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD024 {
            siblings_only: rc.get_bool("siblings-only").unwrap_or(true),
            allow_different_nesting: rc.get_bool("allow-different-nesting").unwrap_or(false),
        }
    }
}
impl Rule for MD024 {
    fn name(&self) -> &'static str {
        "MD024"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let headings: Vec<&Heading> = ctx.headings.iter().filter(|h| is_valid_heading(ctx, h)).collect();
        if self.siblings_only || self.allow_different_nesting {
            // stack of (level, set of texts)
            let mut stack: Vec<(usize, Vec<String>)> = vec![(0, Vec::new())];
            for h in &headings {
                while stack.len() > 1 && stack.last().unwrap().0 >= h.level {
                    stack.pop();
                }
                // siblings are in the parent's child set; we store children per parent level
                // find parent frame
                let frame = stack.last_mut().unwrap();
                let key = h.text.trim().to_string();
                if frame.1.iter().any(|t| t == &key) {
                    out.push(dup_warning(ctx, h));
                } else {
                    frame.1.push(key);
                }
                stack.push((h.level, Vec::new()));
            }
        } else {
            let mut seen: Vec<String> = Vec::new();
            for h in &headings {
                let key = h.text.trim().to_string();
                if seen.iter().any(|t| t == &key) {
                    out.push(dup_warning(ctx, h));
                } else {
                    seen.push(key);
                }
            }
        }
        out
    }
}
fn dup_warning(ctx: &Ctx, h: &Heading) -> Warning {
    let line = ctx.line(h.line);
    let col = if h.text.is_empty() { 1 } else { h.text_col + 1 };
    Warning::new("MD024", h.line + 1, col, format!("Duplicate heading: '{}'.", h.text.trim())).with_severity(Severity::Error).with_end(h.line + 1, line.len() + 1)
}

// ---------------- MD025 ----------------
pub struct MD025 {
    level: usize,
    front_matter_title: String,
}
impl MD025 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD025 { level: rc.get_usize("level").unwrap_or(1), front_matter_title: rc.get_str("front-matter-title").unwrap_or_else(|| "title".to_string()) }
    }
}
impl Rule for MD025 {
    fn name(&self) -> &'static str {
        "MD025"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let mut seen = false;
        if !self.front_matter_title.is_empty() {
            if let Some((s, e)) = ctx.front_matter {
                for i in s + 1..e {
                    let l = ctx.line(i);
                    if l.starts_with(&format!("{}:", self.front_matter_title)) || l.starts_with(&format!("{} =", self.front_matter_title)) {
                        seen = true;
                    }
                }
            }
        }
        for h in &ctx.headings {
            if !is_valid_heading(ctx, h) || h.level != self.level {
                continue;
            }
            if ctx.lines[h.line].bq_depth > 0 {
                continue;
            }
            if seen {
                let line = ctx.line(h.line);
                let col = if h.text.is_empty() { 1 } else { h.text_col + 1 };
                let prefix = &line[..h.prefix_len + h.indent];
                let rep = match h.style {
                    HeadingStyle::Setext => {
                        let ul = ctx.line(h.underline_line.unwrap());
                        format!("{}{}\n{}{}", prefix, h.text, prefix, "-".repeat(ul.trim().len().max(1)))
                    }
                    HeadingStyle::AtxClosed => render_atx(h, h.level + 1, true, prefix),
                    HeadingStyle::Atx => render_atx(h, h.level + 1, false, prefix),
                };
                let end = match h.underline_line {
                    Some(u) => ctx.line_end(u),
                    None => ctx.line_end(h.line),
                };
                let w = Warning::new("MD025", h.line + 1, col, format!("Multiple top-level headings (level {}) in the same document", self.level))
                    .with_severity(Severity::Error)
                    .with_end(h.line + 1, line.len() + 1)
                    .with_fix(ctx.lines[h.line].start, end, rep);
                out.push(w);
            } else {
                seen = true;
            }
        }
        out
    }
}

// ---------------- MD026 ----------------
pub struct MD026 {
    punctuation: String,
}
impl MD026 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD026 { punctuation: rc.get_str("punctuation").unwrap_or_else(|| ".,;:!".to_string()) }
    }
}
impl Rule for MD026 {
    fn name(&self) -> &'static str {
        "MD026"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for h in &ctx.headings {
            if !is_valid_heading(ctx, h) {
                continue;
            }
            let text = h.text.trim_end();
            if text.is_empty() {
                continue;
            }
            let last = text.chars().last().unwrap();
            if !self.punctuation.contains(last) {
                continue;
            }
            // skip if ends with html entity like &amp; or code span
            if last == ';' && regex::Regex::new(r"&[a-zA-Z0-9#]+;$").unwrap().is_match(text) {
                continue;
            }
            let line = ctx.line(h.line);
            // position of punctuation
            let text_start_byte = h.prefix_len + h.indent + match h.style {
                HeadingStyle::Setext => 0,
                _ => {
                    let rest = &line[h.prefix_len + h.indent..];
                    let after = &rest[h.level..];
                    h.level + (after.len() - after.trim_start_matches([' ', '\t']).len())
                }
            };
            let punct_byte = text_start_byte + text.len() - last.len_utf8();
            let col = line[..punct_byte].chars().count() + 1;
            let new_text = text[..text.len() - last.len_utf8()].trim_end().to_string();
            let prefix = &line[..h.prefix_len + h.indent];
            let fixed_h = Heading { text: new_text, ..h.clone() };
            let rep = match h.style {
                HeadingStyle::Atx => render_atx(&fixed_h, h.level, false, prefix),
                HeadingStyle::AtxClosed => render_atx(&fixed_h, h.level, true, prefix),
                HeadingStyle::Setext => format!("{}{}", prefix, fixed_h.text),
            };
            let w = Warning::new("MD026", h.line + 1, col, format!("Heading '{}' ends with punctuation '{}'", text, last))
                .with_end(h.line + 1, col + 1)
                .with_fix(ctx.lines[h.line].start, ctx.line_end(h.line), rep);
            out.push(w);
        }
        out
    }
}

// ---------------- MD041 ----------------
pub struct MD041 {
    level: usize,
    front_matter_title: String,
    front_matter_title_pattern: String,
}
impl MD041 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD041 {
            level: rc.get_usize("level").unwrap_or(1),
            front_matter_title: rc.get_str("front-matter-title").unwrap_or_else(|| "title".to_string()),
            front_matter_title_pattern: rc.get_str("front-matter-title-pattern").unwrap_or_default(),
        }
    }
}
impl Rule for MD041 {
    fn name(&self) -> &'static str {
        "MD041"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        // front matter title satisfies
        if let Some((s, e)) = ctx.front_matter {
            for i in s + 1..e {
                let l = ctx.line(i);
                if !self.front_matter_title.is_empty() && (l.starts_with(&format!("{}:", self.front_matter_title)) || l.starts_with(&format!("{} =", self.front_matter_title))) {
                    return out;
                }
                if !self.front_matter_title_pattern.is_empty() {
                    if let Ok(re) = regex::Regex::new(&self.front_matter_title_pattern) {
                        if re.is_match(l) {
                            return out;
                        }
                    }
                }
            }
        }
        // first non-blank, non-front-matter, non-comment line
        let start = ctx.front_matter.map(|(_, e)| e + 1).unwrap_or(0);
        let n = ctx.line_count();
        let mut i = start;
        while i < n {
            if ctx.lines[i].blank || ctx.lines[i].in_comment {
                i += 1;
                continue;
            }
            break;
        }
        if i >= n {
            return out;
        }
        // html comment block lines handled; check heading
        if let Some(h) = ctx.heading_at(i) {
            if h.level == self.level && is_valid_heading(ctx, h) {
                return out;
            }
        }
        // allow html <h1> at start
        let t = ctx.line(i).trim_start().to_ascii_lowercase();
        if t.starts_with(&format!("<h{}", self.level)) {
            return out;
        }
        let line = ctx.line(i);
        let w = Warning::new("MD041", i + 1, 1, format!("First line in file should be a level {} heading", self.level)).with_end(i + 1, line.len() + 1);
        out.push(w);
        out
    }
}

// ---------------- MD043 ----------------
pub struct MD043 {
    headings: Vec<String>,
    match_case: bool,
}
impl MD043 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD043 { headings: rc.get_str_vec("headings").unwrap_or_default(), match_case: rc.get_bool("match-case").unwrap_or(false) }
    }
}
impl Rule for MD043 {
    fn name(&self) -> &'static str {
        "MD043"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        if self.headings.is_empty() {
            return out;
        }
        let actual: Vec<&Heading> = ctx.headings.iter().filter(|h| is_valid_heading(ctx, h)).collect();
        let norm = |s: &str| if self.match_case { s.to_string() } else { s.to_lowercase() };
        let actual_strs: Vec<String> = actual.iter().map(|h| norm(&format!("{} {}", "#".repeat(h.level), h.text.trim()))).collect();
        let required: Vec<String> = self.headings.iter().map(|s| norm(s)).collect();
        // simple comparison with wildcard "*" support
        let mut ai = 0;
        let mut ri = 0;
        let mut ok = true;
        while ri < required.len() {
            if required[ri] == "*" {
                // match zero or more
                if ri + 1 >= required.len() {
                    ai = actual_strs.len();
                    ri += 1;
                    break;
                }
                let next = &required[ri + 1];
                while ai < actual_strs.len() && &actual_strs[ai] != next {
                    ai += 1;
                }
                ri += 1;
                continue;
            }
            if ai < actual_strs.len() && actual_strs[ai] == required[ri] {
                ai += 1;
                ri += 1;
            } else {
                ok = false;
                break;
            }
        }
        if ok && ai < actual_strs.len() {
            ok = false;
        }
        if !ok {
            let (line, col, len) = if ai < actual.len() {
                let h = actual[ai];
                (h.line + 1, 1, ctx.line(h.line).len())
            } else if let Some(h) = actual.last() {
                (h.line + 1, 1, ctx.line(h.line).len())
            } else {
                (1, 1, 0)
            };
            out.push(Warning::new("MD043", line, col, "Heading structure does not match the required structure".to_string()).with_end(line, len + 1));
        }
        out
    }
}

// ---------------- MD063 (opt-in) ----------------
pub struct MD063 {
    style: String,
    lowercase_words: Vec<String>,
    ignore_words: Vec<String>,
    min_level: usize,
    max_level: usize,
}
impl MD063 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD063 {
            style: rc.get_str("style").unwrap_or_else(|| "title_case".to_string()),
            lowercase_words: rc.get_str_vec("lowercase-words").unwrap_or_else(|| {
                ["a", "an", "and", "as", "at", "but", "by", "for", "from", "in", "into", "nor", "of", "off", "on", "or", "per", "so", "the", "to", "up", "via", "with", "yet"].iter().map(|s| s.to_string()).collect()
            }),
            ignore_words: rc.get_str_vec("ignore-words").unwrap_or_default(),
            min_level: rc.get_usize("min-level").unwrap_or(1),
            max_level: rc.get_usize("max-level").unwrap_or(6),
        }
    }
    fn title_case(&self, text: &str) -> String {
        let words: Vec<&str> = text.split(' ').collect();
        let mut out = Vec::new();
        for (i, w) in words.iter().enumerate() {
            if w.is_empty() {
                out.push(w.to_string());
                continue;
            }
            if self.ignore_words.iter().any(|x| x == w) {
                out.push(w.to_string());
                continue;
            }
            if w.starts_with('`') || w.chars().any(|c| c.is_ascii_digit()) || w.chars().filter(|c| c.is_uppercase()).count() > 1 {
                out.push(w.to_string());
                continue;
            }
            let lower = w.to_lowercase();
            if i != 0 && i != words.len() - 1 && self.lowercase_words.contains(&lower) {
                out.push(lower);
            } else {
                let mut c = w.chars();
                let first = c.next().unwrap().to_uppercase().collect::<String>();
                out.push(format!("{}{}", first, c.as_str()));
            }
        }
        out.join(" ")
    }
}
impl Rule for MD063 {
    fn name(&self) -> &'static str {
        "MD063"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for h in &ctx.headings {
            if !is_valid_heading(ctx, h) || h.level < self.min_level || h.level > self.max_level {
                continue;
            }
            let text = h.text.trim();
            if text.is_empty() {
                continue;
            }
            let expected = match self.style.as_str() {
                "sentence_case" | "sentence-case" => {
                    let mut c = text.chars();
                    let first = c.next().unwrap().to_uppercase().collect::<String>();
                    format!("{}{}", first, c.as_str())
                }
                _ => self.title_case(text),
            };
            if expected != text {
                let line = ctx.line(h.line);
                let prefix = &line[..h.prefix_len + h.indent];
                let fixed = Heading { text: expected.clone(), ..h.clone() };
                let rep = match h.style {
                    HeadingStyle::Atx => render_atx(&fixed, h.level, false, prefix),
                    HeadingStyle::AtxClosed => render_atx(&fixed, h.level, true, prefix),
                    HeadingStyle::Setext => format!("{}{}", prefix, expected),
                };
                out.push(
                    Warning::new("MD063", h.line + 1, h.text_col + 1, format!("Heading should use {}: '{}'", self.style.replace('-', "_"), expected))
                        .with_end(h.line + 1, line.len() + 1)
                        .with_fix(ctx.lines[h.line].start, ctx.line_end(h.line), rep),
                );
            }
        }
        out
    }
}

