        let mut out = Vec::new();
        for h in &ctx.headings {
            if h.style == HeadingStyle::Setext || !is_valid_heading(ctx, h) {
                continue;
            }
            let line = ctx.line(h.line);
            let rest = &line[h.prefix_len + h.indent..];
            let after = &rest[h.level..];
            let sp = after.len() - after.trim_start_matches([' ', '\t']).len();
            if sp > 1 && !after.trim().is_empty() && h.style == HeadingStyle::Atx {
                let col = h.prefix_len + h.indent + h.level + 1;
                let msg = format!("Multiple spaces ({}) after {} in heading", sp, "#".repeat(h.level));
                let s = ctx.lines[h.line].start + h.prefix_len + h.indent + h.level;
                let w = Warning::new("MD019", h.line + 1, col, msg).with_end(h.line + 1, col + sp).with_fix(s, s + sp, " ");
                out.push(w);
            } else if sp > 1 && after.trim().is_empty() {
                let col = h.prefix_len + h.indent + h.level + 1;
                let msg = format!("Multiple spaces ({}) after {} in heading", sp, "#".repeat(h.level));
                let s = ctx.lines[h.line].start + h.prefix_len + h.indent + h.level;
                let w = Warning::new("MD019", h.line + 1, col, msg).with_end(h.line + 1, col + sp).with_fix(s, s + sp, "");
                out.push(w);
            } else if sp > 1 && h.style == HeadingStyle::AtxClosed {
                let col = h.prefix_len + h.indent + h.level + 1;
                let msg = format!("Multiple spaces ({}) after {} in heading", sp, "#".repeat(h.level));
                let s = ctx.lines[h.line].start + h.prefix_len + h.indent + h.level;
                let w = Warning::new("MD019", h.line + 1, col, msg).with_end(h.line + 1, col + sp).with_fix(s, s + sp, " ");
