    max_level: usize,
}
impl MD063 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD063 {
            style: rc.get_str("style").unwrap_or_else(|| "title_case".to_string()),
            lowercase_words: rc.get_str_vec("lowercase-words").unwrap_or_else(|| {
                ["a", "an", "and", "as", "at", "but", "by", "for", "from", "in", "into", "nor", "of", "off", "on", "or", "per", "so", "the", "to", "up", "via", "with", "yet"].iter().map(|s| s.to_string()).collect()
            }),
            ignore_words: rc.get_str_vec("ignore-words").unwrap_or_default(),
            min_level: rc.get_usize("min-level").unwrap_or(1),
            max_level: rc.get_usize("max-level").unwrap_or(6),
        }
    }
    fn title_case(&self, text: &str) -> String {
        let words: Vec<&str> = text.split(' ').collect();
        let mut out = Vec::new();
        for (i, w) in words.iter().enumerate() {
            if w.is_empty() {
                out.push(w.to_string());
                continue;
            }
            if self.ignore_words.iter().any(|x| x == w) {
                out.push(w.to_string());
                continue;
            }
            if w.starts_with('`') || w.chars().any(|c| c.is_ascii_digit()) || w.chars().filter(|c| c.is_uppercase()).count() > 1 {
                out.push(w.to_string());
                continue;
            }
            let lower = w.to_lowercase();
            if i != 0 && i != words.len() - 1 && self.lowercase_words.contains(&lower) {
                out.push(lower);
            } else {
                let mut c = w.chars();
                let first = c.next().unwrap().to_uppercase().collect::<String>();
                out.push(format!("{}{}", first, c.as_str()));
            }
        }
        out.join(" ")
    }
}
impl Rule for MD063 {
    fn name(&self) -> &'static str {
        "MD063"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for h in &ctx.headings {
            if !is_valid_heading(ctx, h) || h.level < self.min_level || h.level > self.max_level {
                continue;
            }
            let text = h.text.trim();
            if text.is_empty() {
                continue;
            }
            let expected = match self.style.as_str() {
                "sentence_case" | "sentence-case" => {
                    let mut c = text.chars();
                    let first = c.next().unwrap().to_uppercase().collect::<String>();
                    format!("{}{}", first, c.as_str())
                }
                _ => self.title_case(text),
            };
            if expected != text {
                let line = ctx.line(h.line);
                let prefix = &line[..h.prefix_len + h.indent];
                let fixed = Heading { text: expected.clone(), ..h.clone() };
                let rep = match h.style {
                    HeadingStyle::Atx => render_atx(&fixed, h.level, false, prefix),
                    HeadingStyle::AtxClosed => render_atx(&fixed, h.level, true, prefix),
                    HeadingStyle::Setext => format!("{}{}", prefix, expected),
                };
                out.push(
                    Warning::new("MD063", h.line + 1, h.text_col + 1, format!("Heading should use {}: '{}'", self.style.replace('-', "_"), expected))
                        .with_end(h.line + 1, line.len() + 1)
                        .with_fix(ctx.lines[h.line].start, ctx.line_end(h.line), rep),
                );
            }
        }
        out
    }
}

