            // multi-paragraph: any blank line within block followed by continuation
            let mut multi = false;
            for l in block.start..block.end {
                if ctx.lines[l].blank {
                    multi = true;
                    break;
                }
            }
            for &idx in &block.items {
                let it = &ctx.list_items[idx];
                if !it.has_content {
                    continue;
