use super::Rule;
use crate::config::RuleConfig;
use crate::ctx::{is_hr_line, leading_ws_bytes, parse_list_marker, strip_blockquote, visual_indent, Ctx, ListItem};
use crate::warning::Warning;

/// A contiguous list block (sequence of list items + continuation lines)
#[derive(Debug, Clone)]
pub struct ListBlock {
    pub start: usize,      // first item line
    pub end: usize,        // last line belonging to the list (non-blank)
    pub items: Vec<usize>, // indices into ctx.list_items
    pub ordered: bool,
}

/// Compute list blocks (top-level grouping). Items inside blockquotes are grouped separately by depth.
pub fn list_blocks(ctx: &Ctx) -> Vec<ListBlock> {
    let n = ctx.line_count();
    let mut blocks = Vec::new();
    let mut i = 0;
    while i < n {
        let li = match ctx.lines[i].list_item {
            Some(idx) if !ctx.skip_line(i) => idx,
            _ => {
                i += 1;
                continue;
            }
        };
        let first = &ctx.list_items[li];
        let bq = ctx.lines[i].bq_depth;
        let mut block = ListBlock { start: i, end: i, items: vec![li], ordered: first.ordered };
        let mut j = i + 1;
        let mut last_nonblank = i;
        while j < n {
            if ctx.lines[j].bq_depth != bq && !ctx.lines[j].blank {
                break;
            }
            if ctx.lines[j].blank {
                // look ahead
                let mut k = j;
                while k < n && ctx.lines[k].blank {
                    k += 1;
                }
                if k >= n {
                    break;
                }
                if ctx.lines[k].bq_depth != bq {
                    break;
                }
                if let Some(idx) = ctx.lines[k].list_item {
                    let it = &ctx.list_items[idx];
                    // same type at top level of this block or nested
                    if it.indent > first.indent || (it.ordered == first.ordered) {
                        if ctx.skip_line(k) {
                            break;
                        }
                        j = k;
                        continue;
                    }
                    break;
                }
                // indented continuation
                let (_, _, rest) = strip_blockquote(ctx.line(k));
                let ind = visual_indent(rest);
                if ind >= 2 && ind >= first.content_col.min(ind) && !ctx.lines[k].heading.is_some() {
                    j = k;
                    continue;
                }
                break;
            }
            if let Some(idx) = ctx.lines[j].list_item {
                if ctx.skip_line(j) {
                    break;
                }
                let it = &ctx.list_items[idx];
                if it.indent <= first.indent && it.ordered != first.ordered {
                    break;
                }
                block.items.push(idx);
                last_nonblank = j;
                j += 1;
                continue;
            }
            if ctx.lines[j].in_list || ctx.lines[j].in_code || ctx.lines[j].is_fence {
                // continuation (indented or lazy) or code inside list
                let (_, _, rest) = strip_blockquote(ctx.line(j));
                let ind = visual_indent(rest);
                if ctx.lines[j].in_code || ctx.lines[j].is_fence {
                    if ind >= 2 || ctx.code_block_at(j).map(|cb| cb.indent >= 2).unwrap_or(false) {
                        last_nonblank = j;
                        j += 1;
                        continue;
                    }
                    break;
                }
                if ctx.lines[j].heading.is_some() && ind < 2 {
                    break;
                }
                last_nonblank = j;
                j += 1;
                continue;
            }
            break;
        }
        block.end = last_nonblank;
        blocks.push(block);
        i = last_nonblank + 1;
    }
    blocks
}

fn replace_line_prefix(ctx: &Ctx, line: usize, new_indent: usize, item: &ListItem) -> (usize, usize, String) {
    // returns fix range replacing the indentation (after bq prefix) with new_indent spaces
    let start = ctx.lines[line].start + item.prefix_len;
    let end = ctx.lines[line].start + item.marker_byte;
    (start, end, " ".repeat(new_indent))
}

// ---------------- MD004 ----------------
pub struct MD004 {
    style: String,
}
impl MD004 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD004 { style: rc.get_str("style").unwrap_or_else(|| "consistent".to_string()).to_lowercase() }
    }
}
fn marker_for_style(style: &str) -> Option<char> {
    match style {
        "asterisk" => Some('*'),
        "plus" => Some('+'),
        "dash" => Some('-'),
        _ => None,
    }
}
impl Rule for MD004 {
    fn name(&self) -> &'static str {
        "MD004"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let items: Vec<&ListItem> = ctx.list_items.iter().filter(|it| !it.ordered && !ctx.skip_line(it.line)).collect();
        if items.is_empty() {
            return out;
        }
        if self.style == "sublist" {
            // depth-based cycling: * + -
            let cycle = ['*', '+', '-'];
            let mut stack: Vec<usize> = Vec::new();
            for it in ctx.list_items.iter().filter(|it| !ctx.skip_line(it.line)) {
                while let Some(&top) = stack.last() {
                    if it.indent <= top {
                        stack.pop();
                    } else {
                        break;
                    }
                }
                let depth = stack.len();
                stack.push(it.indent);
                if it.ordered {
                    continue;
                }
                let expected = cycle[depth % 3];
                let actual = it.marker.chars().next().unwrap();
                if actual != expected {
                    out.push(mk004(ctx, it, actual, expected));
                }
            }
            return out;
        }
        let target = match marker_for_style(&self.style) {
            Some(c) => c,
            None => {
                // consistent: most prevalent; tie -> first marker used? per docs dash preferred
                let mut counts = [0usize; 3];
                for it in &items {
                    match it.marker.as_str() {
                        "*" => counts[0] += 1,
                        "+" => counts[1] += 1,
                        "-" => counts[2] += 1,
                        _ => {}
                    }
                }
                let max = *counts.iter().max().unwrap();
                if counts[2] == max {
                    '-'
                } else if counts[0] == max {
                    '*'
                } else {
                    '+'
                }
            }
        };
        for it in &items {
            let actual = it.marker.chars().next().unwrap();
            if actual != target {
                out.push(mk004(ctx, it, actual, target));
            }
        }
        out
    }
}
fn mk004(ctx: &Ctx, it: &ListItem, actual: char, expected: char) -> Warning {
    let pos = ctx.lines[it.line].start + it.marker_byte;
    Warning::new("MD004", it.line + 1, it.marker_byte + 1, format!("List marker '{}' does not match expected style '{}'", actual, expected))
        .with_end(it.line + 1, it.marker_byte + 2)
        .with_fix(pos, pos + 1, expected.to_string())
}

// ---------------- MD005 ----------------
pub struct MD005 {}
impl MD005 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD005 {}
    }
}
impl Rule for MD005 {
    fn name(&self) -> &'static str {
        "MD005"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for block in list_blocks(ctx) {
            // stack of item indents
            let mut stack: Vec<usize> = Vec::new();
            // expected indent keyed by parent indent (None for root)
            let mut expected: Vec<(Option<usize>, usize)> = Vec::new();
            for &idx in &block.items {
                let it = &ctx.list_items[idx];
                while let Some(&top) = stack.last() {
                    if it.indent <= top {
                        stack.pop();
                    } else {
                        break;
                    }
                }
                // child requires indent >= parent + 2
                while let Some(&top) = stack.last() {
                    if it.indent < top + 2 {
                        stack.pop();
                    } else {
                        break;
                    }
                }
                let parent = stack.last().copied();
                let exp = match parent {
                    None => 0,
                    Some(p) => {
                        if let Some(e) = expected.iter().find(|(k, _)| *k == Some(p)) {
                            e.1
                        } else {
                            expected.push((Some(p), it.indent));
                            it.indent
                        }
                    }
                };
                if it.indent != exp {
                    let (s, e, rep) = replace_line_prefix(ctx, it.line, exp, it);
                    out.push(
                        Warning::new("MD005", it.line + 1, 1, format!("Expected indentation of {} spaces, found {}", exp, it.indent))
                            .with_end(it.line + 1, ctx.line(it.line).len() + 1)
                            .with_fix(s, e, rep),
                    );
                }
                stack.push(it.indent);
            }
        }
        out
    }
}

// ---------------- MD007 ----------------
pub struct MD007 {
    indent: usize,
    start_indented: bool,
    start_indent: usize,
    fixed: bool,
}
impl MD007 {
    pub fn new(rc: &RuleConfig) -> Self {
        let indent = rc.get_usize("indent").unwrap_or(2);
        let style = rc.get_str("style");
        let fixed = match style.as_deref() {
            Some("fixed") => true,
            Some(_) => false,
            None => rc.get("indent").is_some(),
        };
        MD007 { indent, start_indented: rc.get_bool("start-indented").unwrap_or(false), start_indent: rc.get_usize("start-indent").unwrap_or(2), fixed }
    }
}
impl Rule for MD007 {
    fn name(&self) -> &'static str {
        "MD007"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for block in list_blocks(ctx) {
            // stack of (actual indent, expected indent, marker width, ordered)
            let mut stack: Vec<(usize, usize, usize, bool)> = Vec::new();
            for &idx in &block.items {
                let it = &ctx.list_items[idx];
                while let Some(&top) = stack.last() {
                    if it.indent <= top.0 {
                        stack.pop();
                    } else {
                        break;
                    }
                }
                if it.indent < 2 {
                    stack.clear();
                }
                let depth = stack.len();
                let expected = if depth == 0 {
                    if self.start_indented {
                        self.start_indent
                    } else {
                        0
                    }
                } else {
                    let parent = stack.last().unwrap();
                    if self.fixed && !parent.3 {
                        let base = if self.start_indented { self.start_indent } else { 0 };
                        base + self.indent * depth
                    } else {
                        parent.1 + parent.2 + 1
                    }
                };
                let mwidth = it.marker.len();
                if !it.ordered && it.indent != expected {
                    let (s, e, rep) = replace_line_prefix(ctx, it.line, expected, it);
                    out.push(
                        Warning::new("MD007", it.line + 1, 1, format!("Expected {} spaces for indent depth {}, found {}", expected, depth, it.indent))
                            .with_end(it.line + 1, ctx.line(it.line).len() + 1)
                            .with_fix(s, e, rep),
                    );
                }
                let eff_expected = if it.ordered { it.indent } else { expected };
                stack.push((it.indent, eff_expected, mwidth, it.ordered));
            }
        }
        out
    }
}

// ---------------- MD029 ----------------
pub struct MD029 {
    style: String,
}
impl MD029 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD029 { style: rc.get_str("style").unwrap_or_else(|| "one-or-ordered".to_string()).to_lowercase() }
    }
}
impl Rule for MD029 {
    fn name(&self) -> &'static str {
        "MD029"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        if !ctx.content.contains(['-', '*', '+']) {
            return out;
        }
        // group ordered items by (block, indent level): consecutive ordered items with same indent form a list
        for block in list_blocks(ctx) {
            // group items by indent within block, respecting nesting (a deeper item doesn't break the group)
            let mut groups: Vec<Vec<usize>> = Vec::new();
            let mut open: Vec<(usize, usize)> = Vec::new(); // (indent, group index)
            for &idx in &block.items {
                let it = &ctx.list_items[idx];
                if !it.marker.ends_with('.') {
                    // unordered or ')' style: closes deeper groups
                    open.retain(|(ind, _)| *ind < it.indent);
                    if !it.ordered {
                        // unordered item at this indent closes groups at >= this indent
                        open.retain(|(ind, _)| *ind < it.indent);
                    }
                    continue;
                }
                open.retain(|(ind, _)| *ind <= it.indent);
                if let Some(&(ind, g)) = open.last() {
                    if ind == it.indent {
                        groups[g].push(idx);
                        continue;
                    }
                }
                groups.push(vec![idx]);
                open.push((it.indent, groups.len() - 1));
            }
            for g in groups {
                let nums: Vec<u64> = g.iter().map(|&i| ctx.list_items[i].number.unwrap_or(0)).collect();
                let first = nums[0];
                let style = match self.style.as_str() {
                    "one" | "one-one" => "one",
                    "ordered" => "ordered",
                    "ordered0" => "ordered0",
                    _ => {
                        if nums.iter().all(|&n| n == 1) {
                            "one"
                        } else {
                            "ordered"
                        }
                    }
                };
                for (k, &idx) in g.iter().enumerate() {
                    let it = &ctx.list_items[idx];
                    let actual = nums[k];
                    let expected = match style {
                        "one" => 1,
                        "ordered0" => k as u64,
                        _ => {
                            if self.style == "ordered" {
                                (k as u64) + 1
                            } else {
                                first + k as u64
                            }
                        }
                    };
                    if actual != expected {
                        let fixable = match style {
                            "one" => true,
                            "ordered0" => true,
                            _ => first == 1 || self.style == "ordered",
                        };
                        let mut w = Warning::new("MD029", it.line + 1, it.marker_byte + 1, format!("Ordered list item number {} does not match list style '{}' (expected {})", actual, style, expected))
                            .with_end(it.line + 1, it.marker_byte + it.marker.len() + 1);
                        if fixable {
                            let s = ctx.lines[it.line].start + it.marker_byte;
                            let e = s + it.marker.len();
                            let delim = it.marker.chars().last().unwrap();
                            w = w.with_fix(s, e, format!("{}{}", expected, delim));
                        }
                        out.push(w);
                    }
                }
            }
        }
        out
    }
}

