impl MD030 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD030 {
            ul_single: rc.get_usize("ul-single").unwrap_or(1),
            ul_multi: rc.get_usize("ul-multi").unwrap_or(1),
            ol_single: rc.get_usize("ol-single").unwrap_or(1),
