                    let s = ctx.lines[it.line].start + after_marker;
                    out.push(
                        Warning::new("MD030", it.line + 1, after_marker + 1, format!("Spaces after list markers (Expected: {}; Actual: {})", expected, sp))
                            .with_end(it.line + 1, after_marker + sp + 1)
                            .with_fix(s, s + sp, " ".repeat(expected)),
