            let last = block.end;
            if last + 1 < n {
                let k = last + 1;
                let kl = &ctx.lines[k];
                if !kl.blank && kl.bq_depth == 0 {
                    let line = ctx.line(k);
                    let t = line.trim_start();
                    let is_heading = kl.heading.is_some();
                    let is_fence = kl.is_fence;
                    let is_table = kl.in_table;
                    let is_hr = is_hr_line(line) && visual_indent(line) < 4;
                    let is_other_list = kl.list_item.map(|i| ctx.list_items[i].ordered != first.ordered && ctx.list_items[i].indent <= first.indent).unwrap_or(false);
                    let _ = t;
                    if is_heading || is_fence || is_table || is_hr || is_other_list {
                        let pos = ctx.next_line_start(last);
                        out.push(
                            Warning::new("MD032", last + 1, 1, "List should be followed by blank line")
                                .with_end(last + 1, ctx.line(last).len() + 1)
                                .with_fix(pos, pos, "\n"),
                        );
                    }
                }
            }
        }
        out
    }
}

