                if ordered2 {
                    continue;
                }
                let after2 = &rest[mlen..];
                if !after2.starts_with(' ') || after2.trim().is_empty() {
                    continue;
                }
                // second marker followed by space: duplicate
                let s = ctx.lines[it.line].start + it.marker_byte;
                let e = s + it.marker.len() + sp;
                let _ = m2;
                out.push(
                    Warning::new("MD069", it.line + 1, it.marker_byte + 1, format!("Duplicate list marker '{} {}' found", it.marker, m2))
