            if width <= limit {
                continue;
            }
            let col = chars.min(limit) + 1;
            out.push(Warning::new("MD013", i + 1, col, format!("Line length {} exceeds {} characters", width, limit)).with_end(i + 1, chars + 1));
        }
        out
    }
    fn fix(&self, _ctx: &Ctx) -> Option<String> {
        None
    }
}

// ---------------- MD047 ----------------
pub struct MD047 {}
