// ---------------- MD064 ----------------
pub struct MD064 {
    allow_sentence_double_space: bool,
}
impl MD064 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD064 { allow_sentence_double_space: rc.get_bool("allow-sentence-double-space").unwrap_or(false) }
    }
}
impl Rule for MD064 {
    fn name(&self) -> &'static str {
        "MD064"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for i in 0..ctx.line_count() {
            let l = &ctx.lines[i];
            if l.in_code || l.is_fence || l.in_front_matter || l.in_table || l.in_html_block || l.in_comment || l.blank {
                continue;
            }
            let line = ctx.line(i);
            let trimmed_end = line.trim_end_matches([' ', '\t']);
            let lead = line.len() - line.trim_start_matches([' ', '\t']).len();
            // skip if list item: start after marker spaces
            let mut scan_from = lead;
            if let Some(it) = ctx.list_item_at(i) {
                scan_from = it.marker_byte + it.marker.len();
                let rest = &line[scan_from..];
                scan_from += rest.len() - rest.trim_start_matches([' ', '\t']).len();
            }
            if l.bq_depth > 0 {
                scan_from = scan_from.max(l.bq_prefix_len);
            }
            if let Some(h) = ctx.heading_at(i) {
                scan_from = scan_from.max(h.text_col.min(line.len()));
            }
            let masked = inline::mask_code_spans(line);
            // also mask html tags
            let masked = {
                let tags = inline::html_tags(&masked);
                let ranges: Vec<(usize, usize)> = tags.iter().map(|t| (t.start, t.end)).collect();
                inline::mask_ranges(&masked, &ranges)
            };
            if inline::html_tags(line).iter().any(|t| t.start == lead) {
                continue;
            }
            let bytes = masked.as_bytes();
            let mut j = scan_from;
            while j < trimmed_end.len() {
                if bytes[j] == b' ' {
                    let s = j;
                    while j < trimmed_end.len() && bytes[j] == b' ' {
                        j += 1;
                    }
                    let run = j - s;
                    if run >= 2 {
                        // check not inside code span (masked -> spaces too) : verify original has spaces
                        let orig = &line[s..j];
                        if orig.chars().all(|c| c == ' ') {
                            if self.allow_sentence_double_space && run == 2 && s > 0 && matches!(line.as_bytes()[s - 1], b'.' | b'!' | b'?') {
                                continue;
                            }
                            let col = line[..s].chars().count() + 1;
                            out.push(Warning::new("MD064", i + 1, col, format!("Multiple consecutive spaces ({}) found", run)).with_end(i + 1, col + run).with_fix(l.start + s, l.start + j, " "));
                        }
                    }
                } else {
                    j += 1;
                }
            }
        }
        out
    }
}
