impl MD046 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD046 { style: rc.get_str("style").unwrap_or_else(|| "consistent".to_string()).to_lowercase() }
    }
}
impl Rule for MD046 {
    fn name(&self) -> &'static str {
        "MD046"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let blocks: Vec<&crate::ctx::CodeBlock> = ctx.code_blocks.iter().filter(|cb| ctx.lines[cb.start].bq_depth == 0).collect();
        if blocks.is_empty() {
            return out;
        }
        let target = match self.style.as_str() {
            "fenced" => "fenced",
            "indented" => "indented",
            _ => {
                let fenced = blocks.iter().filter(|b| b.fenced).count();
                let indented = blocks.len() - fenced;
                if indented > fenced {
                    "indented"
                } else {
                    "fenced"
                }
            }
        };
        for cb in &blocks {
            if target == "fenced" && !cb.fenced {
                let line = ctx.line(cb.start);
                let mut w = Warning::new("MD046", cb.start + 1, 1, "Use fenced code blocks").with_end(cb.start + 1, line.len() + 1);
                // fix: convert to fenced only when indent is exactly 4 (top-level)
                if cb.indent == 4 {
                    let start = ctx.lines[cb.start].start;
                    let end = ctx.line_end(cb.end);
                    let mut rep = vec!["```text".to_string()];
                    for l in cb.start..=cb.end {
                        let ln = ctx.line(l);
                        if ctx.lines[l].blank {
                            rep.push(String::new());
                        } else {
                            let ws = ln.len() - ln.trim_start().len();
                            rep.push(ln[ws.min(4)..].to_string());
                        }
                    }
                    rep.push("```".to_string());
                    w = w.with_fix(start, end, rep.join("\n"));
                }
                out.push(w);
            } else if target == "indented" && cb.fenced {
                let line = ctx.line(cb.start);
                let mut w = Warning::new("MD046", cb.start + 1, 1, "Use indented code blocks").with_end(cb.start + 1, line.len() + 1);
                if cb.closed {
                    let start = ctx.lines[cb.start].start;
                    let end = ctx.line_end(cb.end);
                    let mut rep = Vec::new();
                    for l in cb.start + 1..cb.end {
                        let ln = ctx.line(l);
                        if ctx.lines[l].blank {
                            rep.push(String::new());
                        } else {
                            rep.push(format!("    {}", ln));
                        }
                    }
                    w = w.with_fix(start, end, rep.join("\n"));
                }
                out.push(w);
            }
        }
        out
    }
}

// ---------------- MD048 ----------------
pub struct MD048 {
    style: String,
}
impl MD048 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD048 { style: rc.get_str("style").unwrap_or_else(|| "consistent".to_string()).to_lowercase() }
    }
}
impl Rule for MD048 {
    fn name(&self) -> &'static str {
        "MD048"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let blocks: Vec<&crate::ctx::CodeBlock> = ctx.code_blocks.iter().filter(|cb| cb.fenced).collect();
        if blocks.is_empty() {
            return out;
        }
        let target = match self.style.as_str() {
            "backtick" => '`',
            "tilde" => '~',
            _ => {
                let bt = blocks.iter().filter(|b| b.fence_char == '`').count();
                let td = blocks.len() - bt;
                if td > bt {
                    '~'
                } else {
                    '`'
                }
            }
        };
        for cb in &blocks {
            if cb.fence_char == target {
                continue;
            }
            let mut lines = vec![cb.start];
            if cb.closed {
                lines.push(cb.end);
            }
            for &l in &lines {
                let line = ctx.line(l);
                let (_, plen, rest) = strip_blockquote(line);
                let ws = rest.len() - rest.trim_start().len();
                let fs = plen + ws;
                let run = line[fs..].chars().take_while(|&c| c == cb.fence_char).count();
                let rep = target.to_string().repeat(run);
                out.push(
                    Warning::new("MD048", l + 1, fs + 1, format!("Code fence style: use {} instead of {}", target.to_string().repeat(3), cb.fence_char.to_string().repeat(3)))
                        .with_end(l + 1, fs + run + 1)
                        .with_fix(ctx.lines[l].start + fs, ctx.lines[l].start + fs + run, rep),
                );
            }
        }
        out
    }
}

// ---------------- MD070 ----------------
pub struct MD070 {}
impl MD070 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD070 {}
    }
}
impl Rule for MD070 {
    fn name(&self) -> &'static str {
        "MD070"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        // Detect: fenced block with a language like markdown/md where content contains a fence of same char & length,
        // which closes it prematurely. Heuristic: a fenced block whose closing fence line is followed later by an
        // unmatched fence (odd number of fences) -> report.
        for (idx, cb) in ctx.code_blocks.iter().enumerate() {
            if !cb.fenced || !cb.closed {
                continue;
            }
            let lang = cb.info.split_whitespace().next().unwrap_or("").to_lowercase();
            if !["markdown", "md", "mdx"].contains(&lang.as_str()) {
                continue;
            }
            // the line after our opening fence is itself a fence opener with same char => nested collision
            if cb.end > cb.start + 1 {
                let inner = ctx.line(cb.start + 1).trim_start();
                let inner_run = inner.chars().take_while(|&c| c == cb.fence_char).count();
                if inner_run >= 3 && inner_run == cb.fence_len && idx + 1 < ctx.code_blocks.len() {
                    let fence = cb.fence_char.to_string().repeat(cb.fence_len);
                    let longer = cb.fence_char.to_string().repeat(cb.fence_len + 1);
                    out.push(
                        Warning::new("MD070", cb.start + 1, 1, format!("Nested {} at line {} closes block prematurely — use {} for outer fence", fence, cb.start + 2, longer))
                            .with_end(cb.start + 1, ctx.line(cb.start).len() + 1),
                    );
                }
            }
        }
        out
    }
}
