                let (_, _, prest) = strip_blockquote(ctx.line(p));
                let prev_blank = pl.blank || prest.trim().is_empty();
                if !prev_blank && !pl.in_front_matter && !(pl.list_item.is_some() && false) {
                    // list item line directly before a fence that belongs to it is still flagged by original
                    let pos = ctx.lines[cb.start].start;
                    let line = ctx.line(cb.start);
                    let rep = if pl.bq_depth > 0 { format!("{}\n", &ctx.line(cb.start)[..ctx.lines[cb.start].bq_prefix_len].trim_end()) } else { "\n".to_string() };
