                }
            }
            // after
            if cb.closed && cb.end + 1 < n {
                let k = cb.end + 1;
                let kl = &ctx.lines[k];
                let (_, _, krest) = strip_blockquote(ctx.line(k));
                let next_blank = kl.blank || krest.trim().is_empty();
                if !next_blank {
                    let pos = ctx.next_line_start(cb.end);
                    let line = ctx.line(cb.end);
                    let rep = if kl.bq_depth > 0 { format!("{}\n", &ctx.line(cb.end)[..ctx.lines[cb.end].bq_prefix_len].trim_end()) } else { "\n".to_string() };
                    out.push(Warning::new("MD031", cb.end + 1, 1, "No blank line after fenced code block").with_end(cb.end + 1, line.len() + 1).with_fix(pos, pos, rep));
                }
            }
        }
        out
    }
}

