impl Rule for MD038 {
    fn name(&self) -> &'static str {
        "MD038"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for i in 0..ctx.line_count() {
            let l = &ctx.lines[i];
            if l.in_code || l.is_fence || l.in_front_matter || l.in_html_block || l.in_comment {
                continue;
            }
            let line = ctx.line(i);
            if !line.contains('`') {
                continue;
            }
            for sp in inline::code_spans(line) {
                let raw = &line[sp.start..sp.end];
                let ticks = raw.chars().take_while(|&c| c == '`').count();
                let inner = &raw[ticks..raw.len() - ticks];
                if inner.trim().is_empty() {
                    continue;
                }
                let lead = inner.starts_with(' ');
                let trail = inner.ends_with(' ');
                // both sides single space with non-space content is allowed (CommonMark stripping)
                if lead && trail {
                    continue;
                }
                if !lead && !trail {
                    continue;
                }
                let col = line[..sp.start].chars().count() + 1;
                let fixed = format!("{}{}{}", "`".repeat(ticks), inner.trim(), "`".repeat(ticks));
                out.push(Warning::new("MD038", i + 1, col, "Spaces inside code span elements").with_end(i + 1, col + raw.chars().count()).with_fix(l.start + sp.start, l.start + sp.end, fixed));
            }
        }
        out
    }
}

