                let line = ctx.line(l);
                let (_, plen, rest) = strip_blockquote(line);
                let ws = rest.len() - rest.trim_start().len();
                let fs = plen + ws;
                let run = line[fs..].chars().take_while(|&c| c == cb.fence_char).count();
                let rep = target.to_string().repeat(run);
                out.push(
                    Warning::new("MD048", l + 1, fs + 1, format!("Code fence style: use {} instead of {}", target.to_string().repeat(3), cb.fence_char.to_string().repeat(3)))
                        .with_end(l + 1, fs + run + 1)
                        .with_fix(ctx.lines[l].start + fs, ctx.lines[l].start + fs + run, rep),
