fn trim_url_end(s: &str) -> &str {
    let mut end = s.len();
    let b = s.as_bytes();
    while end > 0 {
        let c = b[end - 1];
        if matches!(c, b'.' | b',' | b';' | b':' | b'!' | b'?' | b'\'' | b'"' | b'*' | b'_' | b'~') {
            end -= 1;
            continue;
        }
        if c == b')' {
            // unbalanced closing paren
            let opens = s[..end].matches('(').count();
            let closes = s[..end].matches(')').count();
            if closes > opens {
                end -= 1;
                continue;
            }
        }
        break;
    }
    &s[..end]
}
impl Rule for MD034 {
    fn name(&self) -> &'static str {
        "MD034"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let re_url = regex::Regex::new(r"(?:https?|ftp)://[^\s<>\[\]`'\x22]+").unwrap();
        let re_www = regex::Regex::new(r"\bwww\.[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+[^\s<>\[\]`'\x22]*").unwrap();
        let re_email = regex::Regex::new(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+").unwrap();
        for i in 0..ctx.line_count() {
            if skip_inline(ctx, i) {
                continue;
            }
            let line = ctx.line(i);
            if !(line.contains("://") || line.contains("www.") || line.contains('@')) {
                continue;
            }
            if ctx.is_refdef_line(i) {
                continue;
            }
            // mask code spans, links (whole), autolinks, html tags
            let spans = inline::code_spans(line);
            let mut ranges: Vec<(usize, usize)> = spans.iter().map(|s| (s.start, s.end)).collect();
            for l in inline::links(line) {
                ranges.push((l.start, l.end));
            }
            for t in inline::html_tags(line) {
                ranges.push((t.start, t.end));
            }
            let masked = inline::mask_ranges(line, &ranges);
            let mut taken: Vec<(usize, usize)> = Vec::new();
            let mut found: Vec<(usize, usize, bool)> = Vec::new(); // start,end,is_email
            for m in re_url.find_iter(&masked) {
                let url = trim_url_end(&line[m.start()..m.end()]);
                if url.is_empty() {
                    continue;
                }
                let end = m.start() + url.len();
                found.push((m.start(), end, false));
                taken.push((m.start(), end));
            }
            for m in re_www.find_iter(&masked) {
                if taken.iter().any(|&(a, b)| m.start() >= a && m.start() < b) {
                    continue;
                }
                // ensure not part of a URL (preceded by '/' or '.')
                if m.start() > 0 && matches!(line.as_bytes()[m.start() - 1], b'/' | b'.' | b'@') {
                    continue;
                }
                let url = trim_url_end(&line[m.start()..m.end()]);
                let end = m.start() + url.len();
                found.push((m.start(), end, false));
                taken.push((m.start(), end));
            }
            for m in re_email.find_iter(&masked) {
                if taken.iter().any(|&(a, b)| m.start() < b && m.end() > a) {
                    continue;
                }
                let e = trim_url_end(&line[m.start()..m.end()]);
                let end = m.start() + e.len();
                // skip if preceded by '/' (part of url path) 
                if m.start() > 0 && matches!(line.as_bytes()[m.start() - 1], b'/') {
                    continue;
                }
                found.push((m.start(), end, true));
            }
            found.sort_by_key(|f| f.0);
            for (s, e, is_email) in found {
                let text = &line[s..e];
                let col = col_of(line, s);
                let (msg, rep) = if is_email {
                    (format!("Email address without angle brackets or link formatting: '{}'", text), format!("<{}>", text))
                } else if text.starts_with("www.") {
                    (format!("URL without angle brackets or link formatting: '{}'", text), format!("<https://{}>", text))
                } else {
                    (format!("URL without angle brackets or link formatting: '{}'", text), format!("<{}>", text))
                };
                out.push(Warning::new("MD034", i + 1, col, msg).with_end(i + 1, col_of(line, e)).with_fix(ctx.lines[i].start + s, ctx.lines[i].start + e, rep));
            }
        }
        out
    }
