fn alt_from_url(url: &str) -> Option<String> {
    let u = url.trim();
    if u.is_empty() {
        return None;
    }
    let no_query = u.split(['?', '#']).next().unwrap_or("");
    let last = no_query.rsplit('/').next().unwrap_or("");
    let stem = match last.find('.') {
        Some(p) if p > 0 => &last[..p],
        Some(_) => last,
        None => last,
    };
    if stem.is_empty() {
        return None;
    }
    let words: Vec<String> = stem
        .replace(['-', '_'], " ")
        .split_whitespace()
        .map(|w| {
            let mut c = w.chars();
            match c.next() {
                Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
                None => String::new(),
            }
        })
        .collect();
    if words.is_empty() {
        return None;
    }
    Some(format!("{} image", words.join(" ")))
}
