        "MD053"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        if ctx.ref_defs.is_empty() {
            return out;
        }
        let mut used: HashSet<String> = HashSet::new();
        for i in 0..ctx.line_count() {
            if skip_inline(ctx, i) || ctx.is_refdef_line(i) {
                continue;
            }
            let line = ctx.line(i);
            for l in inline::links(line) {
                match l.kind {
