                        used.insert(normalize_label(&l.reference.clone().unwrap_or_default()));
                    }
                    _ => {}
                }
            }
        }
        for d in &ctx.ref_defs {
            let key = normalize_label(&d.label);
            if used.contains(&key) || self.ignored.iter().any(|x| normalize_label(x) == key) {
                continue;
            }
            let line = ctx.line(d.line);
            out.push(Warning::new("MD053", d.line + 1, 1, format!("Unused link/image reference: [{}]", key)).with_end(d.line + 1, line.len() + 1));
        }
        out
    }
