pub struct MD054 {
    autolink: bool,
    collapsed: bool,
    full: bool,
    inline: bool,
    shortcut: bool,
    url_inline: bool,
}
impl MD054 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD054 {
            autolink: rc.get_bool("autolink").unwrap_or(true),
            collapsed: rc.get_bool("collapsed").unwrap_or(true),
            full: rc.get_bool("full").unwrap_or(true),
            inline: rc.get_bool("inline").unwrap_or(true),
            shortcut: rc.get_bool("shortcut").unwrap_or(true),
            url_inline: rc.get_bool("url-inline").unwrap_or(true),
        }
    }
}
impl Rule for MD054 {
    fn name(&self) -> &'static str {
        "MD054"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        if self.autolink && self.collapsed && self.full && self.inline && self.shortcut && self.url_inline {
            return out;
        }
        let defs = ctx.ref_def_map();
        for i in 0..ctx.line_count() {
            if skip_inline(ctx, i) {
                continue;
            }
            let line = ctx.line(i);
            for l in inline::links(line) {
                let (bad, name) = match l.kind {
                    LinkKind::Autolink => (!self.autolink, "autolink"),
                    LinkKind::Collapsed => (!self.collapsed, "collapsed"),
                    LinkKind::Full => (!self.full, "full"),
                    LinkKind::Inline => {
                        if l.text == l.url && !self.url_inline {
                            (true, "url_inline")
                        } else {
                            (!self.inline, "inline")
                        }
                    }
                    LinkKind::Shortcut => {
                        if !defs.contains_key(&normalize_label(&l.text)) {
                            continue;
                        }
                        (!self.shortcut, "shortcut")
                    }
                };
                if bad {
                    let col = col_of(line, l.start);
                    out.push(Warning::new("MD054", i + 1, col, format!("Link/image style '{}' is not allowed", name)).with_end(i + 1, col_of(line, l.end)));
                }
            }
        }
        out
    }
}

// ---------------- MD057 ----------------
pub struct MD057 {
    pub base_dir: std::sync::Mutex<Option<std::path::PathBuf>>,
}
impl MD057 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD057 { base_dir: std::sync::Mutex::new(None) }
    }
