pub fn is_external_url(u: &str) -> bool {
    let l = u.to_lowercase();
    l.starts_with("http://") || l.starts_with("https://") || l.starts_with("ftp://") || l.starts_with("mailto:") || l.starts_with("tel:") || l.starts_with("//") || regex::Regex::new(r"^[a-z][a-z0-9+.-]*:").unwrap().is_match(&l)
}
pub fn md057_links(ctx: &Ctx, base: &std::path::Path) -> Vec<(usize, usize, usize, String, bool, usize)> {
    // returns (line idx, url_start byte, link_start byte, url, is_image, has_fragment)
    let mut res = Vec::new();
    let defs = ctx.ref_def_map();
    for i in 0..ctx.line_count() {
        if skip_inline(ctx, i) {
            continue;
        }
        let line = ctx.line(i);
        if !line.contains('[') {
            continue;
        }
        for l in inline::links(line) {
            let (url, ustart) = match l.kind {
                LinkKind::Inline => (l.url.clone(), l.url_start),
                LinkKind::Full | LinkKind::Collapsed | LinkKind::Shortcut => {
                    let r = l.reference.clone().unwrap_or_default();
                    match defs.get(&normalize_label(&r)) {
                        Some(_d) => continue, // reference defs are not checked
                        None => continue,
                    }
                }
                _ => continue,
            };
            let mut u = url.trim().to_string();
            if u.starts_with('<') && u.ends_with('>') {
                u = u[1..u.len() - 1].to_string();
            }
            if u.is_empty() || u.starts_with('#') || is_external_url(&u) || u.starts_with('/') {
                continue;
            }
            let has_frag = u.contains('#');
            let path_part = u.split(['#', '?']).next().unwrap_or("").to_string();
            if path_part.is_empty() {
                continue;
            }
            let decoded = percent_decode(&path_part);
            let target = base.join(&decoded);
            if target.exists() {
                continue;
            }
            // also try with .md extension for extensionless links
            res.push((i, ustart, l.start, path_part.clone(), l.image, if has_frag { 1 } else { 0 }));
        }
    }
    res
}
impl Rule for MD057 {
    fn name(&self) -> &'static str {
        "MD057"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let base = match self.base_dir.lock().unwrap().clone() {
            Some(b) => b,
            None => return out,
        };
        for (i, ustart, _lstart, url, _img, _frag) in md057_links(ctx, &base) {
            let line = ctx.line(i);
            let col = col_of(line, ustart);
            out.push(Warning::new("MD057", i + 1, col, format!("Relative link '{}' does not exist", url)).with_severity(Severity::Error).with_end(i + 1, col + url.chars().count()));
        }
        out
    }
    fn fix(&self, _ctx: &Ctx) -> Option<String> {
        None
    }
}

