impl Rule for MD062 {
    fn name(&self) -> &'static str {
        "MD062"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let re = regex::Regex::new(r"\]\(([ \t]*)([^)\s]*(?:[^)]*?)?)([ \t]*)\)").unwrap();
        for i in 0..ctx.line_count() {
            if skip_inline(ctx, i) {
                continue;
            }
            let line = ctx.line(i);
            if !line.contains("](") {
                continue;
            }
            let b = line.as_bytes();
            let masked = inline::mask_code_spans(line);
            for m in re.find_iter(&masked) {
                let c = re.captures(&masked[m.start()..m.end()]).unwrap();
                let lead = c.get(1).unwrap().as_str().len();
                let trail = c.get(3).unwrap().as_str().len();
                let inner = c.get(2).unwrap().as_str();
                if inner.starts_with('<') {
                    continue;
                }
                if inner.contains('"') || inner.contains('\'') {
                    // title present: only check leading
                    if lead == 0 {
                        continue;
                    }
                }
                if lead == 0 && trail == 0 {
                    continue;
                }
                // find link start '['
                let mut p = m.start();
                let mut depth = 0i32;
                let mut start = None;
                while p > 0 {
                    p -= 1;
                    if b[p] == b']' {
                        depth += 1;
                    } else if b[p] == b'[' {
                        if depth == 0 {
                            start = Some(p);
                            break;
                        }
                        depth -= 1;
                    }
                }
                let start = start.unwrap_or(m.start());
                let col = col_of(line, start);
                let msg = if lead > 0 && trail > 0 {
                    "Link destination has leading and trailing whitespace"
                } else if lead > 0 {
                    "Link destination has leading whitespace"
                } else {
                    "Link destination has trailing whitespace"
                };
                let paren_open = m.start() + 2;
                let paren_close = m.end() - 1;
                let fixed = line[paren_open..paren_close].trim().to_string();
                out.push(Warning::new("MD062", i + 1, col, msg).with_end(i + 1, col_of(line, m.end())).with_fix(ctx.lines[i].start + paren_open, ctx.lines[i].start + paren_close, fixed));
            }
        }
        out
    }
}
