pub fn strip_inline_markup(s: &str) -> String {
    let mut t = s.to_string();
    // images / links -> text
    let re_img = regex::Regex::new(r"!\[([^\]]*)\]\([^)]*\)").unwrap();
    t = re_img.replace_all(&t, "$1").to_string();
    let re_link = regex::Regex::new(r"\[([^\]]*)\]\([^)]*\)").unwrap();
    t = re_link.replace_all(&t, "$1").to_string();
    let re_ref = regex::Regex::new(r"\[([^\]]*)\]\[[^\]]*\]").unwrap();
    t = re_ref.replace_all(&t, "$1").to_string();
    let re_code = regex::Regex::new(r"`+([^`]*)`+").unwrap();
    t = re_code.replace_all(&t, "$1").to_string();
    let re_html = regex::Regex::new(r"<[^>]+>").unwrap();
    t = re_html.replace_all(&t, "").to_string();
    let re_emph = regex::Regex::new(r"[*_]{1,3}([^*_]+)[*_]{1,3}").unwrap();
    t = re_emph.replace_all(&t, "$1").to_string();
    t
}
pub fn github_anchor(text: &str) -> String {
    let t = strip_inline_markup(text.trim());
    let lower = t.to_lowercase();
    let mut out = String::new();
    for c in lower.chars() {
        if c.is_alphanumeric() || c == '_' {
            out.push(c);
        } else if c == ' ' || c == '-' {
            out.push('-');
        } else if c.is_whitespace() {
            out.push('-');
        }
        // other punctuation removed
    }
    out
}
pub fn heading_anchors(ctx: &Ctx) -> HashSet<String> {
    let mut set = HashSet::new();
    let mut counts: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    let re_attr = regex::Regex::new(r"\s*\{#([^}\s]+)\}\s*$").unwrap();
    for h in &ctx.headings {
        let mut text = h.text.clone();
        if let Some(c) = re_attr.captures(&text) {
            set.insert(c.get(1).unwrap().as_str().to_lowercase());
            text = re_attr.replace(&text, "").to_string();
        }
        let base = github_anchor(&text);
        let n = counts.entry(base.clone()).or_insert(0);
        let anchor = if *n == 0 { base.clone() } else { format!("{}-{}", base, n) };
        *n += 1;
        set.insert(anchor);
    }
    // html anchors
    let re_id = regex::Regex::new(r#"<[A-Za-z][^>]*\s(?:id|name)\s*=\s*["']([^"']+)["']"#).unwrap();
    for i in 0..ctx.line_count() {
        if ctx.lines[i].in_code || ctx.lines[i].is_fence {
            continue;
        }
        for c in re_id.captures_iter(ctx.line(i)) {
            set.insert(c.get(1).unwrap().as_str().to_lowercase());
        }
    }
    set
}
impl Rule for MD051 {
    fn name(&self) -> &'static str {
        "MD051"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let anchors = heading_anchors(ctx);
        for i in 0..ctx.line_count() {
            if skip_inline(ctx, i) {
                continue;
            }
            let line = ctx.line(i);
            if !line.contains("](#") {
                continue;
            }
            for l in inline::links(line) {
                if l.kind != LinkKind::Inline || l.image {
                    continue;
                }
                let url = l.url.trim();
                if !url.starts_with('#') || url.len() == 1 {
                    continue;
                }
                let frag = &url[1..];
                let frag_dec = percent_decode(frag).to_lowercase();
                if anchors.contains(&frag_dec) || anchors.contains(&frag.to_lowercase()) {
                    continue;
                }
                // GitHub line anchors like #L10
                if regex::Regex::new(r"^L\d+(C\d+)?(-L\d+(C\d+)?)?$").unwrap().is_match(frag) {
                    continue;
                }
                let col = col_of(line, l.start);
                out.push(Warning::new("MD051", i + 1, col, format!("Link anchor '{}' does not exist in document headings", url)).with_severity(Severity::Error).with_end(i + 1, col_of(line, l.end)));
            }
        }
        out
    }
}
fn percent_decode(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 {
            if let Ok(v) = u8::from_str_radix(&s[i + 1..i + 3], 16) {
                out.push(v);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    String::from_utf8(out).unwrap_or_else(|_| s.to_string())
}

