            if ctx.lines[prev].bq_depth == 0 || ctx.lines[prev].blank {
                continue;
            }
            let mut k = i;
            while k < n && ctx.lines[k].blank {
                k += 1;
            }
            if k >= n {
                continue;
            }
            if ctx.lines[k].bq_depth == 0 {
                continue;
            }
            let depth = ctx.lines[prev].bq_depth.min(ctx.lines[k].bq_depth);
            for b in i..k {
                let rep = ">".repeat(depth);
                let rep = if depth > 1 { rep.chars().map(|c| c.to_string()).collect::<Vec<_>>().join(" ") } else { rep };
                out.push(
                    Warning::new("MD028", b + 1, 1, format!("Blank line inside blockquote (level {})", depth))
                        .with_end(b + 1, ctx.line(b).len() + 1)
                        .with_fix(ctx.lines[b].start, ctx.line_end(b), rep),
                );
            }
        }
        out
    }
}

