// ---------------- MD044 ----------------
pub struct MD044 {
    names: Vec<String>,
    code_blocks: bool,
    html_elements: bool,
}
impl MD044 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD044 { names: rc.get_str_vec("names").unwrap_or_default(), code_blocks: rc.get_bool("code-blocks").unwrap_or(false), html_elements: rc.get_bool("html-elements").unwrap_or(true) }
    }
}
impl Rule for MD044 {
    fn name(&self) -> &'static str {
        "MD044"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        if self.names.is_empty() {
            return out;
        }
        for i in 0..ctx.line_count() {
            let l = &ctx.lines[i];
            if l.in_front_matter || l.in_comment {
                continue;
            }
            if (l.in_code || l.is_fence) && !self.code_blocks {
                continue;
            }
            if l.in_html_block && !self.html_elements {
                continue;
            }
            let line = ctx.line(i);
            // mask code spans and urls
            let spans = inline::code_spans(line);
            let mut ranges: Vec<(usize, usize)> = spans.iter().map(|s| (s.start, s.end)).collect();
            for lk in inline::links(line) {
                if lk.kind == inline::LinkKind::Inline {
                    ranges.push((lk.text_end, lk.end));
                } else if lk.kind == inline::LinkKind::Autolink {
                    ranges.push((lk.start, lk.end));
                }
            }
            for t in inline::html_tags(line) {
                ranges.push((t.start, t.end));
            }
            let masked = inline::mask_ranges(line, &ranges);
            for name in &self.names {
                let pat = format!(r"(?i)(?<![\w-]){}(?![\w-])", regex::escape(name));
                // regex crate lacks lookaround; emulate
                let _ = pat;
                let re = regex::Regex::new(&format!(r"(?i){}", regex::escape(name))).unwrap();
                for m in re.find_iter(&masked) {
                    let s = m.start();
                    let e = m.end();
                    let before_ok = s == 0 || !(masked.as_bytes()[s - 1].is_ascii_alphanumeric() || masked.as_bytes()[s - 1] == b'_' || masked.as_bytes()[s - 1] == b'-' || masked.as_bytes()[s - 1] == b'.' || masked.as_bytes()[s - 1] == b'/');
                    let after_ok = e >= masked.len() || !(masked.as_bytes()[e].is_ascii_alphanumeric() || masked.as_bytes()[e] == b'_' || masked.as_bytes()[e] == b'-' || masked.as_bytes()[e] == b'.');
                    if !before_ok || !after_ok {
                        continue;
                    }
                    let found = &line[s..e];
                    if found == name {
                        continue;
                    }
                    let col = col_of(line, s);
                    out.push(
                        Warning::new("MD044", i + 1, col, format!("Proper name '{}' should be '{}'", found, name))
                            .with_end(i + 1, col_of(line, e))
                            .with_fix(l.start + s, l.start + e, name.clone()),
                    );
                }
            }
        }
        out.sort_by_key(|w| (w.line, w.column));
        out
    }
}

