pub struct MD072 {}
impl MD072 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD072 {}
    }
}
impl Rule for MD072 {
    fn name(&self) -> &'static str {
        "MD072"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let (s, e) = match ctx.front_matter {
            Some(r) => r,
            None => return out,
        };
        let delim = ctx.line(s).trim();
        let kind = if delim == "+++" { "TOML" } else { "YAML" };
        // top-level keys: lines without leading whitespace of form key: or key =
        let mut keys: Vec<(usize, String)> = Vec::new();
        for i in s + 1..e {
            let l = ctx.line(i);
            if l.starts_with(' ') || l.starts_with('\t') || l.starts_with('#') || l.starts_with('-') || l.trim().is_empty() {
                continue;
            }
            let key = if kind == "TOML" {
                l.split('=').next().map(|k| k.trim().to_string())
            } else {
                l.split(':').next().map(|k| k.trim().to_string())
            };
            if let Some(k) = key {
                if !k.is_empty() {
                    keys.push((i, k));
                }
            }
        }
        for w in 1..keys.len() {
            if keys[w].1.to_lowercase() < keys[w - 1].1.to_lowercase() {
                let (li, _) = keys[w - 1];
                let _ = li;
                let line_idx = keys[w - 1].0;
                out.push(
                    Warning::new("MD072", line_idx + 1, 1, format!("{} frontmatter keys are not sorted alphabetically: '{}' should come before '{}'", kind, keys[w].1, keys[w - 1].1))
                        .with_end(line_idx + 1, ctx.line(line_idx).len() + 1)
                        .with_fix(ctx.lines[s + 1].start, ctx.line_end(e - 1), sorted_front_matter(ctx, s, e, kind)),
                );
                break;
            }
        }
        out
    }
}
fn sorted_front_matter(ctx: &Ctx, s: usize, e: usize, kind: &str) -> String {
    // group lines into top-level entries
    let mut entries: Vec<(String, Vec<&str>)> = Vec::new();
    for i in s + 1..e {
        let l = ctx.line(i);
        let is_top = !(l.starts_with(' ') || l.starts_with('\t') || l.starts_with('-') || l.trim().is_empty() || l.starts_with('#'));
        if is_top || entries.is_empty() {
            let key = if kind == "TOML" { l.split('=').next().unwrap_or("").trim().to_string() } else { l.split(':').next().unwrap_or("").trim().to_string() };
            entries.push((key, vec![l]));
        } else {
            entries.last_mut().unwrap().1.push(l);
        }
    }
    entries.sort_by(|a, b| a.0.to_lowercase().cmp(&b.0.to_lowercase()));
    let lines: Vec<&str> = entries.iter().flat_map(|e| e.1.iter().copied()).collect();
    lines.join("\n")
}

