use super::Rule;
use crate::config::RuleConfig;
use crate::ctx::Ctx;
use crate::inline;
use crate::warning::Warning;

fn skip_inline(ctx: &Ctx, i: usize) -> bool {
    let l = &ctx.lines[i];
    l.in_code || l.is_fence || l.in_front_matter || l.in_html_block || l.in_comment || l.in_math
}
fn col_of(line: &str, byte: usize) -> usize {
    line[..byte.min(line.len())].chars().count() + 1
}

#[derive(Debug, Clone)]
pub struct Emph {
    pub start: usize,
    pub end: usize,
    pub marker: char,
    pub strong: bool,
    pub inner_start: usize,
    pub inner_end: usize,
}

fn is_word_char(c: Option<char>) -> bool {
    c.map(|c| c.is_alphanumeric()).unwrap_or(false)
}

/// Find emphasis spans in a (code-masked) line. Simplified delimiter-run matching.
pub fn find_emphasis(line: &str) -> Vec<Emph> {
    let masked = inline::mask_code_and_links(line);
    let chars: Vec<(usize, char)> = masked.char_indices().collect();
    let mut res = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let (bi, c) = chars[i];
        if c == '\\' {
            i += 2;
            continue;
        }
        if c != '*' && c != '_' {
            i += 1;
            continue;
        }
        // run length
        let mut j = i;
        while j < chars.len() && chars[j].1 == c {
            j += 1;
        }
        let run = j - i;
        if run > 3 {
            i = j;
            continue;
        }
        let prev = if i > 0 { Some(chars[i - 1].1) } else { None };
        let next = if j < chars.len() { Some(chars[j].1) } else { None };
        // intraword underscore is not emphasis
        if c == '_' && is_word_char(prev) {
            i = j;
            continue;
        }
        // left-flanking: next is not whitespace (allow spaces inside for MD037 detection handled separately)
        let left_flanking = next.map(|n| !n.is_whitespace()).unwrap_or(false);
        if !left_flanking {
            i = j;
            continue;
        }
        // find closing run of the same char with the same length (or at least run)
        let mut k = j;
        let mut found = None;
        while k < chars.len() {
            let (_, ck) = chars[k];
            if ck == '\\' {
                k += 2;
                continue;
            }
            if ck == c {
                let mut m = k;
                while m < chars.len() && chars[m].1 == c {
                    m += 1;
                }
                let crun = m - k;
                let cprev = chars[k - 1].1;
                let cnext = if m < chars.len() { Some(chars[m].1) } else { None };
                let right_flanking = !cprev.is_whitespace();
                if c == '_' && is_word_char(cnext) {
                    k = m;
                    continue;
                }
                if right_flanking && crun >= run && k > j {
                    found = Some((k, m));
                    break;
                }
                if crun >= run && k > j && !right_flanking {
                    // closing run preceded by whitespace (MD037 case like "* text *") handled by caller
                    found = Some((k, m));
                    break;
                }
                k = m;
                continue;
            }
            k += 1;
        }
        if let Some((k, m)) = found {
            let _ = m;
            let end_byte = chars[k].0 + run * c.len_utf8();
            let inner_start = chars[j].0;
            let inner_end = chars[k].0;
            if run == 3 {
                res.push(Emph { start: bi, end: end_byte, marker: c, strong: true, inner_start, inner_end });
            } else {
                res.push(Emph { start: bi, end: end_byte, marker: c, strong: run == 2, inner_start, inner_end });
            }
            // continue scanning after the closing run
            i = k + run;
            continue;
        }
        i = j;
    }
    res
}

