        let mut out = Vec::new();
        // patterns: marker, spaces, text, spaces, marker ; or marker text spaces marker
        let re = regex::Regex::new(r"(\*\*|__|\*|_)( +)([^*_]+?)( *)(\*\*|__|\*|_)|(\*\*|__|\*|_)([^*_ ][^*_]*?)( +)(\*\*|__|\*|_)").unwrap();
        for i in 0..ctx.line_count() {
            if skip_inline(ctx, i) || ctx.lines[i].blank {
                continue;
            }
            let line = ctx.line(i);
            if !line.contains('*') && !line.contains('_') {
                continue;
            }
            let masked = inline::mask_code_and_links(line);
            let mut pos = 0;
            while pos < masked.len() {
                let m = match re.find_at(&masked, pos) {
                    Some(m) => m,
                    None => break,
                };
                let c = re.captures(&masked[m.start()..m.end()]).unwrap();
                let (open, lead, text, trail, close) = if c.get(1).is_some() {
                    (c.get(1).unwrap().as_str(), c.get(2).unwrap().as_str(), c.get(3).unwrap().as_str(), c.get(4).unwrap().as_str(), c.get(5).unwrap().as_str())
                } else {
                    (c.get(6).unwrap().as_str(), "", c.get(7).unwrap().as_str(), c.get(8).unwrap().as_str(), c.get(9).unwrap().as_str())
                };
                if open != close {
                    pos = m.start() + 1;
                    continue;
                }
                // for leading-space-only form like "* lead*": original doesn't flag; require trailing space or both
                if !lead.is_empty() && trail.is_empty() {
                    pos = m.start() + 1;
                    continue;
                }
                // list marker at line start "* text *" ambiguous: skip if at start of line and list item
                if ctx.lines[i].list_item.map(|li| ctx.list_items[li].marker_byte == m.start()).unwrap_or(false) {
                    pos = m.start() + 1;
                    continue;
                }
                // for underscore, require not intraword
                if open == "_" || open == "__" {
                    let prevc = line[..m.start()].chars().last();
                    if prevc.map(|c| c.is_alphanumeric()).unwrap_or(false) {
                        pos = m.start() + 1;
                        continue;
                    }
                }
                if text.trim().is_empty() {
                    pos = m.start() + 1;
                    continue;
                }
                let raw = &line[m.start()..m.end()];
                let fixed = format!("{}{}{}", open, text.trim(), close);
                let col = col_of(line, m.start());
                out.push(
                    Warning::new("MD037", i + 1, col, format!("Spaces inside emphasis markers: \"{}\"", raw))
                        .with_end(i + 1, col_of(line, m.end()))
                        .with_fix(ctx.lines[i].start + m.start(), ctx.lines[i].start + m.end(), fixed),
                );
                pos = m.end();
            }
        }
        out
    }
}

// ---------------- MD049 / MD050 ----------------
pub struct MD049 {
    style: String,
}
impl MD049 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD049 { style: rc.get_str("style").unwrap_or_else(|| "consistent".to_string()) }
    }
}
pub struct MD050 {
    style: String,
}
impl MD050 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD050 { style: rc.get_str("style").unwrap_or_else(|| "consistent".to_string()) }
    }
}
fn emphasis_style_check(ctx: &Ctx, strong: bool, style: &str, rule: &'static str) -> Vec<Warning> {
    let mut out = Vec::new();
    let mut all: Vec<(usize, Emph)> = Vec::new();
    for i in 0..ctx.line_count() {
        if skip_inline(ctx, i) || ctx.lines[i].blank {
            continue;
        }
        let line = ctx.line(i);
        if !line.contains('*') && !line.contains('_') {
            continue;
        }
        for e in find_emphasis(line) {
            let run = (e.inner_start - e.start) / e.marker.len_utf8();
            if run == 3 {
                continue;
            }
            if e.strong == strong {
                all.push((i, e));
            }
        }
    }
    if all.is_empty() {
        return out;
    }
    let target = match style {
        "asterisk" => '*',
        "underscore" => '_',
        _ => {
            let stars = all.iter().filter(|(_, e)| e.marker == '*').count();
            let unders = all.len() - stars;
            if stars > unders {
                '*'
            } else if unders > stars {
                '_'
            } else {
                all[0].1.marker
            }
        }
    };
    for (i, e) in all {
        if e.marker == target {
            continue;
        }
        let line = ctx.line(i);
        let n = if strong { 2 } else { 1 };
        let rep = format!("{}{}{}", target.to_string().repeat(n), &line[e.inner_start..e.inner_end], target.to_string().repeat(n));
        let msg = if strong {
            format!("Strong emphasis should use {} instead of {}", target.to_string().repeat(2), e.marker.to_string().repeat(2))
        } else {
            format!("Emphasis should use {} instead of {}", target, e.marker)
        };
        let col = col_of(line, e.start);
        out.push(Warning::new(rule, i + 1, col, msg).with_end(i + 1, col_of(line, e.end)).with_fix(ctx.lines[i].start + e.start, ctx.lines[i].start + e.end, rep));
    }
    out
}
impl Rule for MD049 {
    fn name(&self) -> &'static str {
        "MD049"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        emphasis_style_check(ctx, false, &self.style, "MD049")
    }
}
impl Rule for MD050 {
    fn name(&self) -> &'static str {
        "MD050"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        emphasis_style_check(ctx, true, &self.style, "MD050")
    }
}
