use super::Rule;
use crate::config::RuleConfig;
use crate::ctx::Ctx;
use crate::inline;
use crate::warning::{Severity, Warning};

pub struct FootnoteDef {
    pub line: usize,
    pub label: String,
    pub content: String,
}

pub fn footnote_defs(ctx: &Ctx) -> Vec<FootnoteDef> {
    let re = regex::Regex::new(r"^\[\^([^\]\s]+)\]:(.*)$").unwrap();
    let mut res = Vec::new();
    for i in 0..ctx.line_count() {
        if ctx.skip_line(i) {
            continue;
        }
        if let Some(c) = re.captures(ctx.line(i)) {
            res.push(FootnoteDef { line: i, label: c.get(1).unwrap().as_str().to_string(), content: c.get(2).unwrap().as_str().to_string() });
        }
    }
    res
}

pub fn footnote_refs(ctx: &Ctx) -> Vec<(usize, usize, String)> {
    // (line, byte col, label) in document order
    let re = regex::Regex::new(r"\[\^([^\]\s]+)\]").unwrap();
    let mut res = Vec::new();
    for i in 0..ctx.line_count() {
        if ctx.skip_line(i) || ctx.lines[i].in_html_block || ctx.lines[i].in_comment {
            continue;
        }
        let line = ctx.line(i);
        if !line.contains("[^") {
            continue;
        }
        let masked = inline::mask_code_spans(line);
        for m in re.find_iter(&masked) {
            // skip definitions
            if m.start() == 0 && line[m.end()..].starts_with(':') {
                continue;
            }
            let c = re.captures(&masked[m.start()..m.end()]).unwrap();
            res.push((i, m.start(), c.get(1).unwrap().as_str().to_string()));
        }
    }
    res
}

fn col_of(line: &str, byte: usize) -> usize {
    line[..byte.min(line.len())].chars().count() + 1
}

// ---------------- MD066 ----------------
pub struct MD066 {}
impl MD066 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD066 {}
    }
}
impl Rule for MD066 {
    fn name(&self) -> &'static str {
        "MD066"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        if !ctx.content.contains("[^") {
            return out;
        }
        let defs = footnote_defs(ctx);
        let refs = footnote_refs(ctx);
        let mut seen_defs: Vec<(String, usize)> = Vec::new();
        for d in &defs {
            if let Some((_, first)) = seen_defs.iter().find(|(l, _)| l == &d.label) {
                out.push(
                    Warning::new("MD066", d.line + 1, 1, format!("Duplicate footnote definition '[^{}]' (first defined on line {})", d.label, first + 1))
                        .with_severity(Severity::Error)
                        .with_end(d.line + 1, ctx.line(d.line).len() + 1),
                );
            } else {
                seen_defs.push((d.label.clone(), d.line));
            }
        }
        for (i, b, label) in &refs {
            if !defs.iter().any(|d| &d.label == label) {
                let line = ctx.line(*i);
                let col = col_of(line, *b);
                out.push(Warning::new("MD066", i + 1, col, format!("Footnote reference '[^{}]' has no corresponding definition", label)).with_severity(Severity::Error).with_end(i + 1, col + label.len() + 3));
            }
        }
        for d in &defs {
            if !refs.iter().any(|(_, _, l)| l == &d.label) {
                out.push(Warning::new("MD066", d.line + 1, 1, format!("Footnote definition '[^{}]' is never referenced", d.label)).with_severity(Severity::Error).with_end(d.line + 1, ctx.line(d.line).len() + 1));
            }
        }
        out.sort_by_key(|w| (w.line, w.column));
        out
    }
    fn fix(&self, _ctx: &Ctx) -> Option<String> {
        None
    }
}

