    fn name(&self) -> &'static str {
        "MD067"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        if !ctx.content.contains("[^") {
            return out;
        }
        let defs = footnote_defs(ctx);
        let refs = footnote_refs(ctx);
        // reference order (first occurrence)
        let mut order: Vec<String> = Vec::new();
        for (_, _, l) in &refs {
            if !order.contains(l) {
                order.push(l.clone());
            }
        }
        // expected order of definitions: referenced ones in reference order (only those defined)
        let expected: Vec<&String> = order.iter().filter(|l| defs.iter().any(|d| &d.label == *l)).collect();
        let mut ei = 0;
        for d in &defs {
            if !order.contains(&d.label) {
                continue;
            }
            if ei < expected.len() && &d.label != expected[ei] {
                out.push(
                    Warning::new("MD067", d.line + 1, 1, format!("Footnote definition '[^{}]' is out of order; expected '[^{}]' next (based on reference order)", d.label, expected[ei]))
                        .with_end(d.line + 1, ctx.line(d.line).len() + 1),
                );
                // keep ei (do not advance) to match original single-stream behaviour
                ei += 1;
                continue;
            }
            ei += 1;
        }
        out
    }
    fn fix(&self, _ctx: &Ctx) -> Option<String> {
        None
    }
}

// ---------------- MD068 ----------------
pub struct MD068 {}
impl MD068 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD068 {}
    }
