impl Rule for MD068 {
    fn name(&self) -> &'static str {
        "MD068"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        if !ctx.content.contains("[^") {
            return out;
        }
        let n = ctx.line_count();
        for d in footnote_defs(ctx) {
            if !d.content.trim().is_empty() {
                continue;
            }
            // continuation lines indented?
            let mut has_cont = false;
            let mut k = d.line + 1;
            while k < n {
                if ctx.lines[k].blank {
                    k += 1;
                    continue;
                }
                let l = ctx.line(k);
                if l.starts_with("    ") || l.starts_with('\t') {
                    has_cont = true;
                }
                break;
            }
            if has_cont {
                continue;
            }
            out.push(Warning::new("MD068", d.line + 1, 1, format!("Footnote definition '[^{}]' is empty", d.label)).with_severity(Severity::Error).with_end(d.line + 1, ctx.line(d.line).len() + 1));
        }
        out
    }
    fn fix(&self, _ctx: &Ctx) -> Option<String> {
        None
    }
}
