                "no_leading_or_trailing" | "no-leading-or-trailing" => (false, false),
                _ => (first_rest_lead, first_rest_trail),
            };
            for &i in &rows {
                let line = ctx.line(i);
                let (_, plen, rest) = strip_blockquote(line);
                let (l, r) = pipe_style(rest);
                if l == tl && r == tt {
                    continue;
                }
                let ws = rest.len() - rest.trim_start().len();
                let trimmed = rest.trim();
                let mut inner = trimmed.to_string();
                if l {
                    inner = inner[1..].to_string();
                }
                if r && inner.ends_with('|') {
                    inner = inner[..inner.len() - 1].to_string();
                }
                let inner = inner.trim();
                let mut fixed = String::new();
                if tl {
                    fixed.push_str("| ");
                }
                fixed.push_str(inner);
                if tt {
                    fixed.push_str(" |");
                }
                let s = ctx.lines[i].start + plen + ws;
                let e = ctx.lines[i].start + plen + ws + rest.trim_end().len() - ws;
                let e = e.min(ctx.line_end(i));
                out.push(
                    Warning::new("MD055", i + 1, 1, format!("Table pipe style should be {}", style_name(tl, tt)))
                        .with_end(i + 1, line.len() + 1)
                        .with_fix(s, e, fixed),
                );
            }
        }
        out
    }
}

// ---------------- MD056 ----------------
pub struct MD056 {}
impl MD056 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD056 {}
    }
}
impl Rule for MD056 {
    fn name(&self) -> &'static str {
        "MD056"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for t in &ctx.tables {
            let (_, _, hrest) = strip_blockquote(ctx.line(t.start));
            let expected = split_cells(hrest).len();
            for i in t.start..=t.end {
                if i == t.delimiter {
                    let (_, _, r) = strip_blockquote(ctx.line(i));
                    let n = split_cells(r).len();
                    if n != expected {
                        out.push(mk056(ctx, i, n, expected, t));
                    }
                    continue;
                }
                let line = ctx.line(i);
                let (_, _, rest) = strip_blockquote(line);
                let n = split_cells(rest).len();
                if n != expected {
                    out.push(mk056(ctx, i, n, expected, t));
                }
            }
        }
        out
    }
}
fn mk056(ctx: &Ctx, i: usize, n: usize, expected: usize, _t: &Table) -> Warning {
    let line = ctx.line(i);
    let (_, plen, rest) = strip_blockquote(line);
    let mut w = Warning::new("MD056", i + 1, 1, format!("Table row has {} cells, but expected {}", n, expected)).with_end(i + 1, line.len() + 1);
    let cells = split_cells(rest);
    let (lead, trail) = pipe_style(rest);
    let fixed: String = if n < expected {
        let mut cs: Vec<String> = cells.iter().map(|c| c.to_string()).collect();
        for _ in n..expected {
            cs.push("  ".to_string());
        }
        let mut s = String::new();
        if lead {
            s.push('|');
        }
        s.push_str(&cs.join("|"));
        if trail {
            s.push('|');
        }
        s
    } else {
        let cs: Vec<String> = cells.iter().take(expected).map(|c| c.to_string()).collect();
        let mut s = String::new();
        if lead {
            s.push('|');
        }
        s.push_str(&cs.join("|"));
        if trail {
            s.push('|');
        }
        s
    };
    let ws = rest.len() - rest.trim_start().len();
    let s = ctx.lines[i].start + plen + ws;
    let e = ctx.lines[i].start + plen + rest.trim_end().len();
    w = w.with_fix(s, e, fixed);
    w
}

// ---------------- MD058 ----------------
pub struct MD058 {
    before: usize,
    after: usize,
}
impl MD058 {
    pub fn new(rc: &RuleConfig) -> Self {
        MD058 { before: rc.get_usize("minimum-before").unwrap_or(1), after: rc.get_usize("minimum-after").unwrap_or(1) }
    }
}
impl Rule for MD058 {
    fn name(&self) -> &'static str {
        "MD058"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        let n = ctx.line_count();
        for t in &ctx.tables {
            if ctx.lines[t.start].bq_depth > 0 {
                continue;
            }
            if t.start > 0 {
                let mut blanks = 0;
                let mut j = t.start;
                while j > 0 && ctx.lines[j - 1].blank {
                    blanks += 1;
                    j -= 1;
                }
                let at_start = j == 0 || ctx.front_matter.map(|(_, e)| j == e + 1).unwrap_or(false);
                if blanks < self.before && !at_start && !ctx.lines[j - 1].in_comment {
                    let pos = ctx.lines[t.start].start;
                    out.push(Warning::new("MD058", t.start + 1, 1, "Missing blank line before table").with_end(t.start + 1, ctx.line(t.start).len() + 1).with_fix(pos, pos, "\n".repeat(self.before - blanks)));
                }
            }
            if t.end + 1 < n {
                let mut blanks = 0;
                let mut k = t.end + 1;
                while k < n && ctx.lines[k].blank {
                    blanks += 1;
                    k += 1;
                }
                if k < n && blanks < self.after {
                    let pos = ctx.next_line_start(t.end);
                    let line = ctx.line(t.end);
                    let col = line.chars().count() + 1;
                    out.push(Warning::new("MD058", t.end + 1, col, "Missing blank line after table").with_end(t.end + 1, col).with_fix(pos, pos, "\n".repeat(self.after - blanks)));
                }
            }
        }
        out
    }
}

// ---------------- MD060 (opt-in) ----------------
pub struct MD060 {}
impl MD060 {
    pub fn new(_rc: &RuleConfig) -> Self {
        MD060 {}
    }
}
impl Rule for MD060 {
    fn name(&self) -> &'static str {
        "MD060"
    }
    fn check(&self, ctx: &Ctx) -> Vec<Warning> {
        let mut out = Vec::new();
        for t in &ctx.tables {
            // compute column widths
            let rows: Vec<Vec<String>> = (t.start..=t.end).map(|i| split_cells(strip_blockquote(ctx.line(i)).2).iter().map(|c| c.trim().to_string()).collect()).collect();
            let ncols = rows.iter().map(|r| r.len()).max().unwrap_or(0);
            let mut widths = vec![3usize; ncols];
            for (ri, r) in rows.iter().enumerate() {
                if ri == t.delimiter - t.start {
                    continue;
                }
                for (ci, c) in r.iter().enumerate() {
                    widths[ci] = widths[ci].max(unicode_width::UnicodeWidthStr::width(c.as_str()));
                }
            }
            for (ri, r) in rows.iter().enumerate() {
                let i = t.start + ri;
                let mut cells = Vec::new();
                for ci in 0..ncols {
                    let c = r.get(ci).cloned().unwrap_or_default();
                    if i == t.delimiter {
                        let left = c.starts_with(':');
                        let right = c.ends_with(':');
                        let dashes = widths[ci] - (left as usize) - (right as usize);
                        cells.push(format!("{}{}{}", if left { ":" } else { "" }, "-".repeat(dashes.max(1)), if right { ":" } else { "" }));
                    } else {
                        let w = unicode_width::UnicodeWidthStr::width(c.as_str());
                        cells.push(format!("{}{}", c, " ".repeat(widths[ci].saturating_sub(w))));
                    }
                }
                let fixed = format!("| {} |", cells.join(" | "));
                let line = ctx.line(i);
                let (_, plen, rest) = strip_blockquote(line);
                if rest.trim() != fixed {
                    let ws = rest.len() - rest.trim_start().len();
                    out.push(
                        Warning::new("MD060", i + 1, 1, "Table columns should be aligned")
                            .with_end(i + 1, line.len() + 1)
                            .with_fix(ctx.lines[i].start + plen + ws, ctx.lines[i].start + plen + rest.trim_end().len(), fixed),
                    );
                }
            }
        }
        out
    }
}
