use super::Rule;
use crate::config::RuleConfig;
use crate::ctx::Ctx;
use crate::inline;
use crate::warning::{Severity, Warning};

pub struct FootnoteDef {
    pub line: usize,
    pub label: String,
    pub content: String,
}

pub fn footnote_defs(ctx: &Ctx) -> Vec<FootnoteDef> {
    let re = regex::Regex::new(r"^\[\^([^\]\s]+)\]:(.*)$").unwrap();
    let mut res = Vec::new();
    for i in 0..ctx.line_count() {
        if ctx.skip_line(i) {
            continue;
        }
        if let Some(c) = re.captures(ctx.line(i)) {
            res.push(FootnoteDef { line: i, label: c.get(1).unwrap().as_str().to_string(), content: c.get(2).unwrap().as_str().to_string() });
        }
    }
    res
}

pub fn footnote_refs(ctx: &Ctx) -> Vec<(usize, usize, String)> {
    // (line, byte col, label) in document order
    let re = regex::Regex::new(r"\[\^([^\]\s]+)\]").unwrap();
    let mut res = Vec::new();
    for i in 0..ctx.line_count() {
        if ctx.skip_line(i) || ctx.lines[i].in_html_block || ctx.lines[i].in_comment {
            continue;
        }
        let line = ctx.line(i);
        if !line.contains("[^") {
            continue;
        }
        let masked = inline::mask_code_spans(line);
        for m in re.find_iter(&masked) {
            // skip definitions
            if m.start() == 0 && line[m.end()..].starts_with(':') {
                continue;
            }
            let c = re.captures(&masked[m.start()..m.end()]).unwrap();
            res.push((i, m.start(), c.get(1).unwrap().as_str().to_string()));
        }
    }
    res
}

fn col_of(line: &str, byte: usize) -> usize {
    line[..byte.min(line.len())].chars().count() + 1
}

