    let re = regex::Regex::new(r"<!--\s*(rumdl|markdownlint)-(disable-file|disable-next-line|disable-line|disable|enable-file|enable|capture|restore|configure-file)(\s+([^>]*?))?\s*-->").unwrap();
    let re_prettier = regex::Regex::new(r"<!--\s*prettier-ignore\s*-->").unwrap();
    let mut active: HashSet<String> = HashSet::new();
    let mut captured: Option<HashSet<String>> = None;
    for i in 0..n {
        let line = ctx.line(i);
        if ctx.lines[i].in_code || ctx.lines[i].is_fence {
            disabled_per_line[i] = active.clone();
            continue;
        }
        // apply current state first (for the comment line itself too)
        let mut line_state = active.clone();
        if line.contains("<!--") {
            for c in re.captures_iter(line) {
                let cmd = c.get(2).unwrap().as_str();
                let args = c.get(4).map(|m| m.as_str().trim()).unwrap_or("");
                let list = parse_rule_list(args);
                match cmd {
                    "disable" => {
                        if list.is_empty() {
                            active.insert("*".into());
                        } else {
                            for r in list {
                                active.insert(r);
                            }
                        }
                        line_state = active.clone();
                    }
                    "enable" => {
                        if list.is_empty() {
                            active.clear();
                        } else {
                            for r in &list {
                                active.remove(r);
                            }
                            if active.contains("*") {
                                // enabling specific rules after disable-all: approximate by keeping '*' but tracking enabled
                                for r in &list {
                                    active.insert(format!("!{}", r));
                                }
                            }
                        }
                        line_state = active.clone();
                    }
                    "disable-line" => {
                        if list.is_empty() {
                            line_state.insert("*".into());
                        } else {
                            for r in list {
                                line_state.insert(r);
                            }
                        }
                    }
                    "disable-next-line" => {
                        if i + 1 < n {
                            if list.is_empty() {
                                disabled_per_line[i + 1].insert("*".into());
                            } else {
                                for r in list {
                                    disabled_per_line[i + 1].insert(r);
                                }
                            }
                        }
                    }
                    "disable-file" => {
                        if list.is_empty() {
                            file_disabled.insert("*".into());
                        } else {
                            for r in list {
                                file_disabled.insert(r);
                            }
                        }
                    }
                    "enable-file" => {
                        if list.is_empty() {
                            file_disabled.clear();
                        } else {
                            for r in &list {
                                file_disabled.remove(r);
                            }
                        }
                    }
                    "capture" => {
                        captured = Some(active.clone());
                    }
                    "restore" => {
                        if let Some(c) = &captured {
                            active = c.clone();
                            line_state = active.clone();
                        }
                    }
                    "configure-file" => {
                        if let Ok(v) = serde_json::from_str::<serde_json::Value>(args) {
                            if let Some(obj) = v.as_object() {
                                for (k, val) in obj {
                                    if let Some(t) = val.as_object() {
                                        let mut m = toml::map::Map::new();
                                        for (kk, vv) in t {
                                            if let Some(tv) = crate::config::json_to_toml(vv) {
                                                m.insert(kk.clone(), tv);
                                            }
                                        }
                                        let rid = rules::resolve_rule(k).map(|s| s.to_string()).unwrap_or_else(|| k.to_uppercase());
                                        configure.push((rid, m));
                                    }
                                }
                            }
                        }
                    }
                    _ => {}
                }
            }
            if re_prettier.is_match(line) && i + 1 < n {
                disabled_per_line[i + 1].insert("*".into());
            }
        }
        for r in line_state {
            disabled_per_line[i].insert(r);
        }
    }
    InlineConfig { disabled_per_line, file_disabled, configure }
}

fn is_disabled(set: &HashSet<String>, rule: &str) -> bool {
    if set.contains(rule) {
        return true;
    }
    if set.contains("*") && !set.contains(&format!("!{}", rule)) {
        return true;
    }
    false
}

pub fn lint_with_rules(content: &str, rule_objs: &[Box<dyn Rule>]) -> Vec<Warning> {
    let ctx = Ctx::new(content);
    let inline = parse_inline_config(&ctx);
    let mut all = Vec::new();
    for r in rule_objs {
        if is_disabled(&inline.file_disabled, r.name()) {
            continue;
        }
        let ws = r.check(&ctx);
        for w in ws {
            let li = w.line.saturating_sub(1);
            if li < inline.disabled_per_line.len() && is_disabled(&inline.disabled_per_line[li], w.rule) {
                continue;
            }
            all.push(w);
        }
    }
    all.sort_by(|a, b| (a.line, a.column, a.rule).cmp(&(b.line, b.column, b.rule)));
    all
}

/// Apply fixes: multiple passes in rule order until stable.
pub fn fix_with_rules(content: &str, rule_objs: &[Box<dyn Rule>]) -> String {
    let mut current = content.to_string();
    for _pass in 0..5 {
        let before = current.clone();
        for r in rule_objs {
            let ctx = Ctx::new(&current);
            let inline = parse_inline_config(&ctx);
            if is_disabled(&inline.file_disabled, r.name()) {
                continue;
            }
            let ws = r.check(&ctx);
            let ws: Vec<Warning> = ws.into_iter().filter(|w| {
                let li = w.line.saturating_sub(1);
                !(li < inline.disabled_per_line.len() && is_disabled(&inline.disabled_per_line[li], w.rule))
            }).collect();
            if ws.iter().all(|w| w.fix.is_none()) {
                continue;
            }
            let has_inline_disables = inline.disabled_per_line.iter().any(|s| !s.is_empty());
            if has_inline_disables {
                // apply only the per-warning fixes to respect inline disables
                if let Some(fixed) = rules::apply_warning_fixes(&current, &ws) {
                    current = fixed;
                }
                continue;
            }
            if let Some(fixed) = r.fix(&ctx) {
                current = fixed;
            }
        }
        if current == before {
            break;
        }
    }
    current
}

/// Build rule objects (with inline configure-file applied) for a given content
pub fn build_rules_for(content: &str, cfg: &crate::config::Config, enabled: &[&'static str]) -> Vec<Box<dyn Rule>> {
    let ctx = Ctx::new(content);
    let inline = parse_inline_config(&ctx);
    let mut cfg2 = cfg.clone();
    for (rid, m) in &inline.configure {
        let rc = cfg2.rules.entry(rid.clone()).or_default();
        for (k, v) in m {
            rc.values.insert(crate::config::norm_key(k), v.clone());
        }
    }
    enabled.iter().filter_map(|id| rules::build_rule(id, &cfg2)).collect()
}
EOF
