        "location": {"path": file, "lines": {"begin": w.line}}
    })
}

pub fn xml_escape(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;").replace('\'', "&apos;")
}

pub fn format_junit(results: &[(String, Vec<Warning>)], total_files: usize, secs: f64) -> String {
    let mut out = String::new();
    let failures: usize = results.iter().map(|r| r.1.len()).sum();
    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    let tests = results.iter().filter(|r| !r.1.is_empty()).count();
    let _ = total_files;
    out.push_str(&format!("<testsuites name=\"rumdl\" tests=\"{}\" failures=\"{}\" errors=\"0\" time=\"{:.3}\">\n", tests, failures, secs));
    for (file, ws) in results {
        if ws.is_empty() {
            continue;
        }
        out.push_str(&format!("  <testsuite name=\"{}\" tests=\"1\" failures=\"{}\" errors=\"0\" time=\"0.000\">\n", xml_escape(file), ws.len()));
        out.push_str(&format!("    <testcase name=\"Lint {}\" classname=\"rumdl\" time=\"0.000\">\n", xml_escape(file)));
        for w in ws {
            out.push_str(&format!(
                "      <failure type=\"{}\" message=\"{}\">{} at line {}, column {}</failure>\n",
                w.rule,
                xml_escape(&w.message),
                xml_escape(&w.message),
                w.line,
                w.column
            ));
        }
        out.push_str("    </testcase>\n");
        out.push_str("  </testsuite>\n");
    }
    out.push_str("</testsuites>\n");
    out
}

pub fn format_sarif(results: &[(String, Vec<Warning>)]) -> String {
    let mut rule_ids: Vec<&str> = Vec::new();
    for (_, ws) in results {
        for w in ws {
            if !rule_ids.contains(&w.rule) {
                rule_ids.push(w.rule);
            }
        }
    }
    let rules: Vec<serde_json::Value> = rule_ids
        .iter()
        .map(|r| {
            serde_json::json!({
                "id": r, "name": r,
                "shortDescription": {"text": format!("Markdown rule {}", r)},
                "fullDescription": {"text": format!("Markdown linting rule {}", r)}
            })
        })
        .collect();
    let mut res = Vec::new();
    for (file, ws) in results {
        for w in ws {
            let level = match w.severity {
                crate::warning::Severity::Error => "error",
                crate::warning::Severity::Warning => "warning",
                crate::warning::Severity::Info => "note",
            };
            res.push(serde_json::json!({
                "ruleId": w.rule,
                "level": level,
                "message": {"text": w.message},
                "locations": [{"physicalLocation": {"artifactLocation": {"uri": file}, "region": {"startLine": w.line, "startColumn": w.column}}}]
            }));
        }
    }
    let v = serde_json::json!({
        "$schema": "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
        "version": "2.1.0",
        "runs": [{
            "tool": {"driver": {"name": "rumdl", "version": crate::VERSION, "informationUri": "https://github.com/rvben/rumdl", "rules": rules}},
            "results": res
        }]
    });
    serde_json::to_string_pretty(&v).unwrap()
}
