use clap::ArgMatches;

/// Resolve a flag/option that may be given at top-level or at subcommand level.
pub fn get_str<'a>(sub: &'a ArgMatches, top: &'a ArgMatches, id: &str) -> Option<&'a str> {
    sub.try_get_one::<String>(id).ok().flatten().map(|s| s.as_str()).or_else(|| top.try_get_one::<String>(id).ok().flatten().map(|s| s.as_str()))
}
pub fn get_flag(sub: &ArgMatches, top: &ArgMatches, id: &str) -> bool {
    sub.try_get_one::<bool>(id).ok().flatten().copied().unwrap_or(false) || top.try_get_one::<bool>(id).ok().flatten().copied().unwrap_or(false)
}

pub fn color_enabled(sub: &ArgMatches, top: &ArgMatches) -> bool {
    let c = sub.try_get_one::<String>("color").ok().flatten().map(|s| s.as_str());
