actions.command:
cat > /workspace/src/commands/check.rs <<'EOF'
use crate::commands::{color_enabled, get_flag, get_str, load_config};
use crate::config::Config;
use crate::linter;
use crate::output::{self, Colors};
use crate::rules;
use crate::warning::{Severity, Warning};
use clap::ArgMatches;
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;

const MD_EXTS: &[&str] = &["md", "markdown", "mdx", "mdown", "mkd", "mkdn", "mdwn", "qmd", "rmd", "Rmd"];

fn is_md_file(p: &Path) -> bool {
    p.extension().and_then(|e| e.to_str()).map(|e| MD_EXTS.contains(&e)).unwrap_or(false)
}

fn rel_display(p: &Path) -> String {
    let s = p.to_string_lossy().to_string();
    let s = s.strip_prefix("./").unwrap_or(&s).to_string();
    s
}

struct Discovered {
    files: Vec<PathBuf>,
}

fn build_globset(patterns: &[String]) -> Option<globset::GlobSet> {
    if patterns.is_empty() {
        return None;
    }
    let mut b = globset::GlobSetBuilder::new();
    for p in patterns {
        let p = p.trim().trim_end_matches('/');
        if p.is_empty() {
            continue;
        }
        for cand in [p.to_string(), format!("{}/**", p), format!("**/{}", p), format!("**/{}/**", p)] {
            if let Ok(g) = globset::GlobBuilder::new(&cand).literal_separator(false).build() {
                b.add(g);
            }
        }
    }
    b.build().ok()
}

fn discover(paths: &[String], cfg: &Config, respect_gitignore: bool, excludes: &[String], includes: &[String], force_exclude: bool) -> Result<Discovered, String> {
    let mut files: Vec<PathBuf> = Vec::new();
    let exclude_set = build_globset(excludes);
    let include_set = build_globset(includes);
    let _ = cfg;
    let explicit_files: Vec<&String> = paths.iter().filter(|p| Path::new(p).is_file()).collect();
    let mut dirs: Vec<&String> = Vec::new();
    for p in paths {
        let path = Path::new(p);
        if path.is_file() {
            continue;
        } else if path.is_dir() {
            dirs.push(p);
        } else {
            return Err(format!("File not found: {}", p));
        }
    }
    if !explicit_files.is_empty() {
        for f in explicit_files {
            let pb = PathBuf::from(f);
            let rel = rel_display(&pb);
            if force_exclude {
                if let Some(ex) = &exclude_set {
                    if ex.is_match(&rel) {
                        continue;
                    }
                }
            }
            if !files.contains(&pb) {
                files.push(pb);
            }
        }
        return Ok(Discovered { files });
    }
    for d in dirs {
        let mut wb = ignore::WalkBuilder::new(d);
        wb.hidden(false).git_ignore(respect_gitignore).git_global(false).git_exclude(respect_gitignore).ignore(respect_gitignore).parents(respect_gitignore).require_git(true);
        wb.sort_by_file_path(|a, b| a.cmp(b));
        for entry in wb.build().flatten() {
            let p = entry.path();
            if !p.is_file() || !is_md_file(p) {
                continue;
            }
            let rel = rel_display(p);
            if let Some(ex) = &exclude_set {
                if ex.is_match(&rel) {
                    continue;
                }
            }
            if let Some(inc) = &include_set {
                if !inc.is_match(&rel) {
                    continue;
                }
            }
            files.push(p.to_path_buf());
        }
    }
    Ok(Discovered { files })
}

fn split_list(s: Option<&str>) -> Vec<String> {
    s.map(|v| v.split(',').map(|x| x.trim().to_string()).filter(|x| !x.is_empty()).collect()).unwrap_or_default()
}

fn count_fmt(n: usize, singular: &str, plural: &str) -> String {
    if n == 1 {
        format!("{} {}", n, singular)
    } else {
        format!("{} {}", n, plural)
    }
}

pub fn run(sub: &ArgMatches, top: &ArgMatches, is_fmt: bool) -> i32 {
    let start = Instant::now();
    let colors = Colors { enabled: color_enabled(sub, top) };
    let fix = is_fmt || sub.get_flag("fix");
    let diff_mode = sub.get_flag("diff");
    let check_mode = sub.get_flag("check");
    let quiet = sub.get_flag("quiet");
    let silent = sub.get_flag("silent");
    let verbose = sub.get_flag("verbose");
    let statistics = sub.get_flag("statistics");
    let to_stderr = sub.get_flag("stderr");
    let fail_on = sub.get_one::<String>("fail_on").map(|s| s.as_str()).unwrap_or("any");

    if sub.get_flag("list_rules") {
        return crate::commands::misc::list_rules_simple();
    }

    let cfg = match load_config(sub, top) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Config error: {}", e);
            return 2;
        }
    };
    for w in &cfg.warnings {
        eprintln!("{} {}", colors_or_always("33", "[config warning]", &colors), w);
    }

    let enable = sub.get_one::<String>("enable").map(|s| s.as_str());
    let disable = sub.get_one::<String>("disable").map(|s| s.as_str());
    let ext_enable = sub.get_one::<String>("extend_enable").map(|s| s.as_str());
    let ext_disable = sub.get_one::<String>("extend_disable").map(|s| s.as_str());
    for (flag, val) in [("--enable", enable), ("--disable", disable), ("--extend-enable", ext_enable), ("--extend-disable", ext_disable)] {
        if let Some(v) = val {
            for r in v.split(',').map(|x| x.trim()).filter(|x| !x.is_empty()) {
                if rules::resolve_rule(r).is_none() {
                    let hint = rules::closest_rule_name(r).map(|h| format!(" (did you mean: {})", h)).unwrap_or_default();
                    eprintln!("{} Unknown rule in {}: {}{}", colors_or_always("33", "[cli warning]", &colors), flag, r.to_uppercase(), hint);
                }
            }
        }
    }
    let enabled = rules::enabled_rules(&cfg, enable, disable, ext_enable, ext_disable);

    // output format
    let output_format: String = if let Some(f) = sub.get_one::<String>("output_format") {
        f.clone()
    } else if let Some(o) = sub.get_one::<String>("output") {
        if o != "text" {
            o.clone()
        } else if let Ok(env) = std::env::var("RUMDL_OUTPUT_FORMAT") {
            env
        } else {
            cfg.global.output_format.clone().unwrap_or_else(|| "text".to_string())
        }
    } else {
        "text".to_string()
    };
    let legacy_json = sub.get_one::<String>("output").map(|o| o == "json").unwrap_or(false) && sub.get_one::<String>("output_format").is_none();

    let paths: Vec<String> = sub.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or_default();
    let stdin_mode = sub.get_flag("stdin") || paths.iter().any(|p| p == "-");

    if verbose && !stdin_mode {
        println!("Enabled rules:");
        for id in &enabled {
            if let Some(m) = rules::meta(id) {
                println!("  - {} ({})", m.id, m.summary);
            }
        }
        println!();
    }

    if stdin_mode {
        return run_stdin(sub, &cfg, &enabled, fix, is_fmt, &colors, &output_format, legacy_json, quiet, silent, fail_on);
    }

    let paths = if paths.is_empty() { vec![".".to_string()] } else { paths };
    let respect_gitignore = sub.get_one::<bool>("respect_gitignore").copied().unwrap_or(cfg.global.respect_gitignore);
    let no_exclude = sub.get_flag("no_exclude");
    let excludes: Vec<String> = if no_exclude {
        vec![]
    } else if sub.get_one::<String>("exclude").is_some() {
        split_list(sub.get_one::<String>("exclude").map(|s| s.as_str()))
    } else {
        cfg.global.exclude.clone()
    };
    let includes: Vec<String> = if sub.get_one::<String>("include").is_some() { split_list(sub.get_one::<String>("include").map(|s| s.as_str())) } else { cfg.global.include.clone() };
    let force_exclude = sub.get_flag("force_exclude") || cfg.global.force_exclude;
    if verbose {
        println!("Exclude patterns: {:?}", excludes);
    }
    let disc = match discover(&paths, &cfg, respect_gitignore, &excludes, &includes, force_exclude) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("{}: Failed to find markdown files: {}", colors.paint("1;31", "Error"), e);
            return 1;
        }
    };
    if disc.files.is_empty() {
        if !silent {
            println!("No markdown files found to check.");
        }
        return 0;
    }

    let mut results: Vec<(String, Vec<Warning>)> = Vec::new();
    let mut total_fixed = 0usize;
    let mut total_fixable = 0usize;
    let mut remaining_after_fix = 0usize;
    let mut diffs: Vec<String> = Vec::new();
    let mut per_file_ignores_matcher: Vec<(globset::GlobMatcher, Vec<String>)> = Vec::new();
    for (pat, rs) in &cfg.per_file_ignores {
        if let Ok(g) = globset::GlobBuilder::new(pat).literal_separator(false).build() {
            per_file_ignores_matcher.push((g.compile_matcher(), rs.clone()));
        }
    }
    let total_files = disc.files.len();
    for f in &disc.files {
        let display = if sub.get_flag("show_full_path") { std::fs::canonicalize(f).map(|p| p.to_string_lossy().to_string()).unwrap_or_else(|_| rel_display(f)) } else { rel_display(f) };
        if verbose {
            println!("Processing file: {}", display);
        }
        let content = match std::fs::read_to_string(f) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Error reading file {}: {}", display, e);
                continue;
            }
        };
        let rel = rel_display(f);
        let mut file_enabled: Vec<&'static str> = enabled.clone();
        for (m, rs) in &per_file_ignores_matcher {
            if m.is_match(&rel) || m.is_match(f) {
                file_enabled.retain(|r| !rs.iter().any(|x| x == r));
            }
        }
        let rule_objs = linter::build_rules_for(&content, &cfg, &file_enabled);
        set_md057_base(&rule_objs, f);
        let warnings = linter::lint_with_rules(&content, &rule_objs);
        let fixable = warnings.iter().filter(|w| w.fix.is_some()).count();
        total_fixable += fixable;
        if fix && fixable > 0 && !diff_mode && !check_mode {
            let fixed = linter::fix_with_rules(&content, &rule_objs);
            if fixed != content {
                if let Err(e) = std::fs::write(f, &fixed) {
                    eprintln!("Error writing file {}: {}", display, e);
                }
            }
            total_fixed += fixable;
            let remaining = linter::lint_with_rules(&fixed, &rule_objs);
            remaining_after_fix += remaining.len();
        } else if (diff_mode || check_mode) && fixable > 0 {
            let fixed = linter::fix_with_rules(&content, &rule_objs);
            if diff_mode {
                diffs.push(make_diff(&display, &content, &fixed));
            }
            remaining_after_fix += warnings.len() - fixable;
        } else {
            remaining_after_fix += warnings.len();
        }
        // MD057 second pass (cross-file link validation) emulation
        let extra: Vec<Warning> = md057_second_pass(&content, &rule_objs, f);
        results.push((display.clone(), warnings));
        if !extra.is_empty() {
            results.push((display, extra));
        }
    }

    let elapsed_ms = start.elapsed().as_millis();
    let total_issues: usize = results.iter().map(|r| r.1.len()).sum();
    let files_with_issues = results.iter().filter(|r| !r.1.is_empty()).count();

    let mut out: Box<dyn Write> = if to_stderr { Box::new(std::io::stderr()) } else { Box::new(std::io::stdout()) };
    let fixed_marker = if fix && !diff_mode && !check_mode { Some("[fixed]") } else { None };

    if !silent {
        match output_format.as_str() {
            "json" => {
                let arr: Vec<serde_json::Value> = results.iter().flat_map(|(f, ws)| ws.iter().map(move |w| output::json_warning(f, w, true))).collect();
                let _ = writeln!(out, "{}", serde_json::to_string_pretty(&arr).unwrap());
            }
            "json-lines" => {
                for (f, ws) in &results {
                    for w in ws {
                        let _ = writeln!(out, "{}", serde_json::to_string(&output::json_warning(f, w, false)).unwrap());
                    }
                }
            }
            "gitlab" => {
                let arr: Vec<serde_json::Value> = results.iter().flat_map(|(f, ws)| ws.iter().map(move |w| output::gitlab_warning(f, w))).collect();
                let _ = writeln!(out, "{}", serde_json::to_string_pretty(&arr).unwrap());
            }
            "sarif" => {
                let _ = writeln!(out, "{}", output::format_sarif(&results));
            }
            "junit" => {
                let _ = writeln!(out, "{}", output::format_junit(&results, total_files, elapsed_ms as f64 / 1000.0));
            }
            "grouped" => {
                for (f, ws) in &results {
                    if ws.is_empty() {
                        continue;
                    }
                    let _ = writeln!(out, "{}:", f);
                    let mut by_rule: Vec<(&str, Vec<&Warning>)> = Vec::new();
                    for w in ws {
                        if let Some(e) = by_rule.iter_mut().find(|(r, _)| *r == w.rule) {
                            e.1.push(w);
                        } else {
                            by_rule.push((w.rule, vec![w]));
                        }
                    }
                    by_rule.sort_by_key(|(r, _)| *r);
                    for (r, list) in by_rule {
                        let _ = writeln!(out, "  {}:", r);
                        for w in list {
                            let _ = writeln!(out, "    {}:{} {}{}", w.line, w.column, w.message, if w.fix.is_some() { " (fixable)" } else { "" });
                        }
                    }
                }
            }
            _ => {
                for (f, ws) in &results {
                    for w in ws {
                        let line = match output_format.as_str() {
                            "concise" => output::format_concise(f, w),
                            "pylint" => output::format_pylint(f, w),
                            "github" => output::format_github(f, w),
                            "azure" => output::format_azure(f, w),
                            _ => output::format_text_warning(f, w, &colors, fixed_marker, true),
                        };
                        let _ = writeln!(out, "{}", line);
                    }
                }
            }
        }
        if diff_mode {
            for d in &diffs {
                let _ = write!(out, "{}", d);
            }
        }
        let summary_formats = ["text", "full", "concise", "grouped", "json-lines", "github", "pylint", "azure"];
        if !quiet && summary_formats.contains(&output_format.as_str()) {
            if total_issues == 0 {
                let _ = writeln!(out);
                let _ = writeln!(out, "{} No issues found in {} ({}ms)", colors.paint("1;32", "Success:"), count_fmt(total_files, "file", "files"), elapsed_ms);
            } else if fix && total_fixed > 0 && !diff_mode && !check_mode {
                let _ = writeln!(out);
                let _ = writeln!(out, "{} Fixed {}/{} issues in {} ({}ms)", colors.paint("1;32", "Fixed:"), total_fixed, total_issues, count_fmt(files_with_issues, "file", "files"), elapsed_ms);
            } else {
                let _ = writeln!(out);
                let files_str = if files_with_issues == total_files { count_fmt(total_files, "file", "files") } else { format!("{}/{} {}", files_with_issues, total_files, if total_files == 1 { "file" } else { "files" }) };
                let _ = writeln!(out, "{} Found {} issues in {} ({}ms)", colors.paint("33", "Issues:"), total_issues, files_str, elapsed_ms);
                if total_fixable > 0 {
                    let _ = writeln!(out, "Run `rumdl fmt` to automatically fix {} of the {} issues", total_fixable, total_issues);
                }
            }
        }
        if statistics && total_issues > 0 {
            print_statistics(&mut out, &results);
        }
    }

    // exit code
    if is_fmt {
        return 0;
    }
    if check_mode {
        return if total_fixable > 0 { 1 } else if total_issues > 0 { 1 } else { 0 };
    }
    let considered: Vec<&Warning> = results.iter().flat_map(|r| r.1.iter()).collect();
    let has_violation = if fix && !diff_mode { remaining_after_fix > 0 } else { !considered.is_empty() };
    if !has_violation {
        return 0;
    }
    match fail_on {
        "never" => 0,
        "error" => {
            if considered.iter().any(|w| w.severity == Severity::Error) {
                1
            } else {
                0
            }
        }
        "warning" => {
            if considered.iter().any(|w| w.severity != Severity::Info) {
                1
            } else {
                0
            }
        }
        _ => 1,
    }
}

fn colors_or_always(code: &str, s: &str, colors: &Colors) -> String {
    let _ = colors;
    format!("\x1b[{}m{}\x1b[0m", code, s)
}

fn set_md057_base(rule_objs: &[Box<dyn rules::Rule>], f: &Path) {
    let _ = (rule_objs, f);
    let base = f.parent().map(|p| if p.as_os_str().is_empty() { PathBuf::from(".") } else { p.to_path_buf() }).unwrap_or_else(|| PathBuf::from("."));
    MD057_BASE.with(|b| *b.borrow_mut() = Some(base));
}

thread_local! {
    pub static MD057_BASE: std::cell::RefCell<Option<PathBuf>> = std::cell::RefCell::new(None);
}

fn md057_second_pass(content: &str, rule_objs: &[Box<dyn rules::Rule>], f: &Path) -> Vec<Warning> {
    if !rule_objs.iter().any(|r| r.name() == "MD057") {
        return vec![];
    }
    let base = f.parent().map(|p| if p.as_os_str().is_empty() { PathBuf::from(".") } else { p.to_path_buf() }).unwrap_or_else(|| PathBuf::from("."));
    let ctx = crate::ctx::Ctx::new(content);
    let inline_cfg = linter::parse_inline_config(&ctx);
    let mut out = Vec::new();
    if inline_cfg.file_disabled.contains("*") || inline_cfg.file_disabled.contains("MD057") {
        return out;
    }
    for (i, ustart, lstart, url, is_image, has_frag) in rules::links::md057_links(&ctx, &base) {
        if is_image {
            continue;
        }
        let line = ctx.line(i);
        let byte = if has_frag == 1 { lstart } else { ustart };
        let col = line[..byte.min(line.len())].chars().count() + 1;
        let w = Warning::new("MD057", i + 1, col, format!("Relative link '{}' does not exist", url)).with_severity(Severity::Error).with_end(i + 1, col + url.chars().count());
        let li = i;
        if li < inline_cfg.disabled_per_line.len() && (inline_cfg.disabled_per_line[li].contains("MD057") || inline_cfg.disabled_per_line[li].contains("*")) {
            continue;
        }
        out.push(w);
    }
    out
}

fn print_statistics(out: &mut Box<dyn Write>, results: &[(String, Vec<Warning>)]) {
    let mut stats: Vec<(&str, usize, usize)> = Vec::new();
    for (_, ws) in results {
        for w in ws {
            if let Some(e) = stats.iter_mut().find(|(r, _, _)| *r == w.rule) {
                e.1 += 1;
                if w.fix.is_some() {
                    e.2 += 1;
                }
            } else {
                stats.push((w.rule, 1, if w.fix.is_some() { 1 } else { 0 }));
            }
        }
    }
    stats.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
    let total: usize = stats.iter().map(|s| s.1).sum();
    let total_fix: usize = stats.iter().map(|s| s.2).sum();
    let _ = writeln!(out);
    let _ = writeln!(out, "Rule Violation Statistics:");
    let _ = writeln!(out, "{:<8} {:<12} {:<8} {}", "Rule", "Violations", "Fixable", "Percentage");
    let _ = writeln!(out, "{}", "-".repeat(50));
    for (r, c, f) in &stats {
        let pct = (*c as f64) * 100.0 / (total.max(1) as f64);
        let fs = if *f == 0 { "-".to_string() } else { f.to_string() };
        let _ = writeln!(out, "{:<8} {:<12} {:<8} {:>7.1}%", r, c, fs, pct);
    }
    let _ = writeln!(out, "{}", "-".repeat(50));
    let _ = writeln!(out, "{:<8} {:<12} {:<8} {:>7.1}%", "Total", total, total_fix, 100.0);
}

fn make_diff(name: &str, before: &str, after: &str) -> String {
    let a: Vec<&str> = before.lines().collect();
    let b: Vec<&str> = after.lines().collect();
    let mut s = String::new();
    s.push_str(&format!("--- {}\n+++ {} (fixed)\n", name, name));
    s.push_str(&format!("@@ -1,{} +1,{} @@\n", a.len(), b.len()));
    // simple LCS-based diff
    let n = a.len();
    let m = b.len();
    let mut dp = vec![vec![0usize; m + 1]; n + 1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            dp[i][j] = if a[i] == b[j] { dp[i + 1][j + 1] + 1 } else { dp[i + 1][j].max(dp[i][j + 1]) };
        }
    }
    let (mut i, mut j) = (0, 0);
    while i < n && j < m {
        if a[i] == b[j] {
            s.push_str(&format!(" {}\n", a[i]));
            i += 1;
            j += 1;
        } else if dp[i + 1][j] >= dp[i][j + 1] {
            s.push_str(&format!("-{}\n", a[i]));
            i += 1;
        } else {
            s.push_str(&format!("+{}\n", b[j]));
            j += 1;
        }
    }
    while i < n {
        s.push_str(&format!("-{}\n", a[i]));
        i += 1;
    }
    while j < m {
        s.push_str(&format!("+{}\n", b[j]));
        j += 1;
    }
    s.push('\n');
    s
}

#[allow(clippy::too_many_arguments)]
fn run_stdin(sub: &ArgMatches, cfg: &Config, enabled: &[&'static str], fix: bool, is_fmt: bool, colors: &Colors, output_format: &str, legacy_json: bool, quiet: bool, silent: bool, fail_on: &str) -> i32 {
    let mut content = String::new();
    if std::io::stdin().read_to_string(&mut content).is_err() {
        eprintln!("Error: Failed to read from stdin");
        return 2;
    }
    let name = sub.get_one::<String>("stdin_filename").cloned().unwrap_or_else(|| "<stdin>".to_string());
    let mut file_enabled: Vec<&'static str> = enabled.to_vec();
    if name != "<stdin>" {
        for (pat, rs) in &cfg.per_file_ignores {
            if let Ok(g) = globset::GlobBuilder::new(pat).literal_separator(false).build() {
                if g.compile_matcher().is_match(&name) {
                    file_enabled.retain(|r| !rs.iter().any(|x| x == r));
                }
            }
        }
    }
    let rule_objs = linter::build_rules_for(&content, cfg, &file_enabled);
    MD057_BASE.with(|b| *b.borrow_mut() = None);
    let warnings = linter::lint_with_rules(&content, &rule_objs);
    let err = std::io::stderr();
    if fix {
        let fixable = warnings.iter().filter(|w| w.fix.is_some()).count();
        let fixed = if fixable > 0 { linter::fix_with_rules(&content, &rule_objs) } else { content.clone() };
        print!("{}", fixed);
        let _ = std::io::stdout().flush();
        let remaining = linter::lint_with_rules(&fixed, &rule_objs);
        if !remaining.is_empty() && !silent {
            let mut e = err.lock();
            for w in &remaining {
                let _ = writeln!(e, "{}", output::format_text_warning(&name, w, colors, None, true));
            }
            if !quiet {
                let _ = writeln!(e);
                let _ = writeln!(e, "{} issue(s) fixed, {} issue(s) remaining", fixable, remaining.len());
            }
        }
        if is_fmt {
            return 0;
        }
        return if remaining.is_empty() { 0 } else { exit_for(&remaining, fail_on) };
    }
    if legacy_json {
        let arr: Vec<serde_json::Value> = warnings.iter().map(|w| output::json_warning(&name, w, true)).collect();
        println!("{}", serde_json::to_string_pretty(&arr).unwrap());
        return if warnings.is_empty() { 0 } else { exit_for(&warnings, fail_on) };
    }
    if !silent {
        let mut e = err.lock();
        let results = vec![(name.clone(), warnings.clone())];
        match output_format {
            "json" => {
                let arr: Vec<serde_json::Value> = warnings.iter().map(|w| output::json_warning(&name, w, true)).collect();
                let _ = writeln!(e, "{}", serde_json::to_string_pretty(&arr).unwrap());
                return if warnings.is_empty() { 0 } else { exit_for(&warnings, fail_on) };
            }
            "gitlab" => {
                let arr: Vec<serde_json::Value> = warnings.iter().map(|w| output::gitlab_warning(&name, w)).collect();
                let _ = writeln!(e, "{}", serde_json::to_string_pretty(&arr).unwrap());
                return if warnings.is_empty() { 0 } else { exit_for(&warnings, fail_on) };
            }
            "sarif" => {
                let _ = writeln!(e, "{}", output::format_sarif(&results));
                return if warnings.is_empty() { 0 } else { exit_for(&warnings, fail_on) };
            }
            "junit" => {
                let _ = writeln!(e, "{}", output::format_junit(&results, 1, 0.0));
                return if warnings.is_empty() { 0 } else { exit_for(&warnings, fail_on) };
            }
            "json-lines" => {
                for w in &warnings {
                    let _ = writeln!(e, "{}", serde_json::to_string(&output::json_warning(&name, w, false)).unwrap());
                }
            }
            "grouped" => {
                if !warnings.is_empty() {
                    let _ = writeln!(e, "{}:", name);
                    let mut by_rule: Vec<(&str, Vec<&Warning>)> = Vec::new();
                    for w in &warnings {
                        if let Some(en) = by_rule.iter_mut().find(|(r, _)| *r == w.rule) {
                            en.1.push(w);
                        } else {
                            by_rule.push((w.rule, vec![w]));
                        }
                    }
                    by_rule.sort_by_key(|(r, _)| *r);
                    for (r, list) in by_rule {
                        let _ = writeln!(e, "  {}:", r);
                        for w in list {
                            let _ = writeln!(e, "    {}:{} {}{}", w.line, w.column, w.message, if w.fix.is_some() { " (fixable)" } else { "" });
                        }
                    }
                }
            }
            _ => {
                for w in &warnings {
                    let line = match output_format {
                        "concise" => output::format_concise(&name, w),
                        "pylint" => output::format_pylint(&name, w),
                        "github" => output::format_github(&name, w),
                        "azure" => output::format_azure(&name, w),
                        _ => output::format_text_warning(&name, w, colors, None, true),
                    };
                    let _ = writeln!(e, "{}", line);
                }
            }
        }
        if !quiet {
            if warnings.is_empty() {
                let _ = writeln!(e, "No issues found in {}", name);
            } else {
                let _ = writeln!(e);
                let _ = writeln!(e, "Found {} issue(s) in {}", warnings.len(), name);
            }
        }
    }
    if warnings.is_empty() {
        0
    } else {
        exit_for(&warnings, fail_on)
    }
}

fn exit_for(ws: &[Warning], fail_on: &str) -> i32 {
    match fail_on {
        "never" => 0,
        "error" => {
            if ws.iter().any(|w| w.severity == Severity::Error) {
                1
            } else {
                0
            }
        }
        "warning" => {
            if ws.iter().any(|w| w.severity != Severity::Info) {
                1
            } else {
                0
            }
        }
        _ => 1,
    }
}
