pub fn fmt_value(v: &Value) -> String {
    match v {
        Value::String(s) => format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\"")),
        Value::Integer(i) => i.to_string(),
        Value::Float(f) => f.to_string(),
        Value::Boolean(b) => b.to_string(),
        Value::Array(a) => format!("[{}]", a.iter().map(fmt_value).collect::<Vec<_>>().join(", ")),
        Value::Table(t) => {
            if t.is_empty() {
                "{}".to_string()
            } else {
                format!("{{ {} }}", t.iter().map(|(k, v)| format!("{} = {}", k, fmt_value(v))).collect::<Vec<_>>().join(", "))
            }
        }
        Value::Datetime(d) => d.to_string(),
    }
}

fn flavor_display(f: &str) -> String {
    match f.to_lowercase().as_str() {
        "mkdocs" => "MkDocs".to_string(),
        "mdx" => "MDX".to_string(),
        "quarto" => "Quarto".to_string(),
        "obsidian" => "Obsidian".to_string(),
        "gfm" | "github" => "GFM".to_string(),
        _ => "Standard".to_string(),
    }
}

struct Section {
    name: String,
    entries: Vec<(String, String, String)>, // key, value, source
}

fn build_sections(cfg: &Config, mode: &str) -> Vec<Section> {
    let src = |s: &str| if s == "default" { "[from default]".to_string() } else { format!("[from {}]", s) };
    let mut sections = Vec::new();
    // global
    let g = &cfg.global;
    let gsrc = |k: &str| g.sources.get(k).map(|s| s.as_str()).unwrap_or("default").to_string();
    let global_entries: Vec<(&str, String, String)> = vec![
        ("enable", fmt_value(&Value::Array(g.enable.iter().map(|x| Value::String(x.clone())).collect())), gsrc("enable")),
        ("disable", fmt_value(&Value::Array(g.disable.iter().map(|x| Value::String(x.clone())).collect())), gsrc("disable")),
        ("exclude", fmt_value(&Value::Array(g.exclude.iter().map(|x| Value::String(x.clone())).collect())), gsrc("exclude")),
        ("include", fmt_value(&Value::Array(g.include.iter().map(|x| Value::String(x.clone())).collect())), gsrc("include")),
        ("respect_gitignore", g.respect_gitignore.to_string(), gsrc("respect-gitignore")),
        ("flavor", flavor_display(&g.flavor), gsrc("flavor")),
    ];
    let mut entries = Vec::new();
    for (k, v, s) in global_entries {
        let is_default = s == "default";
        if (mode == "no-defaults" && is_default) || (mode == "defaults" && !is_default) {
            continue;
        }
        entries.push((k.to_string(), v, src(&s)));
    }
    if !entries.is_empty() {
        sections.push(Section { name: "global".to_string(), entries });
    }
    // rules
    let defaults = default_rule_values();
    let mut rule_ids: Vec<String> = defaults.iter().map(|(id, _)| id.to_string()).collect();
    for id in cfg.rules.keys() {
        if !rule_ids.contains(id) {
            rule_ids.push(id.clone());
        }
    }
    rule_ids.sort();
    for id in rule_ids {
        let def = defaults.iter().find(|(d, _)| *d == id).map(|(_, v)| v.clone()).unwrap_or_default();
        let user = cfg.rules.get(&id);
        let mut keys: Vec<String> = def.iter().map(|(k, _)| k.to_string()).collect();
        if let Some(u) = user {
            for k in u.values.keys() {
                if !keys.contains(k) {
                    keys.push(k.clone());
                }
            }
        }
        keys.sort();
        let mut entries = Vec::new();
        for k in keys {
            let (val, source) = match user.and_then(|u| u.values.get(&k)) {
                Some(v) => (v.clone(), user.and_then(|u| u.sources.get(&k).cloned()).unwrap_or_else(|| "project config".to_string())),
                None => match def.iter().find(|(dk, _)| *dk == k) {
                    Some((_, v)) => (v.clone(), "default".to_string()),
                    None => continue,
                },
            };
            let is_default = source == "default";
            if (mode == "no-defaults" && is_default) || (mode == "defaults" && !is_default) {
                continue;
            }
            entries.push((k, fmt_value(&val), src(&source)));
        }
        if !entries.is_empty() {
            sections.push(Section { name: id, entries });
        }
    }
    sections
}

pub fn run(sub: &ArgMatches, top: &ArgMatches) -> i32 {
    let cfg = match load_config(sub, top) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Config error: {}", e);
            return 2;
        }
    };
    match sub.subcommand() {
        Some(("file", _)) => {
            match &cfg.loaded_from {
                Some(p) => {
                    let abs = std::fs::canonicalize(p).unwrap_or_else(|_| p.clone());
                    println!("{}", abs.display());
                }
                None => println!("No configuration file found (using defaults)"),
            }
            return 0;
        }
        Some(("get", g)) => {
            let key = g.get_one::<String>("key").map(|s| s.as_str()).unwrap_or("");
            return config_get(&cfg, key);
        }
        _ => {}
    }
    let mode = if get_flag(sub, top, "defaults") {
        "defaults"
    } else if get_flag(sub, top, "no_defaults") {
        "no-defaults"
    } else {
        "all"
    };
    let output = get_str(sub, top, "output").unwrap_or("toml");
    if output == "json" {
        return config_json(&cfg);
    }
    let sections = build_sections(&cfg, mode);
    if sections.is_empty() {
        if mode == "no-defaults" {
            println!("All configurations are using default values.");
        }
        return 0;
    }
    let width = sections.iter().flat_map(|s| s.entries.iter().map(|(k, v, _)| format!("{} = {}", k, v).len())).max().unwrap_or(0) + 1;
    for s in &sections {
        println!("{:<width$}", format!("[{}]", s.name), width = width);
        for (k, v, src) in &s.entries {
            println!("{:<width$}{}", format!("{} = {}", k, v), src, width = width);
        }
        println!();
    }
    0
}

fn config_get(cfg: &Config, key: &str) -> i32 {
    let (section, k) = match key.split_once('.') {
        Some((a, b)) => (a, Some(b)),
        None => (key, None),
    };
    let defaults = default_rule_values();
    if section.eq_ignore_ascii_case("global") {
        let g = &cfg.global;
        let kn = k.map(crate::config::norm_key);
        let gsrc = |k: &str| g.sources.get(k).map(|s| format!("[from {}]", s)).unwrap_or_else(|| "[from default]".to_string());
        let pairs: Vec<(&str, String)> = vec![
            ("enable", fmt_value(&Value::Array(g.enable.iter().map(|x| Value::String(x.clone())).collect()))),
            ("disable", fmt_value(&Value::Array(g.disable.iter().map(|x| Value::String(x.clone())).collect()))),
            ("exclude", fmt_value(&Value::Array(g.exclude.iter().map(|x| Value::String(x.clone())).collect()))),
            ("include", fmt_value(&Value::Array(g.include.iter().map(|x| Value::String(x.clone())).collect()))),
            ("respect-gitignore", g.respect_gitignore.to_string()),
            ("line-length", g.line_length.to_string()),
            ("flavor", flavor_display(&g.flavor)),
        ];
        match kn {
            None => {
                for (pk, pv) in pairs {
                    println!("global.{} = {} {}", pk, pv, gsrc(pk));
                }
                0
            }
            Some(kn) => {
                for (pk, pv) in pairs {
                    if pk == kn {
                        println!("global.{} = {} {}", pk, pv, gsrc(pk));
                        return 0;
                    }
                }
                eprintln!("Unknown global key: {}", k.unwrap_or(""));
                2
            }
        }
    } else {
        let id = match crate::rules::resolve_rule(section) {
            Some(r) => r,
            None => {
                eprintln!("Unknown rule: {}", section);
                return 2;
            }
        };
        let def = defaults.iter().find(|(d, _)| *d == id).map(|(_, v)| v.clone()).unwrap_or_default();
        let user = cfg.rules.get(id);
        let print_key = |k: &str| -> bool {
            let kn = crate::config::norm_key(k);
            if let Some(v) = user.and_then(|u| u.values.get(&kn)) {
                let src = user.and_then(|u| u.sources.get(&kn).cloned()).unwrap_or_else(|| "project config".to_string());
                println!("{}.{} = {} [from {}]", id, kn, fmt_value(v), src);
                return true;
            }
            if let Some((_, v)) = def.iter().find(|(dk, _)| *dk == kn) {
                println!("{}.{} = {} [from default]", id, kn, fmt_value(v));
                return true;
            }
            false
        };
        match k {
            Some(k) => {
                if print_key(k) {
                    0
                } else {
                    eprintln!("Unknown key '{}' for rule {}", k, id);
                    2
                }
            }
            None => {
                let mut keys: Vec<String> = def.iter().map(|(k, _)| k.to_string()).collect();
                if let Some(u) = user {
                    for k in u.values.keys() {
                        if !keys.contains(k) {
                            keys.push(k.clone());
                        }
                    }
                }
                keys.sort();
                for k in keys {
                    print_key(&k);
                }
                0
            }
        }
    }
}

fn config_json(cfg: &Config) -> i32 {
    let g = &cfg.global;
    let mut rules_map = serde_json::Map::new();
    for (id, rc) in &cfg.rules {
        let mut m = serde_json::Map::new();
        for (k, v) in &rc.values {
            m.insert(k.clone(), toml_to_json(v));
        }
        rules_map.insert(id.clone(), serde_json::Value::Object(m));
    }
    let mut root = serde_json::Map::new();
    root.insert(
        "global".into(),
        serde_json::json!({
            "enable": g.enable, "disable": g.disable, "exclude": g.exclude, "include": g.include,
            "respect-gitignore": g.respect_gitignore, "line-length": g.line_length,
            "fixable": g.fixable, "unfixable": g.unfixable, "flavor": g.flavor.to_lowercase(),
            "force-exclude": g.force_exclude, "cache": g.cache
        }),
    );
    let mut pfi = serde_json::Map::new();
    for (k, v) in &cfg.per_file_ignores {
        pfi.insert(k.clone(), serde_json::json!(v));
    }
    root.insert("per-file-ignores".into(), serde_json::Value::Object(pfi));
    let mut pff = serde_json::Map::new();
    for (k, v) in &cfg.per_file_flavor {
        pff.insert(k.clone(), serde_json::json!(v));
    }
    root.insert("per-file-flavor".into(), serde_json::Value::Object(pff));
    root.insert(
        "code-block-tools".into(),
        serde_json::json!({
            "enabled": false, "normalize-language": "linguist", "on-error": "fail",
            "on-missing-language-definition": "ignore", "on-missing-tool-binary": "ignore",
            "timeout": 30000, "languages": {}, "language-aliases": {}, "tools": {}
        }),
    );
    for (k, v) in rules_map {
        root.insert(k, v);
    }
    println!("{}", serde_json::to_string_pretty(&serde_json::Value::Object(root)).unwrap());
    0
}

pub fn toml_to_json(v: &Value) -> serde_json::Value {
    match v {
        Value::String(s) => serde_json::Value::String(s.clone()),
        Value::Integer(i) => serde_json::Value::Number((*i).into()),
        Value::Float(f) => serde_json::Number::from_f64(*f).map(serde_json::Value::Number).unwrap_or(serde_json::Value::Null),
        Value::Boolean(b) => serde_json::Value::Bool(*b),
        Value::Array(a) => serde_json::Value::Array(a.iter().map(toml_to_json).collect()),
        Value::Table(t) => serde_json::Value::Object(t.iter().map(|(k, v)| (k.clone(), toml_to_json(v))).collect()),
        Value::Datetime(d) => serde_json::Value::String(d.to_string()),
    }
}
