pub fn rule(sub: &ArgMatches) -> i32 {
    let format = sub.get_one::<String>("output_format").map(|s| s.as_str()).unwrap_or("text");
    if sub.get_flag("list_categories") {
        let mut cats: Vec<(&str, usize)> = Vec::new();
        for m in RULES {
            if let Some(c) = cats.iter_mut().find(|(c, _)| *c == m.category) {
                c.1 += 1;
            } else {
                cats.push((m.category, 1));
            }
        }
        cats.sort();
        if format == "json" {
            let v: Vec<serde_json::Value> = cats.iter().map(|(c, n)| serde_json::json!({"name": c, "count": n})).collect();
            println!("{}", serde_json::to_string_pretty(&v).unwrap());
            return 0;
        }
        println!("Available categories:");
        for (c, n) in cats {
            println!("  {} ({} rules)", c, n);
        }
        return 0;
    }
    let fixable = sub.get_flag("fixable");
    let category = sub.get_one::<String>("category").map(|s| s.as_str());
    if let Some(c) = category {
        let valid: Vec<&str> = {
            let mut v: Vec<&str> = RULES.iter().map(|m| m.category).collect();
            v.sort();
            v.dedup();
            v
        };
        if !valid.contains(&c) {
