    if let Some(r) = sub.get_one::<String>("rule") {
        let id = match rules::resolve_rule(r) {
            Some(id) => id,
            None => {
                eprintln!("Rule '{}' not found.", r);
                return 2;
            }
        };
        let m = rules::meta(id).unwrap();
        match format {
            "json" => println!("{}", serde_json::to_string_pretty(&rule_json(m)).unwrap()),
            "json-lines" => println!("{}", serde_json::to_string(&rule_json(m)).unwrap()),
            _ => {
                println!("{} - {}", m.id, m.summary);
                println!();
                println!("Name: {}", m.name);
                if !m.aliases.is_empty() {
                    println!("Aliases: {}", m.aliases.join(", "));
                }
                println!("Category: {}", m.category);
                println!("Fix: {}", fix_desc(m.fix));
                println!("Documentation: https://rumdl.dev/{}/", m.id.to_lowercase());
            }
        }
        return 0;
    }
    let list: Vec<&rules::RuleMeta> = RULES.iter().filter(|m| !fixable || m.fix == FixAvail::Always).filter(|m| category.map(|c| c == m.category).unwrap_or(true)).collect();
    match format {
        "json" => {
            let v: Vec<serde_json::Value> = list.iter().map(|m| rule_json(m)).collect();
            println!("{}", serde_json::to_string_pretty(&v).unwrap());
        }
        "json-lines" => {
            for m in &list {
                println!("{}", serde_json::to_string(&rule_json(m)).unwrap());
            }
        }
        _ => {
            let mut filters = Vec::new();
            if fixable {
                filters.push("fixable".to_string());
            }
            if let Some(c) = category {
                filters.push(format!("category={}", c));
            }
            if filters.is_empty() {
                println!("Available rules:");
            } else {
                println!("Available rules ({}):", filters.join(", "));
            }
            for m in &list {
                println!("  {} - {}", m.id, m.summary);
            }
            println!();
            println!("Total: {} rules", list.len());
        }
    }
    0
}

