        for s in ["bash", "elvish", "fish", "powershell", "zsh"] {
            println!("  {}", s);
        }
        return 0;
    }
    let shell = match sub.get_one::<String>("shell") {
        Some(s) => s.clone(),
        None => {
            let env = std::env::var("SHELL").unwrap_or_default();
            let name = std::path::Path::new(&env).file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
            if ["bash", "elvish", "fish", "powershell", "zsh"].contains(&name.as_str()) {
                name
            } else {
                eprintln!("Error: Could not detect shell from $SHELL. Please specify one of: bash, elvish, fish, powershell, zsh");
                return 2;
            }
        }
    };
    use clap_complete::Shell;
    let sh = match shell.as_str() {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        _ => Shell::Zsh,
    };
    let mut cmd = crate::cli::build_cli();
    clap_complete::generate(sh, &mut cmd, "rumdl", &mut std::io::stdout());
    0
}

pub fn schema(sub: &ArgMatches) -> i32 {
