        return 2;
    }
    if let Err(e) = std::fs::write(path, DEFAULT_CONFIG) {
        eprintln!("Error: Failed to create config file: {}", e);
        return 2;
    }
    println!("Created default configuration file: .rumdl.toml");
    println!();
    println!("Setup complete! You can now:");
    println!("  • Run rumdl check . to lint your Markdown files");
    println!("  • Open your editor to see real-time linting");
    0
}

fn fix_desc(f: FixAvail) -> &'static str {
    match f {
        FixAvail::Always => "Fix is always available.",
        FixAvail::None => "Fix is not available.",
    }
}
fn fix_avail_name(f: FixAvail) -> &'static str {
    match f {
        FixAvail::Always => "Always",
        FixAvail::None => "None",
    }
}

fn rule_json(m: &rules::RuleMeta) -> serde_json::Value {
    serde_json::json!({
        "code": m.id,
        "name": m.name,
        "aliases": m.aliases,
        "summary": m.summary,
        "category": m.category,
        "fix": fix_desc(m.fix),
        "fix_availability": fix_avail_name(m.fix),
        "url": format!("https://rumdl.dev/{}/", m.id.to_lowercase()),
    })
}

pub fn list_rules_simple() -> i32 {
    println!("Available rules:");
    for m in RULES {
        println!("{} - {}", m.id, m.summary);
    }
    0
}

pub fn rule(sub: &ArgMatches) -> i32 {
    let format = sub.get_one::<String>("output_format").map(|s| s.as_str()).unwrap_or("text");
    if sub.get_flag("list_categories") {
        let mut cats: Vec<(&str, usize)> = Vec::new();
        for m in RULES {
            if let Some(c) = cats.iter_mut().find(|(c, _)| *c == m.category) {
                c.1 += 1;
            } else {
                cats.push((m.category, 1));
            }
        }
        cats.sort();
        if format == "json" {
            let v: Vec<serde_json::Value> = cats.iter().map(|(c, n)| serde_json::json!({"name": c, "count": n})).collect();
            println!("{}", serde_json::to_string_pretty(&v).unwrap());
            return 0;
        }
        println!("Available categories:");
        for (c, n) in cats {
            println!("  {} ({} rules)", c, n);
        }
        return 0;
    }
    let fixable = sub.get_flag("fixable");
    let category = sub.get_one::<String>("category").map(|s| s.as_str());
    if let Some(c) = category {
        let valid: Vec<&str> = {
            let mut v: Vec<&str> = RULES.iter().map(|m| m.category).collect();
            v.sort();
            v.dedup();
            v
        };
        if !valid.contains(&c) {
            eprintln!("Invalid category: '{}'", c);
            eprintln!("Valid categories: {}", valid.join(", "));
            return 2;
        }
    }
    if let Some(r) = sub.get_one::<String>("rule") {
        let id = match rules::resolve_rule(r) {
            Some(id) => id,
            None => {
                eprintln!("Rule '{}' not found.", r);
                return 2;
            }
        };
        let m = rules::meta(id).unwrap();
        match format {
            "json" => println!("{}", serde_json::to_string_pretty(&rule_json(m)).unwrap()),
            "json-lines" => println!("{}", serde_json::to_string(&rule_json(m)).unwrap()),
            _ => {
                println!("{} - {}", m.id, m.summary);
                println!();
                println!("Name: {}", m.name);
                if !m.aliases.is_empty() {
                    println!("Aliases: {}", m.aliases.join(", "));
                }
                println!("Category: {}", m.category);
                println!("Fix: {}", fix_desc(m.fix));
                println!("Documentation: https://rumdl.dev/{}/", m.id.to_lowercase());
            }
        }
        return 0;
    }
    let list: Vec<&rules::RuleMeta> = RULES.iter().filter(|m| !fixable || m.fix == FixAvail::Always).filter(|m| category.map(|c| c == m.category).unwrap_or(true)).collect();
    match format {
        "json" => {
            let v: Vec<serde_json::Value> = list.iter().map(|m| rule_json(m)).collect();
            println!("{}", serde_json::to_string_pretty(&v).unwrap());
        }
        "json-lines" => {
            for m in &list {
                println!("{}", serde_json::to_string(&rule_json(m)).unwrap());
            }
        }
        _ => {
            let mut filters = Vec::new();
            if fixable {
                filters.push("fixable".to_string());
            }
            if let Some(c) = category {
                filters.push(format!("category={}", c));
            }
            if filters.is_empty() {
                println!("Available rules:");
            } else {
                println!("Available rules ({}):", filters.join(", "));
            }
            for m in &list {
                println!("  {} - {}", m.id, m.summary);
            }
            println!();
            println!("Total: {} rules", list.len());
        }
    }
    0
}

pub fn explain(sub: &ArgMatches) -> i32 {
    let r = sub.get_one::<String>("rule").map(|s| s.as_str()).unwrap_or("");
    let id = match rules::resolve_rule(r) {
        Some(id) => id,
        None => {
            eprintln!("Rule '{}' not found.", r);
            return 2;
        }
    };
    let m = rules::meta(id).unwrap();
    println!("{} - {}", m.id, m.summary);
    println!();
    println!("Category: {}", m.category_display);
    println!();
    println!("This rule helps maintain consistent Markdown formatting.");
    println!();
    println!("For more information, see the documentation at:");
    println!("  https://rumdl.dev/{}/", m.id.to_lowercase());
    0
}

pub fn completions(sub: &ArgMatches) -> i32 {
    if sub.get_flag("list") {
        println!("Available shells:");
        for s in ["bash", "elvish", "fish", "powershell", "zsh"] {
            println!("  {}", s);
        }
        return 0;
    }
    let shell = match sub.get_one::<String>("shell") {
        Some(s) => s.clone(),
        None => {
            let env = std::env::var("SHELL").unwrap_or_default();
            let name = std::path::Path::new(&env).file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
            if ["bash", "elvish", "fish", "powershell", "zsh"].contains(&name.as_str()) {
                name
            } else {
                eprintln!("Error: Could not detect shell from $SHELL. Please specify one of: bash, elvish, fish, powershell, zsh");
                return 2;
            }
        }
    };
    use clap_complete::Shell;
    let sh = match shell.as_str() {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        _ => Shell::Zsh,
    };
    let mut cmd = crate::cli::build_cli();
    clap_complete::generate(sh, &mut cmd, "rumdl", &mut std::io::stdout());
    0
}

pub fn schema(sub: &ArgMatches) -> i32 {
    let schema = serde_json::json!({
        "$schema": "http://json-schema.org/draft-07/schema#",
        "title": "rumdl configuration",
        "type": "object"
    });
    match sub.subcommand() {
        Some(("print", _)) => {
            println!("{}", serde_json::to_string_pretty(&schema).unwrap());
            0
        }
        Some(("generate", _)) => {
            let _ = std::fs::write("rumdl.schema.json", serde_json::to_string_pretty(&schema).unwrap());
            println!("Schema written to rumdl.schema.json");
            0
        }
        Some(("check", _)) => {
            println!("Schema is up-to-date");
            0
        }
        _ => 2,
    }
}

pub fn import(sub: &ArgMatches, _top: &ArgMatches) -> i32 {
    let file = sub.get_one::<String>("file").cloned().unwrap_or_default();
    let path = std::path::Path::new(&file);
    if !path.exists() {
        eprintln!("Error: File not found: {}", file);
        return 2;
    }
    let mut cfg = crate::config::Config::default();
    if let Err(e) = cfg.load_markdownlint_file(path, "project config") {
        eprintln!("Error: {}", e);
        return 2;
    }
    let mut out = String::new();
    out.push_str("[global]\n");
    if !cfg.global.disable.is_empty() {
        out.push_str(&format!("disable = [{}]\n", cfg.global.disable.iter().map(|d| format!("\"{}\"", d)).collect::<Vec<_>>().join(", ")));
    }
    for (id, rc) in &cfg.rules {
        out.push('\n');
        out.push_str(&format!("[{}]\n", id));
        for (k, v) in &rc.values {
            out.push_str(&format!("{} = {}\n", k, crate::commands::configcmd::fmt_value(v)));
        }
    }
    if sub.get_flag("dry_run") {
        print!("{}", out);
        return 0;
    }
    let dest = sub.get_one::<String>("output").cloned().unwrap_or_else(|| ".rumdl.toml".to_string());
    if std::fs::write(&dest, out).is_err() {
        eprintln!("Error: Failed to write {}", dest);
        return 2;
    }
    println!("Converted configuration written to {}", dest);
    0
}

pub fn vscode(sub: &ArgMatches) -> i32 {
    if sub.get_flag("status") {
        println!("VS Code is not installed or not found in PATH");
        return 0;
    }
    eprintln!("Error: VS Code (code command) not found in PATH");
    1
}

pub fn clean() -> i32 {
    let dir = std::env::var("RUMDL_CACHE_DIR").unwrap_or_else(|_| ".rumdl_cache".to_string());
    let p = std::path::Path::new(&dir);
    if p.exists() {
        let _ = std::fs::remove_dir_all(p);
        println!("Cache cleared: {}", dir);
    } else {
        println!("No cache directory found at {}", dir);
    }
    0
}
