pub fn byte_index_for_col(s: &str, col: usize) -> usize {
    let mut c = 0;
    for (bi, ch) in s.char_indices() {
        if c >= col {
            return bi;
        }
        match ch {
            ' ' => c += 1,
            '\\t' => c = (c / 4 + 1) * 4,
            _ => return bi,
        }
    }
    s.len()
}

