        let pairs: Vec<(&str, &str, String)> = vec![
            ("enable", "enable", fmt_value(&Value::Array(g.enable.iter().map(|x| Value::String(x.clone())).collect()))),
            ("disable", "disable", fmt_value(&Value::Array(g.disable.iter().map(|x| Value::String(x.clone())).collect()))),
            ("exclude", "exclude", fmt_value(&Value::Array(g.exclude.iter().map(|x| Value::String(x.clone())).collect()))),
            ("include", "include", fmt_value(&Value::Array(g.include.iter().map(|x| Value::String(x.clone())).collect()))),
            ("respect_gitignore", "respect-gitignore", g.respect_gitignore.to_string()),
            ("flavor", "flavor", format!("\\"{}\\"", g.flavor.to_lowercase())),
        ];
        for (pk, sk, pv) in pairs {
            if pk == k {
                println!("global.{} = {} {}", pk, pv, gsrc(sk));
                return 0;
            }
        }
