    let mut current = content.to_string();
    let mut converged = false;
    let mut last_changed: Vec<&'static str> = Vec::new();
    for _pass in 0..100 {
        let before = current.clone();
        let mut changed_now: Vec<&'static str> = Vec::new();
        for r in rule_objs {
            let ctx = Ctx::new(&current);
            let inline = parse_inline_config(&ctx);
            let honours_inline = inline_enabled || SELF_INLINE_RULES.contains(&r.name());
            if honours_inline && is_disabled(&inline.file_disabled, r.name()) {
                continue;
            }
            let ws = r.check(&ctx);
            let ws: Vec<Warning> = ws.into_iter().filter(|w| {
                let li = w.line.saturating_sub(1);
                !(honours_inline && li < inline.disabled_per_line.len() && is_disabled(&inline.disabled_per_line[li], w.rule) && !(li < ctx.lines.len() && ctx.lines[li].in_code))
            }).collect();
            if ws.iter().all(|w| w.fix.is_none()) {
                continue;
