fn build_nameset(patterns: &[String]) -> Option<globset::GlobSet> {
    if patterns.is_empty() {
        return None;
    }
    let mut b = globset::GlobSetBuilder::new();
    for p in patterns {
        let p = p.trim().trim_end_matches('/');
        if p.is_empty() || p.contains('/') {
            continue;
        }
        if let Ok(g) = globset::GlobBuilder::new(p).literal_separator(false).build() {
            b.add(g);
        }
    }
    b.build().ok()
}

/// Which exclude pattern (expanded form) matches the given relative path, if any.
fn matching_pattern(patterns: &[String], rel: &str) -> Option<String> {
    for p in patterns {
        let pt = p.trim().trim_end_matches('/');
        if pt.is_empty() {
            continue;
        }
        for cand in [pt.to_string(), format!("{}/**", pt)] {
            if let Ok(g) = globset::GlobBuilder::new(&cand).literal_separator(false).build() {
                if g.compile_matcher().is_match(rel) {
                    return Some(cand);
                }
            }
        }
    }
    None
}

