    if !rule_objs.iter().any(|r| r.name() == "MD057") {
        return vec![];
    }
    let base = f.parent().map(|p| if p.as_os_str().is_empty() { PathBuf::from(".") } else { p.to_path_buf() }).unwrap_or_else(|| PathBuf::from("."));
    let ctx = crate::ctx::Ctx::new(content);
    let inline_cfg = linter::parse_inline_config(&ctx);
    let mut out = Vec::new();
    if inline_cfg.file_disabled.contains("*") || inline_cfg.file_disabled.contains("MD057") {
        return out;
    }
    let has_md051 = rule_objs.iter().any(|r| r.name() == "MD051");
    let canon: Vec<PathBuf> = all_files.iter().filter_map(|p| std::fs::canonicalize(p).ok()).collect();
    let mut frag_warnings: Vec<Warning> = Vec::new();
    let mut plain_warnings: Vec<Warning> = Vec::new();
