            if lk.kind != crate::inline::LinkKind::Inline || lk.image {
                continue;
            }
            let mut u = lk.url.trim().to_string();
            if u.starts_with('<') && u.ends_with('>') {
                u = u[1..u.len() - 1].to_string();
            }
